INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('codecrafters-io/frontend/fix-lint', 'community', 'codecrafters-io', 'frontend', 'codecrafters-io/frontend', 'fix-lint', 0, 0, 23, '2026-03-08T01:57:15.441Z', '2026-03-08T02:07:44.457Z', '8cad805e81e6e8c8eb71313cc4a0453d80c86cc95af68401a6c368e7f7003c73', '{"id":"codecrafters-io/frontend/fix-lint","name":"fix-lint","description":{"en":"The fix-lint skill helps developers rebuild complex systems from scratch and fix linter failures. It provides a step-by-step process to resolve issues using the `bun run lint:fix` command.","zh":"fix-lint技能可以帮助您重建复杂系统并修复lint错误。使用Bun工具运行lint:fix命令即可开始","ja":"fix-lintスキルは複雑なシステムを再構築し、lintエラーを修復するのに役立ちます。Bunツールを使用してlint:fixコマンドを実行してください","ko":"fix-lint 기능은 복잡한 시스템을 재구성하고 lint 오류를 수정하는 데 도움이 됩니다. Bun 도구를 사용하여 lint:fix 명령을 실행하세요","es":"Fix-lint es una herramienta que permite reconstruir sistemas complejos desde cero y solucionar errores de lint. Sigue los pasos para corregir los errores","fr":"Fix-lint est un outil qui permet de reconstruire des systèmes complexes depuis zéro et de résoudre les erreurs de lint. Suivez les étapes pour corriger les erreurs","de":"Fix-lint ist ein Tool, das die Neuerrichtung komplexer Systeme von Grund auf und die Behebung von Lint-Fehlern ermöglicht. Befolgen Sie die Schritte, um die Fehler zu korrigieren","pt":"O fix-lint é uma ferramenta para corrigir falhas de linter em sistemas complexos. Ele executa comandos como `bun run lint:fix` para identificar e corrigir problemas.","ru":"ИИ Агент fix-lint - это инструмент для исправления ошибок линтера в сложных системах. Он выполняет команды, такие как `bun run lint:fix`, для выявления и исправления проблем.","ar":"أداة fix-lint هي أداة لتصحيح أخطاء لينتر في الأنظمة المعقدة. وهي تنفذ أوامر مثل `bun run lint:fix` لتحديد ومعالجة المشاكل."},"seo":{"title":{"en":"fix-lint: Linter Failure Setup Guide | AI Agent Skill","zh":"fix-lint Setup Guide: 使用Bun运行lint修复","ja":"fix-lint セットアップガイド: Bunでlintを修復する","ko":"fix-lint 설정 가이드: Bun을 사용하여 lint 오류 수정","es":"Guía de configuración de fix-lint para solucionar errores...","fr":"Guide de configuration de fix-lint pour résoudre les erre...","de":"Konfigurationsleitfaden für fix-lint zur Behebung von Lin...","pt":"Guia de Configuração do fix-lint: Corrigindo Falhas de Li...","ru":"ИИ Агенты: Настройка fix-lint для Исправления Ошибок Линтера","ar":"إعداد أداة fix-lint: إصلاح أخطاء لينتر بسرعة"},"description":{"en":"Solve linter issues with ease! Learn how to use fix-lint to rebuild complex systems and fix failures with a simple `bun run lint:fix` command.","zh":"了解如何使用fix-lint技能和Bun工具修复复杂系统中的lint错误","ja":"fix-lintスキルとBunツールを使用して複雑なシステムのlintエラーを修復する方法を学習します","ko":"fix-lint 기능과 Bun 도구를 사용하여 복잡한 시스템의 lint 오류를 수정하는 방법에 대해 알아보세요","es":"Aprenda a solucionar errores de lint con fix-lint. Siga nuestros pasos para reconstruir sistemas complejos desde cero","fr":"Découvrez comment résoudre les erreurs de lint avec fix-lint. Suivez nos étapes pour reconstruire des systèmes complexes desde zéro","de":"Erfahren Sie, wie Sie Lint-Fehler mit fix-lint beheben. Befolgen Sie unsere Schritte, um komplexe Systeme von Grund auf neu zu erstellen","pt":"Aprenda a configurar o fix-lint para corrigir falhas de linter em sistemas complexos. Siga nossos passos para garantir a integridade do seu código.","ru":"Узнайте, как настроить fix-lint для исправления ошибок линтера в сложных системах. Следуйте нашим шагам, чтобы обеспечить целостность вашего кода.","ar":"تعلم كيفية إعداد أداة fix-lint لإصلاح أخطاء لينتر في الأنظمة المعقدة. اتبع خطواتنا لضمان سلامة كودك."},"definition":{"en":"fix-lint is a skill that enables AI agents to rebuild complex systems and resolve linter failures using a series of commands and review processes.","zh":"fix-lint是一种AI工具，用于修复复杂系统中的lint错误","ja":"fix-lintは、複雑なシステムのlintエラーを修復するためのAIエージェントです","ko":"fix-lint는 복잡한 시스템의 lint 오류를 수정하는 데 사용되는 AI 도구입니다","es":"Fix-lint es una herramienta de línea de comandos que ejecuta `bun run lint:fix` para solucionar errores de lint","fr":"Fix-lint est un outil en ligne de commande qui exécute `bun run lint:fix` pour résoudre les erreurs de lint","de":"Fix-lint ist ein Kommandozeilen-Tool, das `bun run lint:fix` ausführt, um Lint-Fehler zu beheben","pt":"O fix-lint é uma ferramenta de linha de comando que corrige falhas de linter em sistemas complexos.","ru":"ИИ Агент fix-lint - это командная утилита, которая исправляет ошибки линтера в сложных системах.","ar":"أداة fix-lint هي أداة سطر أوامر تصحيح أخطاء لينتر في الأنظمة المعقدة."},"features":{"en":["Runs `bun run lint:fix` to identify and fix linter failures","Reviews output for failures and provides a step-by-step resolution process","Fixes one issue at a time for efficient debugging","Re-runs `bun run lint:fix` to confirm all issues are resolved","Supports iterative debugging for persistent failures"],"zh":["使用Bun工具运行lint:fix命令","修复复杂系统中的lint错误","逐步修复lint问题","重新运行lint:fix命令以确认所有问题都已修复","支持CLI命令"],"ja":["Bunツールを使用してlint:fixコマンドを実行する","複雑なシステムのlintエラーを修復する","lint問題を逐一修復する","lint:fixコマンドを再実行してすべての問題が修復されたことを確認する","CLIコマンドに対応"],"ko":["Bun 도구를 사용하여 lint:fix 명령을 실행","복잡한 시스템의 lint 오류를 수정","lint 문제를 하나씩 수정","lint:fix 명령을 다시 실행하여 모든 문제가 수정되었는지 확인","CLI 명령어 지원"],"es":["Ejecuta `bun run lint:fix` para solucionar errores de lint","Revisa la salida para detectar errores","Corrige un error a la vez","Vuelve a ejecutar `bun run lint:fix` para confirmar que todos los errores están corregidos","Repite los pasos hasta que no queden errores"],"fr":["Exécute `bun run lint:fix` pour résoudre les erreurs de lint","Vérifie la sortie pour détecter les erreurs","Corrige une erreur à la fois","Réexécute `bun run lint:fix` pour confirmer que toutes les erreurs sont corrigées","Répète les étapes jusqu''à ce qu''il ne reste plus d''erreurs"],"de":["Führt `bun run lint:fix` aus, um Lint-Fehler zu beheben","Überprüft die Ausgabe, um Fehler zu erkennen","Korrigiert einen Fehler nach dem anderen","Führt `bun run lint:fix` erneut aus, um zu bestätigen, dass alle Fehler korrigiert sind","Wiederholt die Schritte, bis keine Fehler mehr vorhanden sind"],"pt":["Executa o comando `bun run lint:fix` para identificar falhas de linter","Fornece saídas detalhadas para ajudar a corrigir problemas","Permite corrigir problemas um a um para garantir a integridade do código","Executa comandos de forma iterativa para confirmar a correção de todos os problemas","Suporta a utilização de tecnologias como Bun e lint"],"ru":["Выполняет команду `bun run lint:fix` для выявления ошибок линтера","Предоставляет подробные выходные данные для помощи в исправлении проблем","Позволяет исправлять проблемы один за другим, чтобы обеспечить целостность кода","Выполняет команды итеративно, чтобы подтвердить исправление всех проблем","Поддерживает использование технологий, таких как Bun и lint"],"ar":["تنفذ الأمر `bun run lint:fix` لتحديد أخطاء لينتر","توفر مخرجات مفصلة للمساعدة في معالجة المشاكل","تسمح بمعالجة المشاكل واحد تلو الآخر لضمان سلامة الكود","تنفذ أوامر بشكل متكرر ل確認 معالجة جميع المشاكل","تدعم استخدام تقنيات مثل Bun و lint"]},"keywords":{"en":["how to use fix-lint","fix-lint alternative","fix-lint setup guide","fix-lint vs eslint","what is fix-lint","fix-lint install","bun run lint:fix command","linter failure resolution","fix-lint for AI agents","debugging with fix-lint"],"zh":["fix-lint","Bun工具","lint错误修复","复杂系统重建","AI工具","代码优化","编程开发","软件开发"],"ja":["fix-lint","Bunツール","lintエラー修復","複雑なシステム再構築","AIエージェント","コード最適化","プログラミング開発","ソフトウェア開発"],"ko":["fix-lint","Bun 도구","lint 오류 수정","복잡한 시스템 재구성","AI 도구","코드 최적화","프로그래밍 개발","소프트웨어 개발"],"es":["fix-lint","herramientas de línea de comandos","solución de errores de lint","reconstrucción de sistemas complejos","bun run lint:fix","desarrollo de software","herramientas de desarrollo","solución de problemas de lint"],"fr":["fix-lint","outils en ligne de commande","résolution des erreurs de lint","reconstruction de systèmes complexes","bun run lint:fix","développement de logiciels","outils de développement","résolution de problèmes de lint"],"de":["fix-lint","Kommandozeilen-Tools","Behebung von Lint-Fehlern","Neuerstellung komplexer Systeme","bun run lint:fix","Software-Entwicklung","Entwicklungs-Tools","Fehlerbehebung bei Lint"],"pt":["fix-lint","corrigir falhas de linter","configurar fix-lint","bun run lint:fix","lint de código","ferramentas de desenvolvimento","desenvolvimento de software","análise de código"],"ru":["ИИ Агент fix-lint","исправление ошибок линтера","настройка fix-lint","bun run lint:fix","линтер кода","инструменты разработки","разработка программного обеспечения","анализ кода"],"ar":["أداة fix-lint","إصلاح أخطاء لينتر","إعداد أداة fix-lint","bun run lint:fix","لينتر كود","أدوات تطوير","تطوير البرمجيات","تحليل الكود"]}},"owner":"codecrafters-io","repo":"frontend","repoPath":"codecrafters-io/frontend","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.441Z","topics":[],"category":"community","skillMd":{"name":"fix-lint","description":"Run the frontend linter, analyze failures, and fix them iteratively. Use when linting fails, lint errors appear, or the user asks to fix lint issues in the frontend repo.","bodyPreview":"# Fix Linter Failures\n\n## Steps\n\n1. Run `bun run lint:fix`.\n2. Review the output for failures.\n3. Fix one issue at a time.\n4. Re-run `bun run lint:fix` to confirm all issues are fixed.\n5. If failures remain, repeat steps 3 and 4.","body":"# Fix Linter Failures\n\n## Steps\n\n1. Run `bun run lint:fix`.\n2. Review the output for failures.\n3. Fix one issue at a time.\n4. Re-run `bun run lint:fix` to confirm all issues are fixed.\n5. If failures remain, repeat steps 3 and 4.\n"},"lastSynced":"2026-03-08T02:07:44.457Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Refactoring Agents needing automated linting fixes using the `bun run lint:fix` command.","zh":"适用于需要使用 `bun run lint:fix` 命令自动修复代码格式的代码重构代理。","ja":"コードリファクタリングエージェントが `bun run lint:fix` コマンドを使用して自動的にlintの修正を行う必要がある場合に最適です。","ko":"코드 재구성 에이전트가 `bun run lint:fix` 명령을 사용하여 자동으로 린트 수정을 수행하는 데 적합합니다.","es":"Perfecto para agentes de refactorización de código que necesitan correcciones de linting automatizadas utilizando el comando `bun run lint:fix`.","fr":"Parfait pour les agents de refactorisation de code nécessitant des corrections de linting automatisées à l''aide de la commande `bun run lint:fix`.","de":"Perfekt für Code-Refactoring-Agenten, die automatisierte Linting-Korrekturen mit dem Befehl `bun run lint:fix` benötigen.","pt":"Perfeito para Agentes de Refatoração de Código que precisam de correções de linting automatizadas usando o comando `bun run lint:fix`.","ru":"Идеально подходит для агентов рефакторинга кода, которым необходимы автоматические исправления линтинга с помощью команды `bun run lint:fix`.","ar":"مثالي لعمليات إعادة هيكلة الكود التي تحتاج إلى تصحيحات لينتينغ آلية باستخدام الأمر `bun run lint:fix`."},"recommendation":{"en":"Empowers agents to resolve linter failures and rebuild complex systems from scratch, providing a step-by-step process to fix issues using the `bun run lint:fix` command and reviewing output for failures.","zh":"赋予代理解决linter失败并从头开始重建复杂系统的能力，提供了一步一步的过程来使用 `bun run lint:fix` 命令修复问题并检查输出以查找故障。","ja":"エージェントにlinterの失敗を解決し、スクラッチから複雑なシステムを再構築する力を与え、`bun run lint:fix` コマンドを使用して問題を修正し、出力を確認して失敗を検出するためのステップバイステップのプロセスを提供します。","ko":"에이전트가 린터 실패를 해결하고 처음부터 복잡한 시스템을 다시 구축할 수 있도록 해주며, `bun run lint:fix` 명령을 사용하여 문제를 수정하고 출력을 검토하여 오류를 확인하는 단계별 프로세스를 제공합니다.","es":"Habilita a los agentes a resolver fallas del linter y reconstruir sistemas complejos desde cero, proporcionando un proceso paso a paso para corregir problemas utilizando el comando `bun run lint:fix` y revisar la salida para fallas.","fr":"Permet aux agents de résoudre les échecs du linter et de reconstruire des systèmes complexes à partir de zéro, en fournissant un processus étape par étape pour corriger les problèmes à l''aide de la commande `bun run lint:fix` et en examinant la sortie pour les échecs.","de":"Ermächtigt die Agenten, Linter-Fehler zu beheben und komplexe Systeme von Grund auf neu aufzubauen, indem ein schrittweiser Prozess zur Fehlerbehebung mit dem Befehl `bun run lint:fix` bereitgestellt wird und die Ausgabe auf Fehler überprüft wird.","pt":"Habilita os agentes a resolver falhas de linter e reconstruir sistemas complexos do zero, fornecendo um processo passo a passo para corrigir problemas usando o comando `bun run lint:fix` e revisar a saída para falhas.","ru":"Наделяет агентов возможностью решать проблемы линтера и перестраивать сложные системы с нуля, предоставляя пошаговый процесс для исправления проблем с помощью команды `bun run lint:fix` и проверки вывода на наличие ошибок.","ar":"تمكّن الوكلاء من حل مشاكل لينتينغ وإعادة بناء أنظمة معقدة من الصفر، وتوفير عملية خطوة بخطوة لتصحيح المشكلات باستخدام الأمر `bun run lint:fix` ومراجعة الإخراج للفشل."},"useCases":{"en":["Automating linter failure resolution","Rebuilding complex systems from scratch","Debugging code issues using `bun run lint:fix`"],"zh":["自动解决linter失败","从头开始重建复杂系统","使用 `bun run lint:fix` 调试代码问题"],"ja":["linterの失敗を自動的に解決する","スクラッチから複雑なシステムを再構築する","`bun run lint:fix` を使用してコードの問題をデバッグする"],"ko":["린터 실패를 자동으로 해결한다","처음부터 복잡한 시스템을 다시 구축","`bun run lint:fix`를 사용하여 코드 문제를 디버깅"],"es":["Automatización de la resolución de fallas del linter","Reconstrucción de sistemas complejos desde cero","Depuración de problemas de código con `bun run lint:fix`"],"fr":["Automatisation de la résolution des échecs du linter","Reconstruction de systèmes complexes à partir de zéro","Débogage des problèmes de code avec `bun run lint:fix`"],"de":["Automatisierung der Behebung von Linter-Fehlern","Neuaufbau komplexer Systeme von Grund auf","Fehlerbehebung von Codeproblemen mit `bun run lint:fix`"],"pt":["Automatizar a resolução de falhas de linter","Reconstruir sistemas complexos do zero","Depurar problemas de código usando `bun run lint:fix`"],"ru":["Автоматизировать решение проблем линтера","Перестраивать сложные системы с нуля","Отлаживать проблемы кода с помощью `bun run lint:fix`"],"ar":["أتمتة حل مشاكل لينتينغ","إعادة بناء أنظمة معقدة من الصفر","تصحيح مشاكل الكود باستخدام `bun run lint:fix`"]},"limitations":{"en":["Requires `bun` installation","Limited to fixing linter failures"],"zh":["需要 `bun` 安装","仅限于解决linter失败"],"ja":["`bun` のインストールが必要","linterの失敗を修正することのみに限定される"],"ko":["`bun` 설치가 필요","린터 실패를 수정하는 것만으로 제한"],"es":["Requiere la instalación de `bun`","Limitado a la corrección de fallas del linter"],"fr":["Nécessite l''installation de `bun`","Limité à la correction des échecs du linter"],"de":["Benötigt die Installation von `bun`","Begrenzt auf die Korrektur von Linter-Fehlern"],"pt":["Requer instalação do `bun`","Limitado à correção de falhas de linter"],"ru":["Требует установки `bun`","Ограничен исправлением проблем линтера"],"ar":["يتطلب تثبيت `bun`","محدود بتصحيح مشاكل لينتينغ"]},"version":4},"contentHash":"8cad805e81e6e8c8eb71313cc4a0453d80c86cc95af68401a6c368e7f7003c73","qualityScore":23}');
