INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('codecrafters-io/frontend/fix-lint', 'fix-lint', 'codecrafters-io', 'frontend', 'community', 'fix-lint codecrafters-io frontend community The fix-lint skill helps developers rebuild complex systems from scratch and fix linter failures. It provides a step-by-step process to resolve issues using the `bun run lint:fix` command. fix-lint技能可以帮助您重建复杂系统并修复lint错误。使用Bun工具运行lint:fix命令即可开始 fix-lintスキルは複雑なシステムを再構築し、lintエラーを修復するのに役立ちます。Bunツールを使用してlint:fixコマンドを実行してください fix-lint 기능은 복잡한 시스템을 재구성하고 lint 오류를 수정하는 데 도움이 됩니다. Bun 도구를 사용하여 lint:fix 명령을 실행하세요 Fix-lint es una herramienta que permite reconstruir sistemas complejos desde cero y solucionar errores de lint. Sigue los pasos para corregir los errores Fix-lint est un outil qui permet de reconstruire des systèmes complexes depuis zéro et de résoudre les erreurs de lint. Suivez les étapes pour corriger les erreurs Fix-lint ist ein Tool, das die Neuerrichtung komplexer Systeme von Grund auf und die Behebung von Lint-Fehlern ermöglicht. Befolgen Sie die Schritte, um die Fehler zu korrigieren O fix-lint é uma ferramenta para corrigir falhas de linter em sistemas complexos. Ele executa comandos como `bun run lint:fix` para identificar e corrigir problemas. ИИ Агент fix-lint - это инструмент для исправления ошибок линтера в сложных системах. Он выполняет команды, такие как `bun run lint:fix`, для выявления и исправления проблем. أداة fix-lint هي أداة لتصحيح أخطاء لينتر في الأنظمة المعقدة. وهي تنفذ أوامر مثل `bun run lint:fix` لتحديد ومعالجة المشاكل. how to use fix-lint fix-lint alternative fix-lint setup guide fix-lint vs eslint what is fix-lint fix-lint install bun run lint:fix command linter failure resolution fix-lint for AI agents debugging with fix-lint fix-lint Bun工具 lint错误修复 复杂系统重建 AI工具 代码优化 编程开发 软件开发 Runs `bun run lint:fix` to identify and fix linter failures Reviews output for failures and provides a step-by-step resolution process Fixes one issue at a time for efficient debugging Re-runs `bun run lint:fix` to confirm all issues are resolved Supports iterative debugging for persistent failures fix-lint is a skill that enables AI agents to rebuild complex systems and resolve linter failures using a series of commands and review processes.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ShapeCrawler/ShapeCrawler/class', 'community', 'ShapeCrawler', 'ShapeCrawler', 'ShapeCrawler/ShapeCrawler', 'class', 0, 0, 23, '2026-03-08T01:57:15.441Z', '2026-03-08T02:07:44.488Z', '1610371248a55f56dae07bbfeeac79c3e4c0dfdd678498d68b3d2414301d6ed7', '{"id":"ShapeCrawler/ShapeCrawler/class","name":"class","description":{"en":"The Class skill enables developers to read, modify, and generate PPTX presentations without requiring Microsoft Office, streamlining presentation management for AI agents.","zh":"类是PowerPoint .NET库的核心，用于读取、修改和生成PPTX演示文稿","ja":"クラスはPowerPoint .NETライブラリの中心で、PPTXプレゼンテーションを読み取る、変更する、生成するために使用されます","ko":"클래스는 PowerPoint .NET 라이브러리의 핵심으로 PPTX 프레젠테이션을 읽고, 수정하고, 생성하는 데 사용됩니다","es":"La clase representa una entidad o concepto real y encapsula la lógica necesaria para producir resultados sin depender de datos precalculados","fr":"La classe représente une entité ou un concept réel et encapsule la logique nécessaire pour produire des résultats sans dépendre de données précalculées","de":"Die Klasse repräsentiert eine reale Entität oder ein Konzept und kapselt die notwendige Logik, um Ergebnisse zu erzeugen, ohne von vorab berechneten Daten abhängig zu sein","pt":"Crie classes para manipular apresentações PPTX com a biblioteca .NET, seguindo as melhores práticas de design de classes.","ru":"Создайте классы для работы с презентациями PPTX, используя библиотеку .NET и следуя лучшим практикам проектирования классов.","ar":"انشئ الفئات لتعديل العروض التقديمية PPTX باستخدام مكتبة .NET، متبوعًا بأفضل الممارسات لتصميم الفئات."},"seo":{"title":{"en":"Class: PPTX Presentation Management for AI Agents | AI Ag...","zh":"类设置指南 - PowerPoint .NET 库","ja":"クラス設定ガイド - PowerPoint .NET ライブラリ","ko":"클래스 설정 가이드 - PowerPoint .NET 라이브러리","es":"Guía de configuración de clase para bibliotecas .NET de P...","fr":"Guide de mise en place de classe pour les bibliothèques ....","de":"Einrichtungsleitfaden für Klassen in .NET-Bibliotheken fü...","pt":"Guia de Configuração de Classes para PowerPoint .NET","ru":"Настройка классов для PowerPoint .NET: лучшие практики","ar":"دليل إنشاء الفئات لبرنامج PowerPoint .NET"},"description":{"en":"Discover how to create, modify, and generate PPTX presentations without Microsoft Office using the Class skill - get started now!","zh":"了解如何使用类创建和修改PPTX演示文稿，无需Microsoft Office","ja":"クラスを使用してPPTXプレゼンテーションを作成および変更する方法について学びます","ko":"클래스를 사용하여 PPTX 프레젠테이션을 생성하고 수정하는 방법을 알아보세요","es":"Aprende a crear clases efectivas para leer, modificar y generar presentaciones PPTX con nuestra biblioteca .NET para PowerPoint","fr":"Découvrez comment créer des classes efficaces pour lire, modifier et générer des présentations PPTX avec notre bibliothèque .NET pour PowerPoint","de":"Erfahren Sie, wie Sie effektive Klassen erstellen, um PPTX-Präsentationen mit unserer .NET-Bibliothek für PowerPoint zu lesen, zu bearbeiten und zu generieren","pt":"Aprenda a criar classes para manipular apresentações PPTX sem Microsoft Office, utilizando a biblioteca .NET","ru":"Изучите создание классов для работы с презентациями PPTX без Microsoft Office, используя библиотеку .NET","ar":"تعرف على كيفية إنشاء الفئات لتعديل العروض التقديمية PPTX بدون مكتب مايكروسوفت، باستخدام مكتبة .NET"},"definition":{"en":"Class is a PowerPoint .NET library for managing PPTX presentations, allowing developers to create, modify, and generate presentations programmatically.","zh":"类是代表现实世界实体或概念的编程单元","ja":"クラスは実世界のエンティティまたは概念を表すプログラミング単位です","ko":"클래스는 실제 세계의 엔티티 또는 개념을 나타내는 프로그래밍 단위입니다","es":"Una clase es una representación de una entidad o concepto real que encapsula propiedades y lógica","fr":"Une classe est une représentation d''une entité ou d''un concept réel qui encapsule des propriétés et une logique","de":"Eine Klasse ist eine Darstellung einer realen Entität oder eines Konzepts, das Eigenschaften und Logik kapselt","pt":"Uma classe é uma entidade que representa um conceito ou objeto do mundo real, encapsulando lógica e propriedades.","ru":"Класс — это сущность, представляющая понятие или объект реального мира, инкапсулирующая логику и свойства.","ar":"الفئة هي كيان يمثل مفهومًا أو كائنًا في العالم الحقيقي، وتحتوى على منطق وخصائص."},"features":{"en":["Represents real-world entities or concepts as nouns","Encapsulates entity coordinates using constructors","Derives results from dependencies without relying on pre-calculated data","Follows key design patterns for class creation","Enforces naming conventions for class names"],"zh":["代表现实世界实体或概念","封装构造函数和依赖项","不依赖于预计算数据","支持PPTX演示文稿生成"],"ja":["実世界のエンティティまたは概念を表す","コンストラクタと依存関係をカプセル化する","事前計算データに依存しない","PPTXプレゼンテーション生成をサポート"],"ko":["실제 세계의 엔티티 또는 개념을 나타낸다","생성자와 종속성을 캡슐화한다","사전 계산된 데이터에 의존하지 않는다","PPTX 프레젠테이션 생성을 지원한다"],"es":["Representación de entidades o conceptos reales","Encapsulación de propiedades y lógica","No dependencia de datos precalculados","Compatibilidad con bibliotecas .NET para PowerPoint","Generación de presentaciones PPTX"],"fr":["Représentation d''entités ou de concepts réels","Encapsulation de propriétés et de logique","Pas de dépendance à des données précalculées","Compatibilité avec les bibliothèques .NET pour PowerPoint","Génération de présentations PPTX"],"de":["Darstellung realer Entitäten oder Konzepte","Kapselung von Eigenschaften und Logik","Keine Abhängigkeit von vorab berechneten Daten","Kompatibilität mit .NET-Bibliotheken für PowerPoint","Erzeugung von PPTX-Präsentationen"],"pt":["Representação de entidades do mundo real","Encapsulamento de lógica e propriedades","Criação de classes para manipular apresentações PPTX","Utilização da biblioteca .NET para trabalhar com PPTX","Seguimento das melhores práticas de design de classes"],"ru":["Представление сущностей реального мира","Инкапсуляция логики и свойств","Создание классов для работы с презентациями PPTX","Использование библиотеки .NET для работы с PPTX","Следование лучшим практикам проектирования классов"],"ar":["تمثيل الكيانات في العالم الحقيقي","التغليف المنطقي والخصائص","إنشاء الفئات لتعديل العروض التقديمية PPTX","استخدام مكتبة .NET للعمل مع PPTX","اتباع أفضل الممارسات لتصميم الفئات"]},"keywords":{"en":["how to use class in PPTX management","class alternative to Microsoft Office","class vs PowerPoint API","class install guide for AI agents","class setup for PPTX presentation generation","what is class in .NET library"],"zh":["类设置","PowerPoint .NET 库","PPTX 演示文稿","AIエージェント","类设计模式","构造函数封装"],"ja":["クラス設定","PowerPoint .NET ライブラリ","PPTX プレゼンテーション","AIエージェント","クラス設計パターン","コンストラクタカプセル化"],"ko":["클래스 설정","PowerPoint .NET 라이브러리","PPTX 프레젠테이션","AI 에이전트","클래스 디자인 패턴","생성자 캡슐화"],"es":["clase en programación","bibliotecas .NET para PowerPoint","generación de presentaciones PPTX","programación orientada a objetos","diseño de clases","patrones de diseño"],"fr":["classe en programmation","bibliothèques .NET pour PowerPoint","génération de présentations PPTX","programmation orientée objet","conception de classes","patrons de conception"],"de":["Klasse in der Programmierung",".NET-Bibliotheken für PowerPoint","Erzeugung von PPTX-Präsentationen","objektorientierte Programmierung","Klassenentwurf","Entwurfsmuster"],"pt":["classes para PowerPoint","biblioteca .NET para PPTX","criação de classes","design de classes","manipulação de apresentações PPTX","ИИ Агенты para desenvolvedores","desenvolvimento de aplicativos com .NET"],"ru":["классы для PowerPoint","библиотека .NET для PPTX","создание классов","проектирование классов","обработка презентаций PPTX","ИИ Агенты для разработчиков","разработка приложений с использованием .NET"],"ar":["الفئات لبرنامج PowerPoint","مكتبة .NET للعروض التقديمية PPTX","إنشاء الفئات","تصميم الفئات","تعديل العروض التقديمية PPTX","أدوات الذكاء الاصطناعي للמطورين","تطوير التطبيقات باستخدام .NET"]}},"owner":"ShapeCrawler","repo":"ShapeCrawler","repoPath":"ShapeCrawler/ShapeCrawler","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.441Z","topics":[],"category":"community","skillMd":{"name":"class","description":"Use this skill when creating a new class or asking how to model a new class in ShapeCrawler.","bodyPreview":"# Create Class\n\n## Rule (Key Design Patterns)\n\nWhen creating a new class:\n\n- The class must represent a real-world entity or concept (noun).\n- The constructor must encapsulate the entity’s coordinates: store the properties or underlying object the class uses to refer to that entity.\n- The class must encapsulate all logic required to produce its result; do not rely on pre-calculated data from callers if it can be derived from dependencies.\n\n## Quick Checks\n\n- Class name is a noun, not “-er/-or/-s","body":"# Create Class\n\n## Rule (Key Design Patterns)\n\nWhen creating a new class:\n\n- The class must represent a real-world entity or concept (noun).\n- The constructor must encapsulate the entity’s coordinates: store the properties or underlying object the class uses to refer to that entity.\n- The class must encapsulate all logic required to produce its result; do not rely on pre-calculated data from callers if it can be derived from dependencies.\n\n## Quick Checks\n\n- Class name is a noun, not “-er/-or/-service/-manager”.\n- Constructor captures the underlying object/properties that identify the entity.\n- Callers pass minimal inputs; the class derives the rest from its dependencies.\n"},"lastSynced":"2026-03-08T02:07:44.488Z","agentAnalysis":{"suitability":{"en":"Perfect for Object-Oriented Programming Agents needing encapsulated logic and entity representation.","zh":"非常适合需要封装逻辑和实体表示的面向对象编程代理。","ja":"オブジェクト指向プログラミングエージェントがカプセル化されたロジックとエンティティ表現を必要とする場合に最適です。","ko":"캡슐화된 로직과 엔티티 표현이 필요한 객체 지향 프로그래밍 에이전트에 적합합니다.","es":"Perfecto para agentes de programación orientada a objetos que necesitan lógica encapsulada y representación de entidades.","fr":"Parfait pour les agents de programmation orientée objet nécessitant une logique encapsulée et une représentation d''entités.","de":"Perfekt für Agenten der objektorientierten Programmierung, die eine verkapselte Logik und eine Entitätsdarstellung benötigen.","pt":"Perfeito para Agentes de Programação Orientada a Objetos que necessitam de lógica encapsulada e representação de entidades.","ru":"Идеально для агентов объектно-ориентированного программирования, которым необходима инкапсулированная логика и представление сущностей.","ar":"مثالي لعميل البرمجة الكائنية التي تحتاج إلى منطق مغلف وتمثيل الكيانات."},"recommendation":{"en":"Empowers agents to create modular, reusable code using PPTX presentation generation, modification, and reading capabilities, encapsulating entity coordinates and dependencies within constructors.","zh":"赋予代理创建模块化、可重用代码的能力，使用PPTX演示文稿生成、修改和读取功能，封装实体坐标和依赖项在构造函数内。","ja":"PPTX プレゼンテーション生成、変更、読み取り機能を使用して、エージェントがモジュラーで再利用可能なコードを作成できるようにし、コンストラクタ内でエンティティの座標と依存関係をカプセル化します。","ko":"PPTX 프레젠테이션 생성, 수정 및 읽기 기능을 사용하여 에이전트가 모듈화되고 재사용 가능한 코드를 생성할 수 있도록 하며, 생성자 내에서 엔티티 좌표 및 종속성을 캡슐화합니다.","es":"Habilita a los agentes a crear código modular y reutilizable utilizando capacidades de generación, modificación y lectura de presentaciones PPTX, encapsulando las coordenadas y dependencias de las entidades dentro de los constructores.","fr":"Permet aux agents de créer un code modulaire et réutilisable en utilisant les capacités de génération, de modification et de lecture de présentations PPTX, en encapsulant les coordonnées et les dépendances des entités à l''intérieur des constructeurs.","de":"Ermöglicht es den Agenten, modularen und wiederverwendbaren Code zu erstellen, indem sie Generierungs-, Modifizierungs- und Lese-Funktionen für PPTX-Präsentationen verwenden, die die Koordinaten und Abhängigkeiten der Entitäten innerhalb der Konstruktoren verkapseln.","pt":"Habilita os agentes a criar códigos modulares e reutilizáveis usando capacidades de geração, modificação e leitura de apresentações PPTX, encapsulando coordenadas de entidades e dependências dentro de construtores.","ru":"Наделяет агентов возможностью создавать модульный, многоразовый код с помощью возможностей создания, изменения и чтения презентаций PPTX, инкапсулируя координаты сущностей и зависимости внутри конструкторов.","ar":"يمنح الوكلاء khảية إنشاء أكواد قابلة لإعادة الاستخدام باستخدام قابليات إنشاء وتعديل وقراءة عروض تقديمية PPTX، وتغليف إحداثيات الكيانات والاعتماديات داخل المنشئين."},"useCases":{"en":["Generating PPTX presentations from data","Modifying existing presentations programmatically","Reading PPTX files without Microsoft Office"],"zh":["从数据生成PPTX演示文稿","以编程方式修改现有演示文稿","不需要Microsoft Office即可读取PPTX文件"],"ja":["データからPPTXプレゼンテーションを生成する","既存のプレゼンテーションをプログラム的に変更する","Microsoft OfficeなしでPPTXファイルを読み取る"],"ko":["데이터에서 PPTX 프레젠테이션을 생성하는 것","기존 프레젠테이션을 프로그래밍 방식으로 수정하는 것","Microsoft Office 없이 PPTX 파일을 읽는 것"],"es":["Generar presentaciones PPTX a partir de datos","Modificar presentaciones existentes de forma programática","Leer archivos PPTX sin Microsoft Office"],"fr":["Générer des présentations PPTX à partir de données","Modifier des présentations existantes de manière programmatique","Lire des fichiers PPTX sans Microsoft Office"],"de":["Erstellen von PPTX-Präsentationen aus Daten","Modifizieren von bestehenden Präsentationen programmgesteuert","Lesen von PPTX-Dateien ohne Microsoft Office"],"pt":["Geração de apresentações PPTX a partir de dados","Modificação de apresentações existentes de forma programática","Leitura de arquivos PPTX sem Microsoft Office"],"ru":["Генерация презентаций PPTX из данных","Изменение существующих презентаций программно","Чтение файлов PPTX без Microsoft Office"],"ar":["إنشاء عروض تقديمية PPTX من البيانات","تعديل العروض التقديمية الحالية بالبرمجة","قراءة ملفات PPTX بدون مكتب مايكروسوفت"]},"limitations":{"en":["Requires PPTX file format compatibility","Entity representation must be a noun"],"zh":["需要PPTX文件格式兼容性","实体表示必须是一个名词"],"ja":["PPTXファイル形式の互換性が必要","エンティティ表現は名詞でなければならない"],"ko":["PPTX 파일 형식 호환성이 필요함","엔티티 표현은 명사여야 함"],"es":["Requiere compatibilidad con el formato de archivo PPTX","La representación de la entidad debe ser un sustantivo"],"fr":["Nécessite la compatibilité avec le format de fichier PPTX","La représentation de l''entité doit être un nom"],"de":["Erfordert Kompatibilität mit dem PPTX-Dateiformat","Die Entitätsdarstellung muss ein Nomen sein"],"pt":["Requer compatibilidade com o formato de arquivo PPTX","A representação da entidade deve ser um substantivo"],"ru":["Требуется совместимость с форматом файла PPTX","Представление сущности должно быть существительным"],"ar":["يتطلب توافقًا مع تنسيق ملف PPTX","يجب أن تكون تمثيل الكيان اسمًا"]},"version":4},"contentHash":"1610371248a55f56dae07bbfeeac79c3e4c0dfdd678498d68b3d2414301d6ed7","qualityScore":23}');
