INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ShapeCrawler/ShapeCrawler/class', 'class', 'ShapeCrawler', 'ShapeCrawler', 'community', 'class ShapeCrawler ShapeCrawler community The Class skill enables developers to read, modify, and generate PPTX presentations without requiring Microsoft Office, streamlining presentation management for AI agents. 类是PowerPoint .NET库的核心，用于读取、修改和生成PPTX演示文稿 クラスはPowerPoint .NETライブラリの中心で、PPTXプレゼンテーションを読み取る、変更する、生成するために使用されます 클래스는 PowerPoint .NET 라이브러리의 핵심으로 PPTX 프레젠테이션을 읽고, 수정하고, 생성하는 데 사용됩니다 La clase representa una entidad o concepto real y encapsula la lógica necesaria para producir resultados sin depender de datos precalculados La classe représente une entité ou un concept réel et encapsule la logique nécessaire pour produire des résultats sans dépendre de données précalculées Die Klasse repräsentiert eine reale Entität oder ein Konzept und kapselt die notwendige Logik, um Ergebnisse zu erzeugen, ohne von vorab berechneten Daten abhängig zu sein Crie classes para manipular apresentações PPTX com a biblioteca .NET, seguindo as melhores práticas de design de classes. Создайте классы для работы с презентациями PPTX, используя библиотеку .NET и следуя лучшим практикам проектирования классов. انشئ الفئات لتعديل العروض التقديمية PPTX باستخدام مكتبة .NET، متبوعًا بأفضل الممارسات لتصميم الفئات. how to use class in PPTX management class alternative to Microsoft Office class vs PowerPoint API class install guide for AI agents class setup for PPTX presentation generation what is class in .NET library 类设置 PowerPoint .NET 库 PPTX 演示文稿 AIエージェント 类设计模式 构造函数封装 Represents real-world entities or concepts as nouns Encapsulates entity coordinates using constructors Derives results from dependencies without relying on pre-calculated data Follows key design patterns for class creation Enforces naming conventions for class names Class is a PowerPoint .NET library for managing PPTX presentations, allowing developers to create, modify, and generate presentations programmatically.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('grafana/grafana-pathfinder-app/tidyup', 'community', 'grafana', 'grafana-pathfinder-app', 'grafana/grafana-pathfinder-app', 'tidyup', 0, 0, 23, '2026-03-08T01:57:15.443Z', '2026-03-08T02:08:44.321Z', 'e6d3be02ae6fd277d86de098a81d507a171ada61e5fc2d3b69f32d040864989a', '{"id":"grafana/grafana-pathfinder-app/tidyup","name":"tidyup","description":{"en":"The tidyup skill automates housekeeping tasks for code preparation, fixing trivial syntax errors and ensuring CI system compatibility. It benefits developers by streamlining their workflow.","zh":"Tidyup 是一个代码清理工具，自动修复语法错误，优化代码提交","ja":"Tidyup はコード整理ツールで、自動的にコードのエラーを修正し、CIシステムのビルドを最適化","ko":"Tidyup은 코드 정리 도구로 코드 제출 전 자동 오류 수정을 제공하여 개발자에게 도움을 줍니다","es":"Tidyup es una habilidad que ejecuta tareas de housekeeping para preparar el código para su compromiso y envío","fr":"Tidyup est une compétence qui exécute des tâches de maintenance pour préparer le code à son engagement et à son envoi","de":"Tidyup ist eine Fähigkeit, die Wartungsaufgaben ausführt, um den Code für sein Commit und Push vorzubereiten","pt":"O Tidyup é uma ferramenta que executa tarefas de manutenção para preparar o código para commit e push, corrigindo erros de sintaxe triviais","ru":"Tidyup - это инструмент, который выполняет задачи технического обслуживания для подготовки кода к коммиту и пушу, исправляя тривиальные синтаксические ошибки ИИ Агенты","ar":"التيدى اب هو أداة تقوم بتشغيل مهام الصيانة لتحضير الكود للالتزام والدفع، وتصحيح الأخطاء النحوية التافهة أدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"tidyup: Automated Code Cleanup Setup Guide | AI Agent Skill","zh":"Tidyup 代码清理工具：setup 指南","ja":"Tidyup スキル：コード整理のベストプラクティス","ko":"Tidyup 코드 정리 가이드: CI 시스템 최적화","es":"Guía de configuración de Tidyup para desarrolladores","fr":"Guide de mise en place de Tidyup pour les développeurs","de":"Einrichtungsleitfaden für Tidyup-Entwickler","pt":"Guia de Configuração do Tidyup: Otimização de Código","ru":"Настройка Tidyup: Инструмент для Очистки КодаИИ Агенты","ar":"إعداد التيدى اب: أداة لتنظيف الكود AI Agents"},"description":{"en":"Discover how tidyup simplifies code preparation for commit and push, and learn how to integrate it into your workflow today!","zh":"Tidyup 代码清理工具帮助您在提交代码前自动修复语法错误，AIエージェント","ja":"Tidyup スキルはコード整理を自動化し、CIシステムのビルド失敗を防ぐ、AIエージェント","ko":"Tidyup 코드 정리 가이드는 개발자에게 코드 제출 전 자동 오류 수정을 제공하는 AI 도구입니다","es":"Aprenda a configurar Tidyup para automatizar tareas de housekeeping y evitar errores de sintaxis en su código","fr":"Découvrez comment configurer Tidyup pour automatiser les tâches de maintenance et éviter les erreurs de syntaxe dans votre code","de":"Erfahren Sie, wie Sie Tidyup konfigurieren, um Wartungsaufgaben zu automatisieren und Syntaxfehler in Ihrem Code zu vermeiden","pt":"Aprenda a configurar o Tidyup para otimizar seu código e evitar erros de sintaxe com o nosso guia passo a passo","ru":"Узнайте, как настроить Tidyup для оптимизации кода и предотвращения синтаксических ошибок с нашей пошаговой инструкцией ИИ Агенты","ar":"تعلم كيفية設定 التيدى اب لتحسين الكود وتجنب الأخطاء النحوية مع دليلنا خطوة بخطوة أدوات الذكاء الاصطناعي"},"definition":{"en":"tidyup is a skill that runs automated housekeeping tasks to prepare code for commit and push, fixing syntax errors and ensuring CI system compatibility.","zh":"Tidyup 是一种代码清理工具，自动修复代码中的语法错误","ja":"Tidyup はコード整理ツールの一種で、コードのエラーを自動的に修正","ko":"Tidyup은 코드 정리 도구의 일종으로 코드의 오류를 자동으로 수정","es":"Tidyup es una herramienta de automatización de tareas de housekeeping para desarrolladores","fr":"Tidyup est un outil d''automatisation de tâches de maintenance pour les développeurs","de":"Tidyup ist ein Tool für die Automatisierung von Wartungsaufgaben für Entwickler","pt":"O Tidyup é uma ferramenta de limpeza de código que executa tarefas de manutenção para preparar o código para commit e push","ru":"Tidyup - это инструмент очистки кода, который выполняет задачи технического обслуживания для подготовки кода к коммиту и пушу ИИ Агенты","ar":"التيدى اب هو أداة لتنظيف الكود التي تقوم بتشغيل مهام الصيانة لتحضير الكود للالتزام والدفع أدوات الذكاء الاصطناعي"},"features":{"en":["Runs automated housekeeping tasks prior to code commit and push","Fixes trivial syntax errors using prettier","Ensures CI system compatibility by resolving common build failures","Stops and prompts user for action on encountering semantic errors or missing code","Operates within branch context to identify and fix obvious errors"],"zh":["自动修复代码中的语法错误","优化代码提交","支持CI系统","自动检测代码错误","修复代码中的trivial syntax错误"],"ja":["コードのエラーを自動的に修正","コードの提出を最適化","CIシステムをサポート","コードのエラーを自動検出","コードのtrivial syntaxエラーを修正"],"ko":["코드의 오류를 자동으로 수정","코드 제출을 최적화","CI 시스템 지원","코드 오류 자동 감지","코드의 문법 오류 수정"],"es":["Ejecuta tareas de housekeeping para evitar errores de sintaxis","Automatiza la corrección de errores triviales y obvios","Integra con sistemas de integración continua (CI)","Ayuda a prevenir fallos de compilación debido a errores de sintaxis","Se detiene y solicita confirmación en caso de errores semánticos o inusuales"],"fr":["Exécute des tâches de maintenance pour éviter les erreurs de syntaxe","Automatise la correction des erreurs triviales et évidentes","Intègre avec les systèmes de intégration continue (CI)","Aide à prévenir les échecs de compilation due à des erreurs de syntaxe","S''arrête et demande confirmation en cas d''erreurs sémantiques ou inusuelles"],"de":["Führt Wartungsaufgaben aus, um Syntaxfehler zu vermeiden","Automatisiert die Korrektur von trivialen und offensichtlichen Fehlern","Integriert mit Continuous-Integration-Systemen (CI)","Hilft, Kompilierungsfehler aufgrund von Syntaxfehlern zu vermeiden","Hält an und fordert Bestätigung bei semantischen oder ungewöhnlichen Fehlern an"],"pt":["Executa tarefas de manutenção para preparar o código para commit e push","Corrige erros de sintaxe triviais","Integração com o sistema de CI para evitar falhas de build","Executa apenas tarefas de limpeza de código","Para e solicita ação do usuário em caso de erros semânticos ou código faltante"],"ru":["Выполняет задачи технического обслуживания для подготовки кода к коммиту и пушу","Исправляет тривиальные синтаксические ошибки","Интеграция с системой CI для предотвращения сбоя сборки","Выполняет только задачи очистки кода","Останавливается и запрашивает действие пользователя в случае семантических ошибок или отсутствия кода ИИ Агенты"],"ar":["تقوم بتشغيل مهام الصيانة لتحضير الكود للالتزام والدفع","تصحيح الأخطاء النحوية التافهة","التكامل مع نظام CI لتجنب فشل البناء","تقوم بتشغيل مهام تنظيف الكود فقط","تتوقف وتطلب الإجراء من المستخدم في حالة الأخطاء الدلالية أو عدم وجود الكود أدوات الذكاء الاصطناعي"]},"keywords":{"en":["how to use tidyup","tidyup setup guide","tidyup vs prettier","tidyup install","what is tidyup","tidyup alternative","automated code cleanup","ci system compatibility","code preparation workflow"],"zh":["代码清理工具","AIエージェント","代码提交","CI系统","代码错误修复","自动化代码整理","代码优化","开发者工具"],"ja":["コード整理ツール","AIエージェント","コード提出","CIシステム","コードエラー修正","自動コード整理","コード最適化","開発者ツール"],"ko":["코드 정리 도구","AI 도구","코드 제출","CI 시스템","코드 오류 수정","자동 코드 정리","코드 최적화","개발자 툴"],"es":["Tidyup","herramientas de automatización","desarrollo de software","integración continua","corrección de errores","automatización de tareas","desarrollo de código","herramientas de desarrollo"],"fr":["Tidyup","outils d''automatisation","développement de logiciels","intégration continue","correction d''erreurs","automatisation de tâches","développement de code","outils de développement"],"de":["Tidyup","Automatisierungstools","Software-Entwicklung","Continuous Integration","Fehlerkorrektur","Automatisierung von Aufgaben","Code-Entwicklung","Entwicklungstools"],"pt":["Tidyup","limpeza de código","otimização de código","erros de sintaxe","sistema de CI","commit e push","desenvolvimento de software","ferramentas de desenvolvimento"],"ru":["Tidyup","очистка кода","оптимизация кода","синтаксические ошибки","система CI","коммит и пуш","разработка программного обеспечения","инструменты разработки ИИ Агенты"],"ar":["التيدى اب","تنظيف الكود","تحسين الكود","الأخطاء النحوية","نظام CI","الالتزام والدفع","تطوير البرمجيات","أدوات التطوير أدوات الذكاء الاصطناعي"]}},"owner":"grafana","repo":"grafana-pathfinder-app","repoPath":"grafana/grafana-pathfinder-app","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.443Z","topics":[],"category":"community","skillMd":{"name":"tidyup","description":"Run typecheck, lint, and tests for both frontend and Go backend to tidy and test the code prior to committing and pushing.","bodyPreview":"# Tidy up\n\nThis skill runs a bunch of housekeeping tasks that need to be done prior to preparing code for commit\nand push. Our CI system will fail code that has errors in prettier, and a common source of silly\nCI build failures are things in this category.\n\nFor all steps, the intention is only to fix trivial syntax errors and or errors whose cause is\nobvious in branch context. If you find semantic errors, missing code, or anything unusual,\nSTOP and ask the user what to do, do not proceed.\n\n## Wo","body":"# Tidy up\n\nThis skill runs a bunch of housekeeping tasks that need to be done prior to preparing code for commit\nand push. Our CI system will fail code that has errors in prettier, and a common source of silly\nCI build failures are things in this category.\n\nFor all steps, the intention is only to fix trivial syntax errors and or errors whose cause is\nobvious in branch context. If you find semantic errors, missing code, or anything unusual,\nSTOP and ask the user what to do, do not proceed.\n\n## Workflow\n\n### Step 1: Run `npm run typecheck`\n\nFix all trivial TypeScript syntax errors.\n\n### Step 2: Run `npm run lint:fix`\n\nFix all trivial linting errors.\n\nNote: Prettier formatting is handled automatically by Husky''s pre-commit hook via lint-staged, so it doesn''t need to be run manually here.\n\n### Step 3: Run frontend unit tests: `npm run test:ci`\n\nAll should pass; if unit tests break and the cause is obvious (i.e. a missing import,\nor a slight syntax error) you can go ahead and fix them. If unit tests fail due to\nchanged functionality, STOP and ask the user what to do.\n\n### Step 4: Run Go lint: `npm run lint:go`\n\nFix all Go linting errors. If golangci-lint reports issues, address them.\n\n### Step 5: Run Go tests: `npm run test:go`\n\nAll Go tests should pass. If tests fail and the cause is obvious, fix them.\nIf tests fail due to changed functionality, STOP and ask the user what to do.\n\n### Step 6: Build Go backend: `go build ./...`\n\nVerify the Go backend compiles without errors.\n\n## Summary\n\nProvide very brief output that looks like this:\n\nTypecheck: <N> files modified\nLint: <N> files modified\nFrontend tests: (PASS|FAIL)\nGo lint: (PASS|FAIL)\nGo tests: (PASS|FAIL)\nGo build: (PASS|FAIL)\n\nIf any step fails, provide details on why.\n"},"lastSynced":"2026-03-08T02:08:44.321Z","agentAnalysis":{"suitability":{"en":"Ideal for Code Analysis Agents requiring automated syntax error correction and CI system compatibility","zh":"适用于需要自动语法错误纠正和CI系统兼容性的代码分析代理","ja":"コード分析エージェントが自動化された構文エラーの修正とCIシステムの互換性を必要とする場合に最適","ko":"자동화된 구문 오류 수정 및 CI 시스템 호환성이 필요한 코드 분석 에이전트에 적합","es":"Ideal para Agentes de Análisis de Código que requieren corrección automática de errores de sintaxis y compatibilidad con sistemas CI","fr":"Idéal pour les Agents d''Analyse de Code nécessitant une correction automatique des erreurs de syntaxe et une compatibilité avec les systèmes CI","de":"Ideal für Code-Analyse-Agents, die eine automatische Syntaxfehlerkorrektur und CI-Systemkompatibilität erfordern","pt":"Ideal para Agentes de Análise de Código que exigem correção automática de erros de sintaxe e compatibilidade com sistemas CI","ru":"Идеально для Агентов анализа кода, требующих автоматическую исправление синтаксических ошибок и совместимость с системами CI","ar":"مثالي لعميل تحليل الشفرة الذي يتطلب تصحيحًا تلقائيًا للأخطاء النحوية ومتوافق مع أنظمة CI"},"recommendation":{"en":"Empowers agents to automate housekeeping tasks, fixing trivial syntax errors and ensuring compatibility with CI systems using prettier, while streamlining developer workflows","zh":"赋予代理自动化家务任务的能力，修复琐碎的语法错误，并确保与使用prettier的CI系统的兼容性，同时简化开发人员的工作流程","ja":"エージェントに家事タスクの自動化を可能にし、prettierを使用するCIシステムとの互換性を保証しながら、微妙な構文エラーを修正し、開発者のワークフローをストリームライン化する","ko":"에이전트가 자동화된 하우스키핑 작업을 수행할 수 있도록 하여, 사소한 구문 오류를 수정하고, prettier를 사용하는 CI 시스템과의 호환성을 보장하며, 개발자의 워크플ロー를簡素화한다","es":"Habilita a los agentes a automatizar tareas de mantenimiento, corregir errores de sintaxis triviales y garantizar la compatibilidad con sistemas CI utilizando prettier, mientras se optimizan los flujos de trabajo de los desarrolladores","fr":"Permet aux agents d''automatiser les tâches de maintenance, de corriger les erreurs de syntaxe triviales et d''assurer la compatibilité avec les systèmes CI en utilisant prettier, tout en rationalisant les flux de travail des développeurs","de":"Ermächtigt Agents, Wartungsaufgaben zu automatisieren, triviale Syntaxfehler zu beheben und die Kompatibilität mit CI-Systemen unter Verwendung von prettier zu gewährleisten, während die Arbeitsabläufe der Entwickler optimiert werden","pt":"Habilita agentes a automatizar tarefas de manutenção, corrigir erros de sintaxe triviais e garantir a compatibilidade com sistemas CI usando prettier, ao mesmo tempo em que otimiza os fluxos de trabalho dos desenvolvedores","ru":"Наделяет агентов возможностью автоматизировать задачи по содержанию, исправлять тривиальные синтаксические ошибки и обеспечивать совместимость с системами CI с помощью prettier, оптимизируя при этом рабочие процессы разработчиков","ar":"يسمح للوكلاء بتحسين المهام الروتينية، وإصلاح الأخطاء النحوية الطفيفة، وضمان التوافق مع أنظمة CI باستخدام prettier، مع تقليل عبء العمل للمطورين"},"useCases":{"en":["Automating code preparation for commit and push","Debugging trivial syntax errors","Ensuring CI system compatibility"],"zh":["为提交和推送自动准备代码","调试琐碎的语法错误","确保CI系统兼容性"],"ja":["コミットとプッシュのためのコード自動準備","微妙な構文エラーのデバッグ","CIシステムの互換性の確保"],"ko":["커밋 및 푸시를 위한 코드 자동 준비","사소한 구문 오류 디버깅","CI 시스템 호환성 보장"],"es":["Automatizar la preparación de código para commit y push","Depurar errores de sintaxis triviales","Garantizar la compatibilidad con sistemas CI"],"fr":["Automatiser la préparation de code pour commit et push","Déboguer les erreurs de syntaxe triviales","Assurer la compatibilité avec les systèmes CI"],"de":["Automatisieren der Codevorbereitung für Commit und Push","Beheben von trivialen Syntaxfehlern","Gewährleisten der Kompatibilität mit CI-Systemen"],"pt":["Automatizar a preparação de código para commit e push","Depurar erros de sintaxe triviais","Garantir a compatibilidade com sistemas CI"],"ru":["Автоматизировать подготовку кода для commit и push","Отлаживать тривиальные синтаксические ошибки","Обеспечивать совместимость с системами CI"],"ar":["تحسين إعداد الشفرة للالتزام والدفع","تصحيح الأخطاء النحوية الطفيفة","ضمان التوافق مع أنظمة CI"]},"limitations":{"en":["Only fixes trivial syntax errors","Stops and asks for user input on semantic errors or missing code","Requires branch context for error analysis"],"zh":["仅修复琐碎的语法错误","在语义错误或缺失代码时停止并要求用户输入","需要分支上下文进行错误分析"],"ja":["微妙な構文エラーのみを修正","セマンティックエラーまたはコードの欠落時に停止してユーザー入力を要求","エラー分析のためにブランチコンテキストが必要"],"ko":["사소한 구문 오류만 수정","语义 오류 또는 코드 누락시停止하고 사용자 입력을 요청","오류 분석을 위해 브랜치 컨텍스트가 필요"],"es":["Solo corrige errores de sintaxis triviales","Se detiene y solicita la entrada del usuario en errores semánticos o código que falta","Requiere contexto de rama para el análisis de errores"],"fr":["Ne corrige que les erreurs de syntaxe triviales","S''arrête et demande une entrée utilisateur en cas d''erreurs sémantiques ou de code manquant","Nécessite un contexte de branche pour l''analyse des erreurs"],"de":["Behebt nur triviale Syntaxfehler","Hält an und fordert Benutzereingabe bei semantischen Fehlern oder fehlendem Code an","Benötigt Kontext von Zweig für die Fehleranalyse"],"pt":["Corrige apenas erros de sintaxe triviais","Para e solicita entrada do usuário em erros semânticos ou código ausente","Exige contexto de branch para análise de erros"],"ru":["Исправляет только тривиальные синтаксические ошибки","Останавливается и запрашивает ввод пользователя при семантических ошибках или отсутствии кода","Требует контекста ветки для анализа ошибок"],"ar":["يصلح فقط الأخطاء النحوية الطفيفة","يتوقف ويتطلب إدخال المستخدم في الأخطاء الدلالية أو الشفرة المفقودة","يتطلب سياق الفرع لتحليل الأخطاء"]},"version":4},"contentHash":"e6d3be02ae6fd277d86de098a81d507a171ada61e5fc2d3b69f32d040864989a","qualityScore":23}');
