INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('krisnye/cryos/namespace', 'namespace', 'krisnye', 'cryos', 'community', 'namespace krisnye cryos community The namespace skill provides a standardized pattern for WebGPU graphics library development, benefiting developers working with WebGPU and TypeScript. Namespace 是 WebGPU 项目中的一个重要概念，用于组织代码和管理类型 Namespace は WebGPU プロジェクトでコードを整理し、タイプを管理する重要な概念です Namespace는 WebGPU 프로젝트에서 코드를 정리하고 유형을 관리하는 중요한 개념입니다 El namespace es un patrón estándar para organizar tipos y constantes en la biblioteca gráfica WebGPU Le namespace est un modèle standard pour organiser les types et les constantes dans la bibliothèque graphique WebGPU Das Namespace ist ein Standardmuster zur Organisation von Typen und Konstanten in der WebGPU-Grafikbibliothek O namespace é um padrão standard para a biblioteca gráfica WebGPU, que permite a exportação de tipos e constantes de forma organizada. namespace - это стандартный шаблон для библиотеки графики WebGPU, который позволяет экспортировать типы и константы в организованном виде. الnamespace هو نمط معياري لمكتبة الرسومات WebGPU، يسمح بالتصدير النوع والثوابت بشكل منظم. how to use namespace what is namespace namespace alternative namespace vs WebGPU namespace install namespace setup guide WebGPU graphics library TypeScript namespace pattern namespace documentation WebGPU Namespace 类型导入 FromSchema 代码组织 WebGPU 项目 AIエージェント 代码管理 Exports a single export type using FromSchema if schema-based Supports importing and exporting constants from eponymously named files Utilizes a namespace.ts file to export all publicly exported constants Follows a standard pattern for organizing type definitions and constants Exports a single export type with a specific name and type Contains constants in their own separate files for better organization namespace is a WebGPU graphics library that follows a standard pattern for organizing and exporting type definitions and constants.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('lsimatt2/resisters/upload', 'community', 'lsimatt2', 'resisters', 'lsimatt2/resisters', 'upload', 0, 0, 23, '2026-03-08T01:57:15.446Z', '2026-03-08T02:08:54.501Z', 'f93d7f97543d771a68e3767bd24699ab9b7b64062805d117913eee5300e8f8e5', '{"id":"lsimatt2/resisters/upload","name":"upload","description":{"en":"The upload skill automates deployment to Vercel by committing and pushing changes via Git. It benefits developers by simplifying the deployment process.","zh":"Upload功能允许您将更改部署到Vercel，包括运行git状态检查、提交和推送","ja":"Upload機能は、変更をVercelにデプロイすることを可能にします。gitの状態チェック、コミット、プッシュなど","ko":"Upload기능을 사용하면 변경 사항을 Vercel에 배포할 수 있습니다. git 상태 체크, 커밋, 푸시 등","es":"El upload a Vercel es un proceso que implica commit y push de cambios para desplegar sitios web. Utiliza herramientas de AI para automatizar el proceso","fr":"L''upload sur Vercel est un processus qui implique commit et push de modifications pour déployer des sites web. Utilisez des outils d''IA pour automatiser le processus","de":"Der Upload auf Vercel ist ein Prozess, der Commit und Push von Änderungen zum Deployen von Webseiten beinhaltet. Verwenden Sie KI-Tools, um den Prozess zu automatisieren","pt":"O upload para Vercel é um processo que envolve o uso de comandos git para commitar e enviar alterações. Confira nosso guia para saber mais.","ru":"Upload на Vercel - это процесс, включающий использование команд git для фиксации и отправки изменений. Узнайте больше из нашего руководства.","ar":"أداة الرفع إلى Vercel هي عملية تستخدم أوامر git لتقديم وتسليم التغييرات. راجع دليلنا لمعرفة المزيد."},"seo":{"title":{"en":"Upload: Automated Deployment to Vercel | AI Agent Skill","zh":"Upload_SETUP_Guide_使用Vercel部署","ja":"Upload_Setup_Guide_Vercelでデプロイ","ko":"Upload_SETUP_Guide_Vercel을_통한_배포","es":"Guía de Configuración de Subida a Vercel con Herramientas...","fr":"Guide d''Installation de l''Upload sur Vercel avec Outils d''IA","de":"Einrichtungsanleitung für Upload auf Vercel mit KI-Tools","pt":"Guia de Configuração do Upload para Vercel","ru":"ИИ Агенты: Руководство по Настройке Upload на Vercel","ar":"دليل إعداد أداة الرفع إلى Vercel"},"description":{"en":"Streamline your deployment process with the upload skill, automating Git commits and Vercel deployments. Learn how to set it up today!","zh":"了解如何使用Upload功能通过Vercel部署网站，包括git状态检查、提交和推送","ja":"Upload機能を使用してVercelでWebサイトをデプロイする方法について学びます。gitの状態チェック、コミット、プッシュなど","ko":"Upload기능을 사용하여 Vercel을 통해 웹사이트를 배포하는 방법에 대해 알아보세요. git 상태 체크, 커밋, 푸시 등","es":"Aprende a configurar la subida a Vercel con herramientas de AI para desplegar sitios web de manera eficiente","fr":"Découvrez comment configurer l''upload sur Vercel avec des outils d''IA pour déployer des sites web de manière efficace","de":"Erfahren Sie, wie Sie den Upload auf Vercel mit KI-Tools einrichten, um Webseiten effizient zu deployen","pt":"Aprenda a configurar o upload para Vercel com nosso guia passo a passo, incluindo git status, git diff e commit","ru":"Настройте upload на Vercel с нашей пошаговой инструкцией, включая git status, git diff и commit","ar":"تعلم كيفية إعداد أداة الرفع إلى Vercel بخطوات بسيطة، بما في ذلك git status و git diff و commit"},"definition":{"en":"Upload is a skill that automates the deployment of site changes to Vercel via Git, using commands like git add and git push.","zh":"Upload是指将本地更改部署到Vercel的过程，涉及git操作","ja":"Uploadとは、ローカルの変更をVercelにデプロイすることを指し、git操作を伴う","ko":"Upload는 로컬 변경 사항을 Vercel에 배포하는 것을 의미하며, git 연산을 포함","es":"El upload a Vercel es una función que permite desplegar sitios web en Vercel mediante commit y push de cambios","fr":"L''upload sur Vercel est une fonction qui permet de déployer des sites web sur Vercel via commit et push de modifications","de":"Der Upload auf Vercel ist eine Funktion, die das Deployen von Webseiten auf Vercel durch Commit und Push von Änderungen ermöglicht","pt":"O que é upload para Vercel? É um processo de deploy que utiliza git para enviar alterações para o servidor.","ru":"Что такое upload на Vercel? Это процесс deploy, использующий git для отправки изменений на сервер.","ar":"ما هي أداة الرفع إلى Vercel؟ هي عملية نشر تستخدم git لنقل التغييرات إلى الخادم."},"features":{"en":["Runs git status and git diff to review changes","Stages changed files with git add for precise control","Writes clear, concise commit messages for version tracking","Commits changes with a meaningful message and pushes to origin main","Confirms deployment to Vercel for streamlined updates"],"zh":["运行git状态检查","提交更改","推送到远程仓库","使用Vercel部署网站","支持git add和git commit命令","自动部署到Vercel"],"ja":["gitの状態チェックを実行","変更をコミット","リモートリポジトリにプッシュ","VercelでWebサイトをデプロイ","git addとgit commitコマンドをサポート","Vercelへの自動デプロイ"],"ko":["git 상태 체크 실행","변경 사항 커밋","원격 저장소에 푸시","Vercel을 통해 웹사이트 배포","git add 및 git commit 명령어 지원","Vercel로의 자동 배포"],"es":["Ejecuta `git status` y `git diff` para revisar cambios","Etapa los archivos modificados con `git add`","Escribe un mensaje de commit claro y conciso","Commit y push de cambios a Vercel","Confirma al usuario que los cambios se han subido y Vercel deployará pronto","Integración con herramientas de AI para automatizar el proceso"],"fr":["Exécutez `git status` et `git diff` pour examiner les modifications","Etagez les fichiers modifiés avec `git add`","Écrivez un message de commit clair et concis","Commit et push de modifications sur Vercel","Confirmez à l''utilisateur que les modifications ont été téléchargées et que Vercel déployera bientôt","Intégration avec des outils d''IA pour automatiser le processus"],"de":["Führen Sie `git status` und `git diff` aus, um Änderungen zu überprüfen","Stagieren Sie die geänderten Dateien mit `git add`","Schreiben Sie eine klare und präzise Commit-Nachricht","Commit und Push von Änderungen an Vercel","Bestätigen Sie dem Benutzer, dass die Änderungen hochgeladen wurden und Vercel bald deployen wird","Integration mit KI-Tools, um den Prozess zu automatisieren"],"pt":["Uso de git status para revisar alterações","Uso de git diff para visualizar alterações","Commit de alterações com mensagens claras","Envio de alterações para o repositório remoto","Integração com Vercel para deploy automático"],"ru":["Использование git status для просмотра изменений","Использование git diff для отображения изменений","Фиксация изменений с ясными сообщениями","Отправка изменений в удаленный репозиторий","Интеграция с Vercel для автоматического deploy"],"ar":["استخدام git status لمراجعة التغييرات","استخدام git diff لعرض التغييرات","التعهد بالتغييرات مع رسائل واضحة","نقل التغييرات إلى المستودع البعيد","التكامل مع Vercel لنشر التغييرات تلقائيًا"]},"keywords":{"en":["how to use upload","upload setup guide","git add command","vercel deployment automation","upload vs manual deployment","upload install for ai agents","what is upload skill","upload alternative for developers","automated git push"],"zh":["Upload功能","Vercel部署","git操作","自动部署","Web开发","AIエージェント","Upload.setup","Vercel deploying"],"ja":["Upload機能","Vercelデプロイ","git操作","自動デプロイ","Web開発","AIエージェント","Upload.setup","Vercel deploying"],"ko":["Upload기능","Vercel 배포","git 연산","자동 배포","웹 개발","인공지능 에이전트","Upload.setup","Vercel deploying"],"es":["subida a Vercel","herramientas de AI","despliegue de sitios web","commit y push","git status","git diff","Vercel deploy","automatización de procesos","desarrollo web"],"fr":["upload sur Vercel","outils d''IA","déployer des sites web","commit et push","git status","git diff","Vercel déployer","automatisation de processus","développement web"],"de":["Upload auf Vercel","KI-Tools","Webseiten-Deploy","Commit und Push","git status","git diff","Vercel Deploy","Automatisierung von Prozessen","Webentwicklung"],"pt":["upload para Vercel","git status","git diff","commit","deploy automático","Vercel","git","desenvolvimento web"],"ru":["ИИ Агенты","upload на Vercel","git status","git diff","commit","автоматический deploy","Vercel","git","веб-разработка"],"ar":["أداة الرفع إلى Vercel","git status","git diff","التعهد","نشر التغييرات تلقائيًا","Vercel","git","تطوير الويب","أدوات الويب الذكية"]}},"owner":"lsimatt2","repo":"resisters","repoPath":"lsimatt2/resisters","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.446Z","topics":[],"category":"community","skillMd":{"name":"upload","description":"Commit and push all changes to GitHub to trigger a Vercel deployment.","bodyPreview":"# Upload to Vercel\n\nWhen the user invokes /upload, commit and push all changes to deploy the site via Vercel.\n\n## Steps\n\n1. Run `git status` and `git diff` to review all changes\n2. Stage the changed files with `git add` (prefer adding specific files over `git add .`)\n3. Write a clear, concise commit message summarizing the changes\n4. Commit with the message\n5. Push to the remote (`origin main`)\n6. Confirm to the user that the changes have been pushed and Vercel will deploy shortly\n\n## Rules\n\n- A","body":"# Upload to Vercel\n\nWhen the user invokes /upload, commit and push all changes to deploy the site via Vercel.\n\n## Steps\n\n1. Run `git status` and `git diff` to review all changes\n2. Stage the changed files with `git add` (prefer adding specific files over `git add .`)\n3. Write a clear, concise commit message summarizing the changes\n4. Commit with the message\n5. Push to the remote (`origin main`)\n6. Confirm to the user that the changes have been pushed and Vercel will deploy shortly\n\n## Rules\n\n- Always use `eval \"$(/opt/homebrew/bin/brew shellenv zsh)\"` before git commands if needed\n- Never force push\n- Never skip pre-commit hooks\n- If there are no changes to commit, let the user know\n"},"lastSynced":"2026-03-08T02:08:54.501Z","agentAnalysis":{"suitability":{"en":"Perfect for Deployment Agents needing automated Git workflows and Vercel integration.","zh":"非常适合需要自动化 Git 工作流和 Vercel 集成的部署 Agent。","ja":"自動化された Git ワークフローと Vercel 統合を必要とするデプロイメント Agent に最適です。","ko":"자동화된 Git 워크플로우와 Vercel 통합이 필요한 배포 Agent에 완벽합니다.","es":"Perfecto para Agentes de Despliegue que necesitan flujos de trabajo de Git automatizados y integración con Vercel.","fr":"Parfait pour les Agents de déploiement ayant besoin de flux de travail Git automatisés et d''intégration avec Vercel.","de":"Perfekt für Deployment-Agents, die automatisierte Git-Workflows und Vercel-Integration benötigen.","pt":"Perfeito para Agentes de Implantação que precisam de fluxos de trabalho automatizados do Git e integração com o Vercel.","ru":"Идеально подходит для агентов развертывания, которым необходимы автоматизированные рабочие процессы Git и интеграция с Vercel.","ar":"مثالي لعميل التوزيع الذين يحتاجون إلى سير عمل آلي لجيت وتكامل مع Vercel."},"recommendation":{"en":"Empowers agents to streamline deployment processes via Git, utilizing protocols like commit and push to deploy sites on Vercel, and confirming deployment status to users.","zh":"使 Agent 能够通过 Git 简化部署流程，利用 commit 和 push 等协议在 Vercel 上部署站点，并向用户确认部署状态。","ja":"Agent が Git を介してデプロイメントプロセスを効率化し、commit や push などのプロトコルを利用して Vercel 上にサイトをデプロイし、ユーザーにデプロイメントステータスを確認することを可能にします。","ko":"Agent가 Git을 통해 배포 프로세스를 간소화하도록 지원하며, commit 및 push와 같은 프로토콜을 활용하여 Vercel에 사이트를 배포하고 사용자에게 배포 상태를 확인합니다.","es":"Habilita a los agentes a simplificar los procesos de despliegue a través de Git, utilizando protocolos como commit y push para desplegar sitios en Vercel, y confirmando el estado de despliegue a los usuarios.","fr":"Permet aux agents de simplifier les processus de déploiement via Git, en utilisant des protocoles tels que commit et push pour déployer des sites sur Vercel, et en confirmant l''état de déploiement aux utilisateurs.","de":"Ermächtigt Agenten, die Deployment-Prozesse über Git zu rationalisieren, indem sie Protokolle wie commit und push verwenden, um Sites auf Vercel zu deployen und den Deployment-Status an Benutzer zu bestätigen.","pt":"Habilita os agentes a simplificar os processos de implantação via Git, utilizando protocolos como commit e push para implantar sites no Vercel e confirmar o status de implantação para os usuários.","ru":"Наделяет агентов возможностью оптимизировать процессы развертывания через Git, используя протоколы, такие как commit и push, для развертывания сайтов на Vercel и подтверждения статуса развертывания пользователям.","ar":"يمنح الوكلاء القدرة على تبسيط عمليات التوزيع عبر جيت، باستخدام بروتوكولات مثل Commit و Push لنشر المواقع على Vercel وتأكيد حالة النشر للمستخدمين."},"useCases":{"en":["Automating site deployments to Vercel","Committing and pushing changes via Git","Confirming deployment status to users"],"zh":["自动化站点部署到 Vercel","通过 Git 提交和推送更改","向用户确认部署状态"],"ja":["Vercel へのサイトデプロイの自動化","Git を介した変更のコミットとプッシュ","ユーザーへのデプロイメントステータスの確認"],"ko":["Vercel로의 사이트 배포 자동화","Git을 통한 변경 사항 커밋 및 푸시","사용자에게 배포 상태 확인"],"es":["Automatizar despliegues de sitios en Vercel","Confirmar y enviar cambios a través de Git","Confirmar el estado de despliegue a los usuarios"],"fr":["Automatiser les déploiements de sites sur Vercel","Valider et envoyer des modifications via Git","Confirmer l''état de déploiement aux utilisateurs"],"de":["Automatisierung von Site-Deployments auf Vercel","Commiten und Pushen von Änderungen über Git","Bestätigen des Deployment-Status an Benutzer"],"pt":["Automatizar implantações de sites para o Vercel","Fazer commit e push de alterações via Git","Confirmar status de implantação para os usuários"],"ru":["Автоматизация развертывания сайтов на Vercel","Фиксация и отправка изменений через Git","Подтверждение статуса развертывания пользователям"],"ar":["أتمتة نشر المواقع على Vercel","إجراء Commit و Push للتغييرات عبر جيت","تأكيد حالة النشر للمستخدمين"]},"limitations":{"en":["Requires Git installation and configuration","Vercel deployment setup needed","Limited to Git-based version control"],"zh":["需要安装和配置 Git","需要设置 Vercel 部署","仅限于基于 Git 的版本控制"],"ja":["Git のインストールと設定が必要","Vercel デプロイメントの設定が必要","Git ベースのバージョン管理に限定される"],"ko":["Git 설치 및 구성 필요","Vercel 배포 설정 필요","Git 기반 버전 관리로 제한됨"],"es":["Requiere instalación y configuración de Git","Se requiere configuración de despliegue de Vercel","Limitado a control de versiones basado en Git"],"fr":["Nécessite l''installation et la configuration de Git","Configuration de déploiement Vercel requise","Limité au contrôle de version basé sur Git"],"de":["Benötigt Git-Installation und -Konfiguration","Vercel-Deployment-Einrichtung erforderlich","Begrenzt auf Git-basiertes Versionskontrollsystem"],"pt":["Requer instalação e configuração do Git","Configuração de implantação do Vercel necessária","Limitado ao controle de versão baseado em Git"],"ru":["Требуется установка и конфигурация Git","Необходима настройка развертывания Vercel","Ограничен только контроль версий на основе Git"],"ar":["يتطلب تثبيت وتهيئة جيت","مطلوب إعداد نشر Vercel","محدود بالتحكم في الإصدارات القائم على جيت"]},"version":4},"contentHash":"f93d7f97543d771a68e3767bd24699ab9b7b64062805d117913eee5300e8f8e5","qualityScore":23}');
