INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('JUVOJustin/wordpress-plugin-boilerplate/plugin-translations-update', 'plugin-translations-update', 'JUVOJustin', 'wordpress-plugin-boilerplate', 'community', 'plugin-translations-update JUVOJustin wordpress-plugin-boilerplate community The plugin-translations-update skill helps WordPress developers manage internationalization by extracting, translating, and compiling translation files. It benefits developers who need to localize their plugins. WordPress Plugin Boilerplate用于管理国际化，实现翻译文件的更新 WordPressプラグインの国際化を管理するためのボイラープレート 워드프레스 플러그인 국제화를 관리하기 위한 보일러플레이트 El plugin-translations-update es una herramienta para gestionar la internacionalización de plugins de WordPress, incluyendo la extracción y compilación de archivos de traducción Le plugin-translations-update est un outil pour gérer l''internationalisation des plugins WordPress, y compris l''extraction et la compilation de fichiers de traduction Das plugin-translations-update ist ein Tool zur Verwaltung der Internationalisierung von WordPress-Plugins, einschließlich Extraktion und Kompilierung von Übersetzungsdateien O plugin-translations-update é uma ferramenta para gerenciar internacionalização para plugins do WordPress, permitindo a extração e compilação de arquivos de tradução Плагин перевода является инструментом для управления интернационализацией для плагинов WordPress, позволяющим извлекать и компилировать файлы перевода تحديث الترجمة الإضافية هو أداة لإدارة التدويل لاضافات ووردبريس ، مما يسمح باسترجاع وتجميع ملفات الترجمة how to use plugin-translations-update wordpress plugin translation setup guide plugin-translations-update alternative wordpress internationalization tutorial plugin-translations-update install wordpress plugin localization best practices what is plugin-translations-update plugin-translations-update vs wp-translate plugin-translations-update setup tutorial WordPress插件翻译 国际化管理 npm composer 翻译文件更新 多语言支持 AIエージェント WordPress开发 Extracts strings using `composer run i18n:extract` to generate `.pot` files Updates existing `.po` files with missing translations Builds scripts using `npm run build` for seamless integration Validates setup by reading `languages/` directory for existing translation files Compiles translation files for efficient plugin localization plugin-translations-update is a WordPress Plugin Boilerplate that simplifies internationalization (i18n) for plugins by automating translation file management');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('AhmedAlnasser2000/Science-Lab/physicslab_worktrees', 'community', 'AhmedAlnasser2000', 'Science-Lab', 'AhmedAlnasser2000/Science-Lab', 'physicslab_worktrees', 0, 0, 23, '2026-03-08T01:57:15.465Z', '2026-03-08T02:09:21.699Z', 'd7e46af7f1d79762b2c6247e05696d04f55125b160a1775c644be2d6f6f0a798', '{"id":"AhmedAlnasser2000/Science-Lab/physicslab_worktrees","name":"physicslab_worktrees","description":{"en":"The physicslab_worktrees skill enables developers to create new worktrees and manage branches efficiently. It automates tasks such as starting new slice/milestone branches and reminding users about best practices.","zh":"PhysicsLab Worktrees 是一个用于创建和管理工作树的工具，支持分支管理和安全默认设置","ja":"PhysicsLab Worktrees は、新しいスライス/マイルストーン ブランチを作成し、ワークツリーを安全に管理するためのツールです","ko":"PhysicsLab Worktrees는 작업을 효율적으로 관리할 수 있는 작업 트리 및 분기 관리 도구입니다","es":"PhysicsLab Worktrees es una herramienta para crear ramas y trabajar de forma efectiva con Git. Permite a los desarrolladores crear worktrees y trabajar en ellos de forma segura.","fr":"PhysicsLab Worktrees est un outil pour créer des branches et travailler efficacement avec Git. Il permet aux développeurs de créer des worktrees et de travailler dessus de manière sécurisée.","de":"PhysicsLab Worktrees ist ein Tool zum Erstellen von Branches und effektiver Arbeit mit Git. Es ermöglicht Entwicklern, Worktrees zu erstellen und sicher darin zu arbeiten.","pt":"O PhysicsLab Worktrees é uma ferramenta para criar branches e worktrees de forma eficiente, com recursos como start de branches com segurança e lembretes para desenvolvedores","ru":"PhysicsLab Worktrees - это инструмент для создания веток и рабочих деревьев, обеспечивающий безопасный старт веток и напоминания для разработчиков ИИ Агентов","ar":"PhysicsLab Worktrees هو أداة لإنشاء فروع ووحدات عمل بشكل فعال، مع ميزات مثل بدء الفروع بأمان وتذكيرات لمنشئي الأدوات الذكية"},"seo":{"title":{"en":"physicslab_worktrees: Setup Guide for AI Agents","zh":"PhysicsLab Worktrees 快速入门指南","ja":"PhysicsLab Worktrees の設定方法","ko":"PhysicsLab Worktrees 시작 가이드","es":"Guía de configuración de PhysicsLab Worktrees para desarr...","fr":"Guide de démarrage de PhysicsLab Worktrees pour les dével...","de":"Setup-Leitfaden für PhysicsLab Worktrees für Entwickler","pt":"Guia de Configuração do PhysicsLab Worktrees para Desenvo...","ru":"Настройка PhysicsLab Worktrees: Руководство для Разработч...","ar":"دليل إعداد PhysicsLab Worktrees لمنشئي الأدوات الذكية"},"description":{"en":"Discover how to utilize physicslab_worktrees for efficient worktree management. Learn to create new slice/milestone branches and worktrees with ease.","zh":"了解 PhysicsLab Worktrees 的功能和特性，包括创建工作树和分支管理","ja":"PhysicsLab Worktrees を使用して新しいスライス/マイルストーン ブランチを作成し、ワークツリーを管理する","ko":"PhysicsLab Worktrees로 작업을 효율적으로 관리하는 방법","es":"Aprende a utilizar PhysicsLab Worktrees para crear ramas y trabajar de forma efectiva con Git","fr":"Découvrez comment utiliser PhysicsLab Worktrees pour créer des branches et travailler efficacement avec Git","de":"Erfahren Sie, wie Sie PhysicsLab Worktrees verwenden, um Branches zu erstellen und effektiv mit Git zu arbeiten","pt":"Aprenda a configurar o PhysicsLab Worktrees para criar branches e worktrees de forma eficiente, com dicas e práticas recomendadas para desenvolvedores","ru":"Узнайте, как настроить PhysicsLab Worktrees для создания веток и рабочих деревьев, а также получите советы и лучшие практики для разработчиков ИИ Агентов","ar":"تعلم كيفية إعداد PhysicsLab Worktrees لإنشاء فروع ووحدات عمل بشكل فعال، مع نصائح وأفضل الممارسات لمنشئي الأدوات الذكية"},"definition":{"en":"physicslab_worktrees is a skill that automates worktree management, allowing developers to create and manage new branches and worktrees using PowerShell scripts.","zh":"PhysicsLab Worktrees 是一个用于创建和管理工作树的工具","ja":"PhysicsLab Worktrees はワークツリーを作成して管理するためのツールです","ko":"PhysicsLab Worktrees는 작업 트리를 생성하고 관리하는 도구입니다","es":"PhysicsLab Worktrees es una herramienta de Git que permite crear worktrees y ramas para trabajar de forma efectiva","fr":"PhysicsLab Worktrees est un outil Git qui permet de créer des worktrees et des branches pour travailler efficacement","de":"PhysicsLab Worktrees ist ein Git-Tool, das das Erstellen von Worktrees und Branches für effektive Arbeit ermöglicht","pt":"O PhysicsLab Worktrees é uma ferramenta de desenvolvimento que ajuda a criar branches e worktrees de forma eficiente","ru":"PhysicsLab Worktrees - это инструмент разработки, помогающий создавать ветки и рабочие деревья эффективно","ar":"PhysicsLab Worktrees هو أداة تطوير تساعد في إنشاء فروع ووحدات عمل بشكل فعال"},"features":{"en":["Starts new slice/milestone branches using PowerShell scripts","Creates worktrees with safe defaults and no push enabled","Reminds users to work inside the created worktree folder","Enforces fetch and fast-forward only pull for local main vs origin","Supports explicit push requests using the -Push flag","Utilizes powershell ./tools/dev/start_slice_worktree.ps1 script for automation"],"zh":["支持创建新分支","安全默认设置，防止意外推送","强制 fetch 和 ff-only pull","工作树文件夹内进行所有工作","powershell 脚本支持"],"ja":["新しいスライス/マイルストーン ブランチを作成","安全なデフォルト設定でプッシュを防ぐ","fetch と ff-only pull を強制","ワークツリー フォルダ内ですべての作業を行う","powershell スクリプトをサポート"],"ko":["새로운 슬라이스/마일스톤 브랜치를 생성","안전한 기본 설정으로 푸시를 방지","페치 및 ff-온리 풀을 강제","작업 트리 폴더 내에서 모든 작업을 수행","powershell 스크립트 지원"],"es":["Crea worktrees y ramas con PowerShell","Permite trabajar de forma segura con Git","Desactiva el push por defecto para evitar errores","Permite fetch y pull de forma segura","Soporta la creación de branches con nombres personalizados"],"fr":["Crée des worktrees et des branches avec PowerShell","Permet de travailler de manière sécurisée avec Git","Désactive le push par défaut pour éviter les erreurs","Permet de fetch et de pull de manière sécurisée","Prend en charge la création de branches avec des noms personnalisés"],"de":["Erstellt Worktrees und Branches mit PowerShell","Ermöglicht sichere Arbeit mit Git","Deaktiviert Push standardmäßig, um Fehler zu vermeiden","Ermöglicht sicheres Fetchen und Pullen","Unterstützt die Erstellung von Branches mit benutzerdefinierten Namen"],"pt":["Criação de branches com segurança","Lembretes para desenvolvedores","Suporte a worktrees","Integração com o PowerShell","Opção de push explícita","Suporte a fetch e pull"],"ru":["Безопасный старт веток","Напоминания для разработчиков","Поддержка рабочих деревьев","Интеграция с PowerShell","Эксплицитная опция пуша","Поддержка фетча и пула"],"ar":["إنشاء فروع بأمان","تذكيرات لمنشئي الأدوات الذكية","دعم وحدات العمل","التكامل مع PowerShell","خيار دفع صريح","دعم جلب و سحب"]},"keywords":{"en":["how to use physicslab_worktrees","physicslab_worktrees setup guide","physicslab_worktrees alternative","physicslab_worktrees vs git worktree","physicslab_worktrees install","physicslab_worktrees tutorial","worktree management with physicslab_worktrees","physicslab_worktrees best practices","physicslab_worktrees and PowerShell"],"zh":["PhysicsLab Worktrees","工作树管理","分支管理","powershell 脚本","安全默认设置","fetch 和 ff-only pull","AI 工具","AI 에이전트"],"ja":["PhysicsLab Worktrees","ワークツリー管理","ブランチ管理","powershell スクリプト","安全なデフォルト設定","fetch と ff-only pull","AI エージェント","開発ツール"],"ko":["PhysicsLab Worktrees","작업 트리 관리","분기 관리","powershell 스크립트","안전한 기본 설정","페치 및 ff-온리 풀","AI 도구","개발자ツール"],"es":["PhysicsLab Worktrees","Git para desarrolladores","Herramientas de Git","Worktrees en Git","Ramas en Git","desarrollo de software","control de versiones","Herramientas de desarrollo"],"fr":["PhysicsLab Worktrees","Git pour les développeurs","Outils Git","Worktrees dans Git","Branches dans Git","développement de logiciels","contrôle de version","Outils de développement"],"de":["PhysicsLab Worktrees","Git für Entwickler","Git-Tools","Worktrees in Git","Branches in Git","Software-Entwicklung","Versionskontrolle","Entwicklertools"],"pt":["PhysicsLab Worktrees","criação de branches","worktrees","desenvolvimento de software","ferramentas de desenvolvimento","PowerShell","git","controle de versão"],"ru":["PhysicsLab Worktrees","создание веток","рабочие деревья","разработка программного обеспечения","инструменты разработки","PowerShell","git","контроль версий","ИИ Агенты"],"ar":["PhysicsLab Worktrees","إنشاء فروع","وحدات العمل","تطوير البرمجيات","أدوات التطوير","PowerShell","git","مراقبة الإصدار","الأدوات الذكية"]}},"owner":"AhmedAlnasser2000","repo":"Science-Lab","repoPath":"AhmedAlnasser2000/Science-Lab","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.465Z","topics":[],"category":"community","skillMd":{"name":"physicslab_worktrees","description":"Start and clean PhysicsLab slice branches safely using git worktrees. Use when asked to create/start a slice branch (for example V5.5d2), start a milestone branch, or create a new worktree.","bodyPreview":"# PhysicsLab Worktrees\n\nUse this skill when the user asks to start a new slice/milestone branch or create a worktree.\n\n## Behavior\n\n1. If branch name is missing, ask for it.\n2. Start with safe defaults (no push):\n   - `powershell ./tools/dev/start_slice_worktree.ps1 -Branch work/vX.Yz`\n3. Remind the user:\n   - Do all work inside the created worktree folder.\n   - Push is disabled unless explicitly requested (`-Push`).\n   - The start script enforces `fetch + ff-only pull` for local `main` vs `orig","body":"# PhysicsLab Worktrees\n\nUse this skill when the user asks to start a new slice/milestone branch or create a worktree.\n\n## Behavior\n\n1. If branch name is missing, ask for it.\n2. Start with safe defaults (no push):\n   - `powershell ./tools/dev/start_slice_worktree.ps1 -Branch work/vX.Yz`\n3. Remind the user:\n   - Do all work inside the created worktree folder.\n   - Push is disabled unless explicitly requested (`-Push`).\n   - The start script enforces `fetch + ff-only pull` for local `main` vs `origin/main`; if main is ahead/diverged, repair main first.\n4. Before wrapping up a slice, always provide:\n   - one suggested PR title based on what was actually achieved in committed slice changes\n   - a descriptive PR summary/body that covers all major change themes in that branch/slice.\n5. If hot-reload gate workflow is active for the slice:\n   - start/maintain `tools/dev/slice_session.py` artifacts under `.slice_tmp/<slice_id>/`\n   - run gates sequentially by default (one gate, stop for user confirmation)\n   - only batch multiple gates when the user explicitly asks\n   - classify mid-gate changes and split into follow-up gates when scope/risk expands\n   - keep commit messages non-ambiguous with explicit follow-up suffixes when repeating scope.\n6. Before any push, enforce pre-push confirmation:\n   - print push plan with branch, upstream target, and commits to be pushed\n   - verify branch/slice match\n   - wait for explicit user approval\n   - if unclear, commit locally only and do not push.\n7. Enforce same-slice branch containment:\n   - keep all slice changes (code/docs/policies/tests/tweaks) on the same slice branch\n   - verify current branch against `.physicslab_worktree.json` when available\n   - if mismatch is detected, stop and present recovery plan before any commit/push\n   - do not push mixed-slice commit batches.\n8. Enforce no-leftover-commits + main-sync timing:\n   - at slice handoff (or before switching slices), run/report:\n     - `git status --short`\n     - `git log --oneline @{u}..` (or equivalent ahead check)\n   - if branch is ahead, either:\n     - push after pre-push confirmation, or\n     - record explicit user-approved deferral\n   - do not begin the next slice with implicit unpushed commits.\n   - sync `main` at two times:\n     - after PR merge: `fetch` + `checkout main` + `pull --ff-only`\n     - before starting the next slice: re-verify local `main` matches `origin/main`.\n9. Enforce PR conflict prevention + recovery:\n   - before each push to an open PR branch: `git fetch origin --prune` and check branch vs `origin/main`\n   - if branch is behind main, integrate first (`rebase origin/main` unless user requests merge)\n   - resolve conflicts locally, rerun required verification, then push\n   - when rebase rewrites history, use only `--force-with-lease` (never plain `--force`)\n   - still show pre-push plan and wait for approval before push\n   - if conflicts occur, record decisions in `.slice_tmp/<slice_id>/pr_conflict_recovery.md`\n   - if PR is already merged/closed, start a new follow-up branch from updated main instead of appending unrelated commits to the closed branch.\n9. If wrong-branch edits are discovered, run patch-first recovery:\n   - stop edits on wrong branch\n   - create `.slice_tmp/<slice_id>/wrong_branch_recovery.patch` in the correct slice\n   - export exact diff from wrong branch to that file\n   - reapply from patch artifact only (no memory retype)\n   - verify parity before commit (no missing/extra hunks)\n   - use commit message suffix `(recovered-from-wrong-branch)`\n   - report source branch, target branch, patch path, and verification method.\n\n## One-liners\n\n- Start (local only):\n  - `powershell ./tools/dev/start_slice_worktree.ps1 -Branch work/v5.5d2`\n- Start after syncing from remote main explicitly:\n  - `git fetch origin --prune; git checkout main; git pull --ff-only origin main; powershell ./tools/dev/start_slice_worktree.ps1 -Branch work/v5.5d2`\n- Start and push upstream (explicit only):\n  - `powershell ./tools/dev/start_slice_worktree.ps1 -Branch work/v5.5d2 -Push`\n- List worktrees:\n  - `powershell ./tools/dev/list_worktrees.ps1`\n- Cleanup worktree + local branch:\n  - `powershell ./tools/dev/remove_slice_worktree.ps1 -Branch work/v5.5d2 -DeleteBranch`\n"},"lastSynced":"2026-03-08T02:09:21.699Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing efficient Git worktree management and branch automation.","zh":"适合需要高效Git工作树管理和分支自动化的开发代理。","ja":"開発エージェントが効率的なGitのワークツリ管理とブランチ自動化を必要とする場合に最適です。","ko":"효율적인 Git 작업 트리 관리 및 분기 자동화가 필요한 개발 에이전트에게 적합합니다.","es":"Perfecto para agentes de desarrollo que necesitan una gestión eficiente de Git worktree y automatización de ramas.","fr":"Parfait pour les agents de développement ayant besoin d''une gestion efficace de Git worktree et d''automatisation de branches.","de":"Perfekt für Entwicklungsmittel, die eine effiziente Git-Worktree-Verwaltung und eine Automatisierung von Branches benötigen.","pt":"Perfeito para agentes de desenvolvimento que necessitam de gerenciamento eficiente de worktree do Git e automação de branch.","ru":"Идеально для агентов разработки, которым необходим эффективный менеджмент рабочего дерева Git и автоматизация веток.","ar":"مثالي لعميل التطوير الذين يحتاجون إلى إدارة كفؤة لشجرة العمل Git وتأتمة الفرع."},"recommendation":{"en":"Empowers agents to automate tasks such as starting new slice/milestone branches and enforcing best practices using PowerShell scripts like `start_slice_worktree.ps1`, while reminding users to work within created worktree folders and following safe defaults like `fetch + ff-only pull` for local `main` vs `origin` branches.","zh":"赋予代理自动执行任务的能力，例如启动新的切片/里程碑分支，并使用PowerShell脚本（如`start_slice_worktree.ps1`）强制执行最佳实践，同时提醒用户在创建的工作树文件夹中工作，并遵循本地`main`与`origin`分支的安全默认值（如`fetch + ff-only pull`）。","ja":"エージェントにタスクの自動化を可能にします。たとえば、新しいスライス/マイルストーン ブランチの作成と、PowerShell スクリプト（例： `start_slice_worktree.ps1`）を使用したベストプラクティスの適用を含み、作成されたワークツリーフォルダ内で作業し、ローカルの `main` ブランチと `origin` ブランチの安全なデフォルト（例： `fetch + ff-only pull`）に従うようにユーザーにリマインドします。","ko":"에이전트가 작업을 자동화 할 수 있도록 해줍니다. 예를 들어 새로운 슬라이스/마일스톤 분기의 생성과 PowerShell 스크립트(예: `start_slice_worktree.ps1`)를 사용한 최적의 관행 적용을 포함하며, 생성된 작업 트리 폴더 내에서 작업하고 로컬 `main` 브랜치와 `origin` 브랜치의 안전한 기본값(예: `fetch + ff-only pull`)을 따르도록 사용자에게 리마인드합니다.","es":"Habilita a los agentes a automatizar tareas como la creación de nuevas ramas de rebanada/hito y la aplicación de las mejores prácticas utilizando scripts de PowerShell como `start_slice_worktree.ps1`, mientras recuerda a los usuarios que trabajen dentro de las carpetas de worktree creadas y sigan los valores predeterminados seguros como `fetch + ff-only pull` para las ramas locales `main` vs `origin`.","fr":"Permet aux agents d''automatiser des tâches telles que la création de nouvelles branches de tranche/étape et l''application des meilleures pratiques en utilisant des scripts PowerShell comme `start_slice_worktree.ps1`, tout en rappelant aux utilisateurs de travailler dans les dossiers de worktree créés et en suivant les valeurs par défaut sécurisées comme `fetch + ff-only pull` pour les branches locales `main` vs `origin`.","de":"Ermächtigt die Agenten, Aufgaben wie die Erstellung neuer Slice/Milestone-Branches und die Durchsetzung von Best Practices mithilfe von PowerShell-Skripten wie `start_slice_worktree.ps1` zu automatisieren, während es den Benutzern in Erinnerung ruft, innerhalb der erstellten Worktree-Ordner zu arbeiten und sich an sichere Standardwerte wie `fetch + ff-only pull` für lokale `main`- vs. `origin`-Branches zu halten.","pt":"Habilita os agentes a automatizar tarefas como iniciar novas branchs de fatia/etapa e aplicar as melhores práticas usando scripts do PowerShell como `start_slice_worktree.ps1`, enquanto lembra os usuários de trabalhar dentro das pastas de worktree criadas e seguir padrões seguros como `fetch + ff-only pull` para branchs `main` locais versus branchs `origin`.","ru":"Наделяет агентов возможностью автоматизировать задачи, такие как создание новых веток среза/этапа и обеспечение соблюдения最佳 практик с помощью скриптов PowerShell, таких как `start_slice_worktree.ps1`, при этом напоминая пользователям работать в созданных папках worktree и следовать безопасным настройкам по умолчанию, таким как `fetch + ff-only pull` для локальных веток `main` по сравнению с ветками `origin`.","ar":"يمنح الوكلاء القدرة على تأتمة مهام مثل بدء فروع جديدة لقطعة/مرحلة وتطبيق أفضل الممارسات باستخدام نصوص PowerShell مثل `start_slice_worktree.ps1` ، في حين يذكر المستخدمين بالعمل داخل مجلدات شجرة العمل المُنشأة ومتابعة الإعدادات الافتراضية الآمنة مثل `fetch + ff-only pull` للفروع `main` المحلية مقابل الفروع `origin`."},"useCases":{"en":["Automating new slice/milestone branch creation","Managing worktrees efficiently with safe defaults","Enforcing best practices for Git workflow"],"zh":["自动化新的切片/里程碑分支创建","高效地管理工作树，使用安全默认值","强制执行Git工作流的最佳实践"],"ja":["新しいスライス/マイルストーン ブランチの作成の自動化","ワークツリの効率的な管理と安全なデフォルトの使用","Gitのワークフローのベストプラクティスの適用"],"ko":["새로운 슬라이스/마일스톤 분기 생성의 자동화","작업 트리의 효율적인 관리 및 안전한 기본값 사용","Git 작업 흐름의 최적의 관행 적용"],"es":["Automatización de la creación de nuevas ramas de rebanada/hito","Gestión eficiente de worktrees con valores predeterminados seguros","Aplicación de las mejores prácticas para el flujo de trabajo de Git"],"fr":["Automatisation de la création de nouvelles branches de tranche/étape","Gestion efficace des worktrees avec des valeurs par défaut sécurisées","Application des meilleures pratiques pour le flux de travail Git"],"de":["Automatisierung der Erstellung neuer Slice/Milestone-Branches","Effiziente Verwaltung von Worktrees mit sicheren Standardwerten","Durchsetzung von Best Practices für den Git-Workflow"],"pt":["Automação da criação de branchs de fatia/etapa novas","Gerenciamento eficiente de worktrees com padrões seguros","Aplicação de melhores práticas para fluxo de trabalho do Git"],"ru":["Автоматизация создания новых веток среза/этапа","Эффективное управление рабочими деревьями с безопасными настройками по умолчанию","Обеспечение соблюдения лучших практик для рабочего процесса Git"],"ar":["تأتمة إنشاء فروع جديدة لقطعة/مرحلة","إدارة كفؤة لشجرة العمل مع الإعدادات الافتراضية الآمنة","تطبيق أفضل الممارسات لسير عمل Git"]},"limitations":{"en":["Requires PowerShell execution capabilities","Git repository access needed","Limited to specific branch naming conventions (e.g., `work/vX.Yz`)"],"zh":["需要PowerShell执行能力","需要Git仓库访问","仅限于特定的分支命名约定（例如`work/vX.Yz`）"],"ja":["PowerShellの実行機能が必要","Gitリポジトリへのアクセスが必要","特定のブランチ命名規約（例： `work/vX.Yz`）に限定される"],"ko":["PowerShell 실행 기능이 필요합니다","Git 저장소 액세스가 필요합니다","특정한 분기 이름 규약(예: `work/vX.Yz`)으로 제한됩니다"],"es":["Requiere capacidades de ejecución de PowerShell","Se necesita acceso al repositorio de Git","Limitado a convenciones de nombres de ramas específicas (por ejemplo, `work/vX.Yz`)"],"fr":["Nécessite des capacités d''exécution PowerShell","L''accès au référentiel Git est nécessaire","Limité à des conventions de nommage de branches spécifiques (par exemple, `work/vX.Yz`)"],"de":["Benötigt PowerShell-Ausführungsfähigkeiten","Zugriff auf das Git-Repository erforderlich","Begrenzt auf bestimmte Branch-Namenskonventionen (z. B. `work/vX.Yz`)"],"pt":["Requer capacidades de execução do PowerShell","Acesso ao repositório Git necessário","Limitado a convenções específicas de nomenclatura de branchs (por exemplo, `work/vX.Yz`)"],"ru":["Требует возможности выполнения PowerShell","Необходим доступ к репозиторию Git","Ограничен конкретными соглашениями об именовании веток (например, `work/vX.Yz`)"],"ar":["يتطلب khảيات تشغيل PowerShell","مطلوب وصول إلى مستودع Git","محدود بالاتفاقيات المحددة لتسمية الفروع (على سبيل المثال `work/vX.Yz` )"]},"version":4},"contentHash":"d7e46af7f1d79762b2c6247e05696d04f55125b160a1775c644be2d6f6f0a798","qualityScore":23}');
