INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('pekral/php-skeleton/class-refactoring', 'class-refactoring', 'pekral', 'php-skeleton', 'community', 'class-refactoring pekral php-skeleton community The class-refactoring skill provides a basic skeleton for new PHP packages, helping developers analyze and optimize their code. It benefits PHP developers looking to improve their package structure. PHP 类重构是提高代码质量和可维护性的关键步骤，通过分析和优化类结构实现现代化和高效的代码 PHP クラスリファクタリングは、コードの品質とメンテナンス性を向上させるための重要なステップです PHP 클래스 리팩토링은 코드의 품질과 유지보수성을 향상시키기 위한 중요한 단계입니다 Nuestra herramienta de class-refactoring para PHP ayuda a mejorar la calidad del código mediante la refactorización de clases, análisis de código y verificación de cobertura Notre outil de refactoring de classes pour PHP aide à améliorer la qualité du code en refactorisant des classes, en analysant le code et en vérifiant la couverture Unser class-refactoring-Tool für PHP hilft dabei, die Code-Qualität durch die Refactoring von Klassen, Code-Analyse und Abdeckungsprüfung zu verbessern Refatoração de classe para PHP, com foco em código limpo, moderno e otimizado Рефакторинг классов для PHP, с фокусом на чистом, современном и оптимизированном коде إعادة هيكلة الفئة لبي إتش بي، مع التركيز على الكود النظيف والحديث والمحسّن how to use class-refactoring class-refactoring for PHP developers PHP package optimization techniques class-refactoring vs PHPStan class-refactoring setup guide PHP class refactoring best practices PHP 类重构 PHP 包优化 代码质量提高 可维护性提高 PHPDoc PHPStan stateless PHP 类 集合代替 foreach 代码覆盖率验证 Analyzes classes and completes TODO list tasks Verifies code coverage after refactoring Preserves functionality with stateless PHP classes Utilizes collections over foreach where appropriate Supports PHPDoc for PHPStan class-refactoring is a skill that provides a basic skeleton for new PHP packages, focusing on clean, modern, and optimized code with PHPDoc for PHPStan');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('makaronz/agent66/ordercli', 'community', 'makaronz', 'agent66', 'makaronz/agent66', 'ordercli', 0, 0, 23, '2026-03-08T01:57:15.473Z', '2026-03-08T02:09:40.448Z', '14aef89ed6dad8e3f5712f172d7580623d5bf64f70914788a8fad96e9ec45f66', '{"id":"makaronz/agent66/ordercli","name":"ordercli","description":{"en":"ordercli is a command-line tool for managing Foodora orders. It allows users to check past orders and track active order status.","zh":"ordercli是一个命令行工具，用于跟踪Foodora的订单状态和历史记录。它提供了快速的订单管理和状态跟踪功能","ja":"ordercliは、Foodoraの注文状態と履歴を追跡するためのコマンドラインツールです。迅速な注文管理と状態追跡機能を提供します","ko":"ordercli는 Foodora의 주문 상태와 기록을 추적하는 명령줄 도구입니다. 빠른 주문 관리와 상태 추적 기능을 제공합니다","es":"Ordercli es una herramienta de línea de comandos para verificar pedidos pasados y rastrear el estado de pedidos activos en Foodora","fr":"Ordercli est un outil en ligne de commande pour vérifier les commandes passées et suivre le statut des commandes actives sur Foodora","de":"Ordercli ist ein Kommandozeilen-Tool, um vergangene Bestellungen zu überprüfen und den Status von aktiven Bestellungen in Foodora zu verfolgen","pt":"ordercli é uma ferramenta de linha de comando para gerenciar pedidos e rastrear status de entrega. Confira nossa documentação para começar a usar","ru":"ordercli - это инструмент командной строки для управления заказами и отслеживания статуса доставки. Прочитайте нашу документацию, чтобы начать использовать","ar":"ordercli هو أداة سطر الأوامر لإدارة الطلبات وتتبع حالة التسليم. راجع وثائقنا لبدء استخدام"},"seo":{"title":{"en":"ordercli: Foodora Order Management Setup Guide | AI Agent...","zh":"ordercli Setup Guide -Foodora 订单跟踪工具","ja":"ordercli のベストプラクティス - AIエージェントを使用したFoodora注文管理","ko":"ordercli 사용법 - Foodora 주문 상태 추적 도구","es":"Guía de configuración de ordercli para desarrolladores","fr":"Guide de démarrage rapide pour ordercli","de":"Ordercli-Setup-Anleitung für Entwickler","pt":"Guia de Configuração ordercli: Ferramentas de Gerenciamen...","ru":"Настройка ordercli: Руководство по управлению заказами с ...","ar":"إعداد ordercli: دليل لإدارة الطلبات باستخدام أدوات الذكاء..."},"description":{"en":"Discover how to track active orders and check past orders with ordercli. Learn to set up and use ordercli for Foodora with our expert guide.","zh":"了解ordercli的功能和用法，快速跟踪Foodora的订单状态和历史记录","ja":"ordercliを使用してFoodoraの注文を管理し、状態を追跡する方法を学びます","ko":"ordercli를 사용하여 Foodora의 주문 상태와 기록을 쉽게 추적하는 방법을 알아보세요","es":"Aprende a utilizar ordercli para verificar pedidos pasados y rastrear el estado de pedidos activos en Foodora","fr":"Découvrez comment utiliser ordercli pour vérifier les commandes passées et suivre le statut des commandes actives sur Foodora","de":"Erfahren Sie, wie Sie ordercli verwenden, um vergangene Bestellungen zu überprüfen und den Status von aktiven Bestellungen in Foodora zu verfolgen","pt":"Aprenda a usar ordercli para gerenciar pedidos e rastrear status de entrega. Confira nossa documentação para começar","ru":"Узнайте, как использовать ordercli для управления заказами и отслеживания статуса доставки. Прочитайте нашу документацию, чтобы начать","ar":"تعلم كيفية استخدام ordercli لإدارة الطلبات وتتبع حالة التسليم. راجع وثائقنا لبدء استخدام"},"definition":{"en":"ordercli is a command-line interface for interacting with Foodora''s order system, enabling users to retrieve and monitor order information.","zh":"ordercli是一种命令行工具，用于跟踪和管理Foodora的订单","ja":"ordercliは、Foodoraの注文を管理および追跡するためのコマンドラインツールです","ko":"ordercli는 Foodora의 주문 상태를 추적하고 관리하는 명령줄 도구입니다","es":"Ordercli es una herramienta de línea de comandos para la gestión de pedidos","fr":"Ordercli est un outil en ligne de commande pour la gestion de commandes","de":"Ordercli ist ein Kommandozeilen-Tool für die Bestellverwaltung","pt":"ordercli é uma ferramenta de gerenciamento de pedidos que permite verificar pedidos passados e rastrear status de entrega","ru":"ordercli - это инструмент управления заказами, который позволяет проверять прошлые заказы и отслеживать статус доставки","ar":"ordercli هو أداة لإدارة الطلبات التي تمكنك من التحقق من الطلبات السابقة وتتبع حالة التسليم"},"features":{"en":["Runs `ordercli foodora countries` to retrieve available countries","Supports setting configuration with `ordercli foodora config set --country AT`","Enables login functionality via `ordercli foodora login --email you@example.com --password-stdin`","Displays active orders with `ordercli foodora orders` and watch functionality with `--watch` flag","Provides order history with `ordercli foodora history --limit 20` and detailed order information with `ordercli foodora history show <orderCode>`"],"zh":["支持Foodora的订单状态跟踪","提供快速的订单管理功能","可以查看订单历史记录","支持命令行界面","可以设置国家和登录信息","支持实时订单状态更新"],"ja":["Foodoraの注文状態の追跡をサポート","迅速な注文管理機能を提供","注文履歴を表示可能","コマンドラインインターフェースをサポート","国とログイン情報を設定可能","リアルタイムの注文状態更新をサポート"],"ko":["Foodora의 주문 상태 추적을 지원","빠른 주문 관리 기능을 제공","주문 기록을查看할 수 있습니다","명령줄 인터페이스를 지원","나라와 로그인 정보를 설정할 수 있습니다","실시간 주문 상태 업데이트를 지원"],"es":["Verificación de pedidos pasados","Rastreo del estado de pedidos activos","Soporte para configuración de países","Inicio de sesión seguro con contraseña","Visualización de historial de pedidos","Opción de ver pedidos activos con actualización en tiempo real"],"fr":["Vérification des commandes passées","Suivi du statut des commandes actives","Prise en charge de la configuration de pays","Connexion sécurisée avec mot de passe","Affichage de l''historique des commandes","Option pour afficher les commandes actives avec mise à jour en temps réel"],"de":["Überprüfung von vergangenen Bestellungen","Verfolgung des Status von aktiven Bestellungen","Unterstützung für Länderkonfiguration","Sichere Anmeldung mit Passwort","Anzeige des Bestellverlaufs","Option zum Anzeigen von aktiven Bestellungen mit Echtzeit-Aktualisierung"],"pt":["Verificar pedidos passados","Rastrear status de entrega","Suporte a múltiplos países","Configuração de login e senha","Listagem de pedidos ativos","Visualização de histórico de pedidos"],"ru":["Проверка прошлых заказов","Отслеживание статуса доставки","Поддержка нескольких стран","Настройка входа и пароля","Список активных заказов","Просмотр истории заказов"],"ar":["التحقق من الطلبات السابقة","تتبع حالة التسليم","دعم بلدان متعددة","إعداد تسجيل الدخول وكلمة المرور","قائمة الطلبات النشطة","عرض تاريخ الطلبات"]},"keywords":{"en":["how to use ordercli","ordercli setup guide","ordercli foodora integration","ordercli alternative","ordercli vs foodora api","ordercli install","what is ordercli","ordercli command-line tool","ordercli order tracking"],"zh":["ordercli","Foodora","命令行工具","订单状态跟踪","快速订单管理","AIエージェント","命令行界面","订单历史记录"],"ja":["ordercli","Foodora","コマンドラインツール","注文状態の追跡","迅速な注文管理","AIエージェント","コマンドラインインターフェース","注文履歴"],"ko":["ordercli","Foodora","명령줄 도구","주문 상태 추적","빠른 주문 관리","AI 에이전트","명령줄 인터페이스","주문 기록"],"es":["ordercli","herramienta de línea de comandos","gestión de pedidos","Foodora","verificación de pedidos","rastreo de pedidos","configuración de países","inicio de sesión seguro"],"fr":["ordercli","outil en ligne de commande","gestion de commandes","Foodora","vérification de commandes","suivi de commandes","configuration de pays","connexion sécurisée"],"de":["ordercli","Kommandozeilen-Tool","Bestellverwaltung","Foodora","Überprüfung von Bestellungen","Verfolgung von Bestellungen","Länderkonfiguration","sichere Anmeldung"],"pt":["ordercli","gerenciamento de pedidos","rastreamento de entrega","ferramentas de linha de comando","CLI","gerenciamento de pedidos online","rastreamento de status de entrega","configuração de login","visualização de histórico de pedidos"],"ru":["ordercli","управление заказами","отслеживание доставки","инструменты командной строки","CLI","управление заказами онлайн","отслеживание статуса доставки","настройка входа","просмотр истории заказов","ИИ Агенты"],"ar":["ordercli","إدارة الطلبات","تتبع التسليم","أدوات سطر الأوامر","CLI","إدارة الطلبات عبر الإنترنت","تتبع حالة التسليم","إعداد تسجيل الدخول","عرض تاريخ الطلبات","أدوات الذكاء الاصطناعي"]}},"owner":"makaronz","repo":"agent66","repoPath":"makaronz/agent66","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.473Z","topics":[],"category":"community","skillMd":{"name":"ordercli","description":"Foodora-only CLI for checking past orders and active order status (Deliveroo WIP).","bodyPreview":"# ordercli\n\nUse `ordercli` to check past orders and track active order status (Foodora only right now).\n\nQuick start (Foodora)\n\n- `ordercli foodora countries`\n- `ordercli foodora config set --country AT`\n- `ordercli foodora login --email you@example.com --password-stdin`\n- `ordercli foodora orders`\n- `ordercli foodora history --limit 20`\n- `ordercli foodora history show <orderCode>`\n\nOrders\n\n- Active list (arrival/status): `ordercli foodora orders`\n- Watch: `ordercli foodora orders --watch`\n- Ac","body":"# ordercli\n\nUse `ordercli` to check past orders and track active order status (Foodora only right now).\n\nQuick start (Foodora)\n\n- `ordercli foodora countries`\n- `ordercli foodora config set --country AT`\n- `ordercli foodora login --email you@example.com --password-stdin`\n- `ordercli foodora orders`\n- `ordercli foodora history --limit 20`\n- `ordercli foodora history show <orderCode>`\n\nOrders\n\n- Active list (arrival/status): `ordercli foodora orders`\n- Watch: `ordercli foodora orders --watch`\n- Active order detail: `ordercli foodora order <orderCode>`\n- History detail JSON: `ordercli foodora history show <orderCode> --json`\n\nReorder (adds to cart)\n\n- Preview: `ordercli foodora reorder <orderCode>`\n- Confirm: `ordercli foodora reorder <orderCode> --confirm`\n- Address: `ordercli foodora reorder <orderCode> --confirm --address-id <id>`\n\nCloudflare / bot protection\n\n- Browser login: `ordercli foodora login --email you@example.com --password-stdin --browser`\n- Reuse profile: `--browser-profile \"$HOME/Library/Application Support/ordercli/browser-profile\"`\n- Import Chrome cookies: `ordercli foodora cookies chrome --profile \"Default\"`\n\nSession import (no password)\n\n- `ordercli foodora session chrome --url https://www.foodora.at/ --profile \"Default\"`\n- `ordercli foodora session refresh --client-id android`\n\nDeliveroo (WIP, not working yet)\n\n- Requires `DELIVEROO_BEARER_TOKEN` (optional `DELIVEROO_COOKIE`).\n- `ordercli deliveroo config set --market uk`\n- `ordercli deliveroo history`\n\nNotes\n\n- Use `--config /tmp/ordercli.json` for testing.\n- Confirm before any reorder or cart-changing action.\n"},"lastSynced":"2026-03-08T02:09:40.448Z","agentAnalysis":{"suitability":{"en":"Perfect for E-commerce Agents needing streamlined order management capabilities for Foodora","zh":"非常适合需要为 Foodora 提供简化订单管理功能的电子商务智能体。","ja":"Foodora の効率化された注文管理機能を必要とする E コマース エージェントに最適です。","ko":"Foodora를 위한 간소화된 주문 관리 기능이 필요한 전자상거래 에이전트에 완벽합니다.","es":"Perfecto para Agentes de Comercio Electrónico que necesitan capacidades de gestión de pedidos simplificadas para Foodora","fr":"Parfait pour les agents de commerce électronique ayant besoin de capacités de gestion de commandes simplifiées pour Foodora","de":"Perfekt für E-Commerce-Agents, die vereinfachte Bestellmanagementfunktionen für Foodora benötigen","pt":"Perfeito para Agentes de Comércio Eletrônico que precisam de capacidades de gerenciamento de pedidos simplificados para Foodora","ru":"Идеально подходит для агентов электронной коммерции, которым необходимы упрощенные возможности управления заказами для Foodora","ar":"مثالي للوكلاء التجاريين الذين يحتاجون إلى إمكانيات إدارة الطلبات المبسطة لـ Foodora"},"recommendation":{"en":"Empowers agents to track active order status and retrieve past orders using command-line interfaces, leveraging Foodora''s API for seamless integration and providing features like order history and real-time status updates","zh":"使智能体能够使用命令行界面跟踪活动订单状态并检索历史订单，利用 Foodora 的 API 实现无缝集成，并提供订单历史和实时状态更新等功能。","ja":"コマンドライン インターフェースを利用して、アクティブな注文ステータスを追跡し、過去の注文を取得する機能をエージェントに付与し、Foodora の API を活用したシームレスな統合と、注文履歴やリアルタイムのステータス更新などの機能を提供します。","ko":"Foodora의 API를 활용하여 원활한 통합을 제공하고, 주문 내역 및 실시간 상태 업데이트와 같은 기능을 제공하며, 명령줄 인터페이스를 사용하여 활성 주문 상태를 추적하고 과거 주문을 검색할 수 있도록 에이전트에 권한을 부여합니다.","es":"Habilita a los agentes a realizar un seguimiento del estado de los pedidos activos y a recuperar pedidos anteriores utilizando interfaces de línea de comandos, aprovechando la API de Foodora para una integración sin problemas y proporcionando características como el historial de pedidos y las actualizaciones de estado en tiempo real","fr":"Permet aux agents de suivre l''état des commandes actives et de récupérer les commandes passées en utilisant des interfaces en ligne de commande, en exploitant l''API de Foodora pour une intégration transparente et en fournissant des fonctionnalités comme l''historique des commandes et les mises à jour de statut en temps réel","de":"Ermächtigt die Agenten, den Status der aktiven Bestellungen zu verfolgen und vergangene Bestellungen mithilfe von Kommandozeilen-Schnittstellen abzurufen, indem die API von Foodora für eine nahtlose Integration genutzt wird und Funktionen wie Bestellhistorie und Echtzeit-Status-Updates bereitgestellt werden","pt":"Permite que os agentes accompanies o status do pedido ativo e recuperem pedidos anteriores usando interfaces de linha de comando, aproveitando a API da Foodora para integração sem problemas e fornecendo recursos como histórico de pedidos e atualizações de status em tempo real","ru":"Предоставляет агентам возможность отслеживать активный статус заказа и получать прошлые заказы, используя командные интерфейсы, используя API Foodora для бесшовной интеграции и предоставляя функции, такие как история заказов и обновления статуса в реальном времени","ar":"تمكّن الوكلاء من تتبع حالة الطلب الفعّال واسترجاع الطلبات السابقة باستخدام واجهات سطر الأوامر، مستفيدًا من واجهة برمجة التطبيقات Foodora من أجل التكامل السلس و提供 ميزات مثل سجل الطلبات وتحديثات الحالة في الوقت الفعلي"},"useCases":{"en":["Tracking active Foodora orders","Retrieving past order history","Monitoring order status updates in real-time"],"zh":["跟踪 Foodora 的活动订单","检索过去的订单历史记录","实时监控订单状态更新"],"ja":["Foodora のアクティブな注文の追跡","過去の注文履歴の取得","リアルタイムでの注文ステータス更新の監視"],"ko":["활성 Foodora 주문 추적","과거 주문 내역 검색","실시간으로 주문 상태 업데이트 모니터링"],"es":["Seguimiento de pedidos activos de Foodora","Recuperación del historial de pedidos anteriores","Monitoreo de actualizaciones de estado de pedidos en tiempo real"],"fr":["Suivi des commandes actives de Foodora","Récupération de l''historique des commandes passées","Surveillance des mises à jour de statut des commandes en temps réel"],"de":["Verfolgung von aktiven Foodora-Bestellungen","Abrufen der Historie von vergangenen Bestellungen","Überwachung von Echtzeit-Status-Updates von Bestellungen"],"pt":["Acompanhamento de pedidos ativos da Foodora","Recuperação do histórico de pedidos anteriores","Monitoramento de atualizações de status de pedido em tempo real"],"ru":["Отслеживание активных заказов Foodora","Получение истории прошлых заказов","Мониторинг обновлений статуса заказа в реальном времени"],"ar":["تتبع الطلبات الفعّالة لـ Foodora","استرجاع سجل الطلبات السابقة","مراقبة تحديثات حالة الطلب في الوقت الفعلي"]},"limitations":{"en":["Limited to Foodora orders only","Requires user login credentials for authentication"],"zh":["仅限于 Foodora 订单","需要用户登录凭据进行身份验证"],"ja":["Foodora の注文に限定される","認証にはユーザーのログイン資格情報が必要"],"ko":["Foodora 주문으로만 제한됨","인증을 위해 사용자 로그인 자격 증명이 필요함"],"es":["Limitado solo a pedidos de Foodora","Requiere credenciales de inicio de sesión de usuario para la autenticación"],"fr":["Limité aux commandes de Foodora uniquement","Nécessite des informations d''identification de connexion de l''utilisateur pour l''authentification"],"de":["Begrenzt auf Foodora-Bestellungen","Benötigt Benutzeranmeldeinformationen für die Authentifizierung"],"pt":["Limitado a pedidos da Foodora apenas","Exige credenciais de login do usuário para autenticação"],"ru":["Ограничен только заказами Foodora","Требует учетных данных пользователя для аутентификации"],"ar":["محدود بالطلبات من Foodora فقط","يتطلب بيانات اعتماد تسجيل الدخول للمستخدم من أجل المصادقة"]},"version":4},"contentHash":"14aef89ed6dad8e3f5712f172d7580623d5bf64f70914788a8fad96e9ec45f66","qualityScore":23}');
