INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('makaronz/agent66/ordercli', 'ordercli', 'makaronz', 'agent66', 'community', 'ordercli makaronz agent66 community ordercli is a command-line tool for managing Foodora orders. It allows users to check past orders and track active order status. ordercli是一个命令行工具，用于跟踪Foodora的订单状态和历史记录。它提供了快速的订单管理和状态跟踪功能 ordercliは、Foodoraの注文状態と履歴を追跡するためのコマンドラインツールです。迅速な注文管理と状態追跡機能を提供します ordercli는 Foodora의 주문 상태와 기록을 추적하는 명령줄 도구입니다. 빠른 주문 관리와 상태 추적 기능을 제공합니다 Ordercli es una herramienta de línea de comandos para verificar pedidos pasados y rastrear el estado de pedidos activos en Foodora Ordercli est un outil en ligne de commande pour vérifier les commandes passées et suivre le statut des commandes actives sur Foodora Ordercli ist ein Kommandozeilen-Tool, um vergangene Bestellungen zu überprüfen und den Status von aktiven Bestellungen in Foodora zu verfolgen ordercli é uma ferramenta de linha de comando para gerenciar pedidos e rastrear status de entrega. Confira nossa documentação para começar a usar ordercli - это инструмент командной строки для управления заказами и отслеживания статуса доставки. Прочитайте нашу документацию, чтобы начать использовать ordercli هو أداة سطر الأوامر لإدارة الطلبات وتتبع حالة التسليم. راجع وثائقنا لبدء استخدام how to use ordercli ordercli setup guide ordercli foodora integration ordercli alternative ordercli vs foodora api ordercli install what is ordercli ordercli command-line tool ordercli order tracking ordercli Foodora 命令行工具 订单状态跟踪 快速订单管理 AIエージェント 命令行界面 订单历史记录 Runs `ordercli foodora countries` to retrieve available countries Supports setting configuration with `ordercli foodora config set --country AT` Enables login functionality via `ordercli foodora login --email you@example.com --password-stdin` Displays active orders with `ordercli foodora orders` and watch functionality with `--watch` flag Provides order history with `ordercli foodora history --limit 20` and detailed order information with `ordercli foodora history show <orderCode>` ordercli is a command-line interface for interacting with Foodora''s order system, enabling users to retrieve and monitor order information.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('macho715/tr_dash/tr-dashboard-autopilot', 'community', 'macho715', 'tr_dash', 'macho715/tr_dash', 'tr-dashboard-autopilot', 0, 0, 23, '2026-03-08T01:57:15.474Z', '2026-03-08T02:09:41.495Z', 'fbd7193bd5c1b87860b80afb0222bcbae0afc22ba815208e6493293fb8d29b71', '{"id":"macho715/tr_dash/tr-dashboard-autopilot","name":"tr-dashboard-autopilot","description":{"en":"The tr-dashboard-autopilot skill automates TR dashboard setup, benefiting developers by generating plans and verifying implementations. It utilizes AGENTS.md and option_c.json for configuration.","zh":"TR Dashboard Autopilot 是一个基于 AGENTS.md 的自动化计划和验证报告生成工具，支持 option_c.json 配置","ja":"TR ダッシュボード オートパイロットは、AGENTS.md に基づく自動計画と検証レポートの生成ツールです。option_c.json 設定をサポートします","ko":"TR 대시보드 오토파일럿은 AGENTS.md 기반 자동 계획과 검증 리포트 생성 도구로서 option_c.json 설정을 지원합니다","es":"tr-dashboard-autopilot es una habilidad que automatiza la planificación y verificación de tareas con agente de AI. Utiliza option_c.json para configurar flujos y modos.","fr":"tr-dashboard-autopilot est une compétence qui automatise la planification et la vérification de tâches avec un outil d''IA. Il utilise option_c.json pour configurer les flux et les modes.","de":"tr-dashboard-autopilot ist eine Fähigkeit, die die Planung und Verifizierung von Aufgaben mit einem KI-Agenten automatisiert. Sie verwendet option_c.json, um Flüsse und Modi zu konfigurieren.","pt":"O TR Dashboard Autopilot é uma ferramenta que automatiza tarefas de planejamento e implementação com base em AGENTS.md e option_c.json.","ru":"TR Dashboard Autopilot - это инструмент, который автоматизирует задачи планирования и реализации на основе AGENTS.md и option_c.json.","ar":"تطبيق TR Dashboard Autopilot هو أداة ت自动 عمليات التخطيط والتنفيذ بالاعتماد على AGENTS.md و option_c.json"},"seo":{"title":{"en":"tr-dashboard-autopilot: Automated TR Dashboard Setup Guid...","zh":"TR Dashboard Autopilot 设置指南 - 基于 AGENTS.md 的自动化计划","ja":"TR ダッシュボード オートパイロットの設定方法 - AGENTS.md に基づく自動計画","ko":"TR 대시보드 오토파일럿 설정 가이드 - AGENTS.md 기반 자동 계획","es":"Guía de configuración de tr-dashboard-autopilot para agen...","fr":"Guide de mise en route de tr-dashboard-autopilot pour out...","de":"Einrichtungsanleitung für tr-dashboard-autopilot als KI-A...","pt":"Guia de Configuração do TR Dashboard Autopilot","ru":"ИИ Агенты: Настройка TR Dashboard Autopilot","ar":"إعداد تطبيق TR Dashboard Autopilot"},"description":{"en":"Discover how tr-dashboard-autopilot streamlines TR dashboard creation. Learn to automate plan generation, implementation, and verification with this AI agent...","zh":"了解 TR Dashboard Autopilot 的功能和特点，实现基于 AGENTS.md 的自动化计划和验证报告的生成","ja":"TR ダッシュボード オートパイロットの機能と特徴を紹介します。AGENTS.md に基づく自動計画と検証レポートの生成を実現します","ko":"TR 대시보드 오토파일럿의 기능과 특징을紹介합니다. AGENTS.md 기반 자동 계획과 검증 리포트의 생성을 실현합니다","es":"Aprende a configurar tr-dashboard-autopilot para automatizar tareas de planificación y verificación con agente de AI","fr":"Découvrez comment configurer tr-dashboard-autopilot pour automatiser les tâches de planification et de vérification avec un outil d''IA","de":"Erfahren Sie, wie Sie tr-dashboard-autopilot einrichten, um Planungs- und Verifizierungsaufgaben mit einem KI-Agenten zu automatisieren","pt":"Aprenda a configurar o TR Dashboard Autopilot para automatizar tarefas de planejamento e implementação com base em AGENTS.md e option_c.json","ru":"Откройте возможности ИИ Агентов с помощью TR Dashboard Autopilot: автоматизируйте планирование и реализацию на основе AGENTS.md и option_c.json","ar":"تعلم كيفية إعداد تطبيق TR Dashboard Autopilot لتحسين عملية التخطيط والتنفيذ بالاعتماد على AGENTS.md و option_c.json"},"definition":{"en":"tr-dashboard-autopilot is an AI agent skill that automates the creation and verification of TR dashboards, using inputs like AGENTS.md and option_c.json to generate plans and reports.","zh":"TR Dashboard Autopilot 是一种 AI 工具，用于自动化计划和验证报告的生成","ja":"TR ダッシュボード オートパイロットは、AI エージェントの一種で、自動計画と検証レポートの生成を担当します","ko":"TR 대시보드 오토파일럿은 AI 에이전트의 일종으로 자동 계획과 검증 리포트의 생성을 담당합니다","es":"tr-dashboard-autopilot es una habilidad de agente de AI que automatiza la planificación y verificación de tareas","fr":"tr-dashboard-autopilot est une compétence d''outil d''IA qui automatise la planification et la vérification de tâches","de":"tr-dashboard-autopilot ist eine Fähigkeit von KI-Agenten, die die Planung und Verifizierung von Aufgaben automatisiert","pt":"O que é TR Dashboard Autopilot? É uma ferramenta de automação de tarefas de planejamento e implementação.","ru":"Что такое TR Dashboard Autopilot? Это инструмент для автоматизации задач планирования и реализации.","ar":"ما هو تطبيق TR Dashboard Autopilot? هو أداة لتحسين عمليات التخطيط والتنفيذ"},"features":{"en":["Generates TR dashboard plans using /tr-planner","Implements tasks using /tr-implementer","Validates implementations with ssot-guard or valida","Creates verification reports in docs/plan/tr-dashboard-verification-report.md","Utilizes option_c.json for SSOT configuration","Processes AGENTS.md for task planning"],"zh":["基于 AGENTS.md 的自动化计划生成","支持 option_c.json 配置","自动生成计划文档（docs/plan/tr-dashboard-plan.md）","自动生成验证报告（docs/plan/tr-dashboard-verification-report.md）","集成 ssot-guard 和 valida 检验"],"ja":["AGENTS.md に基づく自動計画の生成","option_c.json 設定をサポート","計画文書（docs/plan/tr-dashboard-plan.md）の自動生成","検証レポート（docs/plan/tr-dashboard-verification-report.md）の自動生成","ssot-guard と valida 検証の統合"],"ko":["AGENTS.md 기반 자동 계획 생성","option_c.json 설정 지원","계획 문서（docs/plan/tr-dashboard-plan.md）的 자동 생성","검증 리포트（docs/plan/tr-dashboard-verification-report.md）的 자동 생성","ssot-guard 및 valida 검증의 통합"],"es":["Automatización de tareas de planificación y verificación","Uso de option_c.json para configurar flujos y modos","Integración con /tr-planner para generar planes","Ejecución de tareas con /tr-implementer","Verificación de resultados con ssot-guard"],"fr":["Automatisation des tâches de planification et de vérification","Utilisation de option_c.json pour configurer les flux et les modes","Intégration avec /tr-planner pour générer des plans","Exécution de tâches avec /tr-implementer","Vérification des résultats avec ssot-guard"],"de":["Automatisierung von Planungs- und Verifizierungsaufgaben","Verwendung von option_c.json, um Flüsse und Modi zu konfigurieren","Integration mit /tr-planner, um Pläne zu generieren","Ausführung von Aufgaben mit /tr-implementer","Verifizierung von Ergebnissen mit ssot-guard"],"pt":["Criação de planos de implementação com base em AGENTS.md","Automatização de tarefas de implementação com base em option_c.json","Integração com /tr-planner para criação de planos","Integração com /tr-implementer para execução de tarefas","Suporte a validação com ssot-guard"],"ru":["Создание планов реализации на основе AGENTS.md","Автоматизация задач реализации на основе option_c.json","Интеграция с /tr-planner для создания планов","Интеграция с /tr-implementer для выполнения задач","Поддержка валидации с помощью ssot-guard"],"ar":["إنشاء خطط تنفيذ بالاعتماد على AGENTS.md","تحسين عمليات التنفيذ بالاعتماد على option_c.json","التكامل مع /tr-planner لإنشاء خطط","التكامل مع /tr-implementer لتنفيذ المهام","دعم التحقق بالاعتماد على ssot-guard"]},"keywords":{"en":["how to use tr-dashboard-autopilot","tr-dashboard-autopilot setup guide","tr-dashboard-autopilot alternative","tr-dashboard-autopilot vs manual setup","automating TR dashboard creation","AGENTS.md configuration","option_c.json tutorial","tr-dashboard-autopilot install","tr-dashboard-autopilot documentation"],"zh":["TR Dashboard Autopilot","AI 工具","自动化计划","验证报告","AGENTS.md","option_c.json","ssot-guard","valida"],"ja":["TR ダッシュボード オートパイロット","AI エージェント","自動計画","検証レポート","AGENTS.md","option_c.json","ssot-guard","valida"],"ko":["TR 대시보드 오토파일럿","AI 에이전트","자동 계획","검증 리포트","AGENTS.md","option_c.json","ssot-guard","valida"],"es":["agente de AI","automatización de tareas","planificación y verificación","option_c.json","tr-dashboard-autopilot","guias de configuración de AI","herramientas de automatización de tareas"],"fr":["outil d''IA","automatisation de tâches","planification et vérification","option_c.json","tr-dashboard-autopilot","guides de configuration d''IA","outils d''automatisation de tâches"],"de":["KI-Agent","Automatisierung von Aufgaben","Planung und Verifizierung","option_c.json","tr-dashboard-autopilot","Einrichtungsanleitungen für KI","Werkzeuge für die Automatisierung von Aufgaben"],"pt":["TR Dashboard Autopilot","AGENTS.md","option_c.json","automação de tarefas","planejamento de implementação","integração com /tr-planner","integração com /tr-implementer","validação com ssot-guard"],"ru":["ИИ Агенты","TR Dashboard Autopilot","AGENTS.md","option_c.json","автоматизация задач","планирование реализации","интеграция с /tr-planner","интеграция с /tr-implementer","валидация с помощью ssot-guard"],"ar":["تطبيقات الذكاء الاصطناعي","TR Dashboard Autopilot","AGENTS.md","option_c.json","تحسين عمليات التخطيط","تحسين عمليات التنفيذ","التكامل مع /tr-planner","التكامل مع /tr-implementer","دعم التحقق بالاعتماد على ssot-guard"]}},"owner":"macho715","repo":"tr_dash","repoPath":"macho715/tr_dash","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.474Z","topics":[],"category":"community","skillMd":{"name":"tr-dashboard-autopilot","description":"End-to-end autopilot for TR 이동 대시보드. Use to generate a plan from AGENTS.md, implement in small steps, and run lint/typecheck/test/build with SSOT(option_c.json) guardrails via subagents.","bodyPreview":"# TR Dashboard Autopilot\n\n## 언제 사용\n- \"AGENTS.md 기반으로 plan 문서부터 최종 테스트까지 에이전트가 혼자\" 수행해야 할 때\n- option_c.json(SSOT) 기반 일정/리플로우/충돌/모드 분리를 구현/검증할 때\n\n## 입력\n- 레포의 `AGENTS.md` (가장 가까운 파일 우선)\n- SSOT: `option_c.json`\n\n## 출력\n- `docs/plan/tr-dashboard-plan.md` (Plan)\n- `docs/plan/tr-dashboard-verification-report.md` (최종 검증 리포트)\n\n## 실행 오케스트레이션\n1) **Plan 생성**\n   - `/tr-planner`를 호출해 `docs/plan/tr-dashboard-plan.md` 생성\n2) **구현 루프**\n   - plan의 Task를 1개씩 `/tr-implementer`로 수행\n   - 각 Task 후 `ssot-guard`(또는 valida","body":"# TR Dashboard Autopilot\n\n## 언제 사용\n- \"AGENTS.md 기반으로 plan 문서부터 최종 테스트까지 에이전트가 혼자\" 수행해야 할 때\n- option_c.json(SSOT) 기반 일정/리플로우/충돌/모드 분리를 구현/검증할 때\n\n## 입력\n- 레포의 `AGENTS.md` (가장 가까운 파일 우선)\n- SSOT: `option_c.json`\n\n## 출력\n- `docs/plan/tr-dashboard-plan.md` (Plan)\n- `docs/plan/tr-dashboard-verification-report.md` (최종 검증 리포트)\n\n## 실행 오케스트레이션\n1) **Plan 생성**\n   - `/tr-planner`를 호출해 `docs/plan/tr-dashboard-plan.md` 생성\n2) **구현 루프**\n   - plan의 Task를 1개씩 `/tr-implementer`로 수행\n   - 각 Task 후 `ssot-guard`(또는 validate_optionc) 실행\n3) **최종 검증**\n   - `/tr-verifier`로 lint/typecheck/test/build + DoD + SSOT 검증\n4) **FAIL 시 자동 루프**\n   - verifier의 FAIL 항목을 implementer에게 전달 → 수정 → 재검증 반복\n\n## 강제 가드레일\n- 커맨드(dev/test/lint/typecheck/build)는 절대 추정하지 말고 `scripts/detect_project_commands.py`로 탐지한다.\n- SSOT 위반(예: option_c.json 우회 SoT 도입) 징후가 있으면 즉시 중단하고 리포트에 기록한다.\n- Preview→Apply 및 History append-only 원칙을 깨는 변경은 \"기능 구현\"이 아니라 \"규칙 위반\"으로 간주한다.\n\n## 빠른 사용\n- Cursor Agent 채팅에서:\n  - `/tr-dashboard-autopilot` 실행\n  - (필요 시) `/tr-dashboard-ssot-guard` 단독 실행\n"},"lastSynced":"2026-03-08T02:09:41.495Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing automated TR dashboard setup and verification capabilities.","zh":"非常适合需要自动化 TR 仪表板设置和验证功能的开发代理。","ja":"開発エージェントが自動化された TR ダッシュボード設定と検証機能を必要とする場合に最適です。","ko":"자동화된 TR 대시보드 설정 및 확인 기능이 필요한 개발 에이전트에게 적합합니다.","es":"Perfecto para agentes de desarrollo que necesitan configuración y verificación automatizadas del panel de TR.","fr":"Parfait pour les agents de développement ayant besoin d''une configuration et d''une vérification automatisées du tableau de bord TR.","de":"Perfekt für Entwicklungssagenten, die eine automatisierte TR-Dashboard-Konfiguration und -Verifizierung benötigen.","pt":"Perfeito para Agentes de Desenvolvimento que necessitam de configuração e verificação automática de dashboard TR.","ru":"Идеально подходит для агентов разработки, которым необходимы автоматизированные возможности настройки и проверки панели управления TR.","ar":"مثالي لعمليات تطوير الوكلاء التي تحتاج إلى إمكانيات تلقائية لتعيين لوحة تحكم TR والتحقق منها."},"recommendation":{"en":"Empowers agents to generate plans and verify implementations using AGENTS.md and option_c.json configurations, streamlining the development process with automated TR dashboard setup and validation reports in Markdown format.","zh":"赋予代理生成计划和验证实施的能力，使用 AGENTS.md 和 option_c.json 配置，通过自动化 TR 仪表板设置和验证报告（以 Markdown 格式），简化开发流程。","ja":"エージェントは、AGENTS.md と option_c.json の構成を使用して計画を生成し、実装を検証し、自動化された TR ダッシュボードの設定と検証レポート（Markdown 形式）を使用して開発プロセスを合理化できます。","ko":"에이전트가 AGENTS.md와 option_c.json 구성으로 계획을 생성하고 구현을 확인할 수 있도록 하여 자동화된 TR 대시보드 설정 및 확인 보고서(Markdown 형식)를 통해 개발 프로세스를 간소화합니다.","es":"Habilita a los agentes a generar planes y verificar implementaciones utilizando configuraciones de AGENTS.md y option_c.json, simplificando el proceso de desarrollo con una configuración automática del panel de TR y informes de validación en formato Markdown.","fr":"Permet aux agents de générer des plans et de vérifier les implémentations en utilisant les configurations AGENTS.md et option_c.json, simplifiant le processus de développement avec une configuration automatisée du tableau de bord TR et des rapports de validation au format Markdown.","de":"Ermöglicht es Agenten, Pläne zu generieren und Implementierungen unter Verwendung von AGENTS.md- und option_c.json-Konfigurationen zu überprüfen, wodurch der Entwicklungsprozess durch eine automatisierte TR-Dashboard-Konfiguration und Validierungsberichte im Markdown-Format gestreamlined wird.","pt":"Habilita os agentes a gerar planos e verificar implementações usando configurações AGENTS.md e option_c.json, agilizando o processo de desenvolvimento com configuração automática de dashboard TR e relatórios de validação no formato Markdown.","ru":"Наделяет агентов возможностью генерировать планы и проверять реализацию с помощью конфигураций AGENTS.md и option_c.json, оптимизируя процесс разработки с автоматизированной настройкой панели управления TR и отчетами о проверке в формате Markdown.","ar":"يمنح الوكلاء القدرة على توليد خطط والتحقق من التنفيذ باستخدام إعدادات AGENTS.md و option_c.json، مما يسهل عملية التطوير مع إعداد لوحة تحكم TR التلقائي وتقارير التحقق بالتنسيق Markdown."},"useCases":{"en":["Automating TR dashboard setup from plan creation to final verification","Generating and verifying implementation reports based on option_c.json configurations","Validating TR dashboard implementations against predefined plans and SSOT settings"],"zh":["从计划创建到最终验证的自动化 TR 仪表板设置","根据 option_c.json 配置生成和验证实施报告","验证 TR 仪表板实施是否符合预定义计划和 SSOT 设置"],"ja":["計画の作成から最終的な検証までの TR ダッシュボード設定の自動化","option_c.json 構成に基づいて実装レポートを生成し検証する","TR ダッシュボードの実装が予定された計画と SSOT 設定に準拠していることを検証する"],"ko":["계획 생성에서 최종 확인까지의 자동화된 TR 대시보드 설정","option_c.json 구성에 따라 구현 보고서를 생성하고 확인하는 것","TR 대시보드 구현이 미리 정의된 계획 및 SSOT 설정과 일치하는지 확인"],"es":["Automatizar la configuración del panel de TR desde la creación del plan hasta la verificación final","Generar y verificar informes de implementación en función de las configuraciones de option_c.json","Validar las implementaciones del panel de TR frente a planes y ajustes de SSOT preestablecidos"],"fr":["Automatiser la configuration du tableau de bord TR depuis la création du plan jusqu''à la vérification finale","Générer et vérifier les rapports d''implémentation en fonction des configurations option_c.json","Valider les implémentations du tableau de bord TR par rapport aux plans et paramètres SSOT prédéfinis"],"de":["Automatisierung der TR-Dashboard-Konfiguration vom Planerstellung bis zur abschließenden Überprüfung","Erzeugen und Überprüfen von Implementierungsberichten auf Grundlage von option_c.json-Konfigurationen","Validierung der TR-Dashboard-Implementierungen gegenüber vorgegebenen Plänen und SSOT-Einstellungen"],"pt":["Automatizar a configuração do dashboard TR desde a criação do plano até a verificação final","Gerar e verificar relatórios de implementação com base em configurações option_c.json","Validar implementações do dashboard TR contra planos e configurações SSOT predefinidos"],"ru":["Автоматизировать настройку панели управления TR от создания плана до окончательной проверки","Генерировать и проверять отчеты о реализации на основе конфигураций option_c.json","Проверять реализацию панели управления TR с предопределенными планами и настройками SSOT"],"ar":["تحويل إعداد لوحة تحكم TR تلقائيًا من إنشاء الخطة إلى التحقق النهائي","توليد وتحقق تقارير التنفيذ استنادًا إلى إعدادات option_c.json","التحقق من تنفيذ لوحة تحكم TR مقابل خطط مسبقة التعريف وإعدادات SSOT"]},"limitations":{"en":["Requires AGENTS.md and option_c.json files for configuration","Limited to generating Markdown reports for plans and verification"],"zh":["需要 AGENTS.md 和 option_c.json 文件进行配置","仅限生成计划和验证的 Markdown 报告"],"ja":["構成に AGENTS.md と option_c.json ファイルが必要","計画と検証の Markdown レポートの生成のみ"],"ko":["구성에 AGENTS.md 및 option_c.json 파일이 필요","계획 및 확인의 Markdown 보고서 생성만"],"es":["Requiere archivos AGENTS.md y option_c.json para la configuración","Limitado a la generación de informes en Markdown para planes y verificación"],"fr":["Nécessite des fichiers AGENTS.md et option_c.json pour la configuration","Limité à la génération de rapports Markdown pour les plans et la vérification"],"de":["Benötigt AGENTS.md- und option_c.json-Dateien für die Konfiguration","Begrenzt auf die Erzeugung von Markdown-Berichten für Pläne und Überprüfung"],"pt":["Requer arquivos AGENTS.md e option_c.json para configuração","Limitado a gerar relatórios Markdown para planos e verificação"],"ru":["Требует файлов AGENTS.md и option_c.json для конфигурации","Ограничен генерацией отчетов Markdown для планов и проверки"],"ar":["يتطلب ملفات AGENTS.md و option_c.json للتحكم","محدود بتوليد تقارير Markdown للخطط والتحقق"]},"version":4},"contentHash":"fbd7193bd5c1b87860b80afb0222bcbae0afc22ba815208e6493293fb8d29b71","qualityScore":23}');
