INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('macho715/tr_dash/tr-dashboard-autopilot', 'tr-dashboard-autopilot', 'macho715', 'tr_dash', 'community', 'tr-dashboard-autopilot macho715 tr_dash community The tr-dashboard-autopilot skill automates TR dashboard setup, benefiting developers by generating plans and verifying implementations. It utilizes AGENTS.md and option_c.json for configuration. TR Dashboard Autopilot 是一个基于 AGENTS.md 的自动化计划和验证报告生成工具，支持 option_c.json 配置 TR ダッシュボード オートパイロットは、AGENTS.md に基づく自動計画と検証レポートの生成ツールです。option_c.json 設定をサポートします TR 대시보드 오토파일럿은 AGENTS.md 기반 자동 계획과 검증 리포트 생성 도구로서 option_c.json 설정을 지원합니다 tr-dashboard-autopilot es una habilidad que automatiza la planificación y verificación de tareas con agente de AI. Utiliza option_c.json para configurar flujos y modos. tr-dashboard-autopilot est une compétence qui automatise la planification et la vérification de tâches avec un outil d''IA. Il utilise option_c.json pour configurer les flux et les modes. tr-dashboard-autopilot ist eine Fähigkeit, die die Planung und Verifizierung von Aufgaben mit einem KI-Agenten automatisiert. Sie verwendet option_c.json, um Flüsse und Modi zu konfigurieren. O TR Dashboard Autopilot é uma ferramenta que automatiza tarefas de planejamento e implementação com base em AGENTS.md e option_c.json. TR Dashboard Autopilot - это инструмент, который автоматизирует задачи планирования и реализации на основе AGENTS.md и option_c.json. تطبيق TR Dashboard Autopilot هو أداة ت自动 عمليات التخطيط والتنفيذ بالاعتماد على AGENTS.md و option_c.json how to use tr-dashboard-autopilot tr-dashboard-autopilot setup guide tr-dashboard-autopilot alternative tr-dashboard-autopilot vs manual setup automating TR dashboard creation AGENTS.md configuration option_c.json tutorial tr-dashboard-autopilot install tr-dashboard-autopilot documentation TR Dashboard Autopilot AI 工具 自动化计划 验证报告 AGENTS.md option_c.json ssot-guard valida Generates TR dashboard plans using /tr-planner Implements tasks using /tr-implementer Validates implementations with ssot-guard or valida Creates verification reports in docs/plan/tr-dashboard-verification-report.md Utilizes option_c.json for SSOT configuration Processes AGENTS.md for task planning tr-dashboard-autopilot is an AI agent skill that automates the creation and verification of TR dashboards, using inputs like AGENTS.md and option_c.json to generate plans and reports.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('naufaldi/lp-corporate/ui-law', 'community', 'naufaldi', 'lp-corporate', 'naufaldi/lp-corporate', 'ui-law', 0, 0, 23, '2026-03-08T01:57:15.483Z', '2026-03-08T02:09:59.550Z', '40758ff7dfd3465836c8ecf0d22bfae6a3cc25d57e445cbdca9ce605a8539fb6', '{"id":"naufaldi/lp-corporate/ui-law","name":"ui-law","description":{"en":"ui-law is a modern, single-page corporate landing page showcasing Nusantara Palm Industries, utilizing AI-assisted frontend development with MiniMax AI for a visually appealing design","zh":"ui-law 是一个现代的单页企业着陆页，展示了 Nusantara Palm Industries 的可持续棕榈油出口业务。该项目演示了使用 MiniMax AI 的 AI 辅助前端开发","ja":"ui-law は、Nusantara Palm Industries の持続可能なパームオイル輸出事業を紹介するモダンなシングルページ企業ランディングページです。このプロジェクトでは、MiniMax AI を使用した AI アシストによるフロントエンド開発を実演します","ko":"ui-law는 Nusantara Palm Industries의 지속 가능한 팜오일 수출 사업을展示하는 최신의 단일 페이지 기업 랜딩 페이지입니다. 이 프로젝트는 MiniMax AI를 사용한 AI 보조 프론트엔드 개발을展示합니다","es":"ui-law es una habilidad de desarrollo frontend asistida por IA que mejora la jerarquía visual y la tipografía en las páginas de aterrizaje corporativas","fr":"ui-law est une compétence de développement frontend assistée par l''IA qui améliore la hiérarchie visuelle et la typographie sur les pages d''accueil d''entreprise","de":"ui-law ist eine Fähigkeit für die Entwicklung von Frontends, die von KI unterstützt wird und die visuelle Hierarchie und Typografie auf Unternehmens-Landingpages verbessert","pt":"ui-law é uma habilidade que demonstra desenvolvimento de frontend assistido por IA usando MiniMax AI para criar páginas de destino corporativas modernas","ru":"ui-law - это навык, который демонстрирует разработку frontend с помощью ИИ с использованием MiniMax AI для создания современных корпоративных страниц","ar":"ui-law هو مهارة يُظهر تطوير واجهة المستخدم الأمامية بمساعدة الذكاء الاصطناعي باستخدام MiniMax AI لإنشاء صفحات هبوط الشركات ال