INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ThallesP/railway-minecraft-template/distinctive-frontend-design', 'distinctive-frontend-design', 'ThallesP', 'railway-minecraft-template', 'community', 'distinctive-frontend-design ThallesP railway-minecraft-template community The distinctive frontend design skill enables developers to create bold and unique UIs, solving real problems for users. It executes production-grade code with a strong aesthetic direction. 独特前端设计是指创建具有强烈美学方向和生产级代码的前端UI，避免通用AI样式 独特なフロントエンド設計は、強い美的方向性と生産性の高いコードを持つフロントエンドUIを作成することを意味し、ジェネリックなAIスタイルを避ける 특이한 프론트엔드 디자인은 강력한 미적 방향과 생산급 코드를 갖춘 프론트엔드 UI를 생성하는 것을 의미하며 일반적인 AI 스타일을 피합니다 Diseño frontend distintivo con un enfoque estético atrevido y código de producción de alta calidad Conception de frontend distinctif avec une direction esthétique audacieuse et du code de production de haute qualité Einzigartiges Frontend-Design mit einer mutigen ästhetischen Richtung und Produktionscode höchster Qualität O design de frontend distintivo é uma abordagem que combina design thinking e código de produção para criar interfaces de usuário únicas. Уникальный дизайн frontend - это подход, который сочетает дизайн-мышление и код производства для создания индивидуальных интерфейсов пользователя. التصميم الأمامي الفريد هو نهج يجمع بين التفكير التصميمي وкод الإنتاج لإنشاء واجهات مستخدم فريدة. how to use distinctive frontend design what is distinctive frontend design distinctive frontend design alternative distinctive frontend design vs material design distinctive frontend design setup guide distinctive frontend design install bold aesthetic direction in UI design production-grade frontend code unique UI design implementation 独特前端设计 AIエージェント 前端开发 UI设计 生产级代码 设计思维 独特的UI设计 高性能的前端开发 避免通用AI样式 Executes production-grade code with a strong aesthetic direction Avoids generic ''AI slop'' visuals and predictable layouts Implements design thinking to solve real problems for users Commits to a bold aesthetic direction, such as minimal or maximalist Answers key design questions, including purpose and tone Produces unique and bold UIs for various use cases distinctive-frontend-design is a skill that helps developers create frontend UIs with a bold aesthetic direction, avoiding generic visuals and predictable layouts.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('shotly/shotly/vue-nuxt-project-standards', 'community', 'shotly', 'shotly', 'shotly/shotly', 'vue-nuxt-project-standards', 0, 0, 23, '2026-03-08T01:57:15.512Z', '2026-03-08T02:10:27.935Z', 'c9d3a4914d0171e1853cad656edd350e88c722440b38a8fdf096a683c0443f60', '{"id":"shotly/shotly/vue-nuxt-project-standards","name":"vue-nuxt-project-standards","description":{"en":"vue-nuxt-project-standards provides expert guidelines for Senior Frontend Developers using Vue 3, Nuxt 3, and TypeScript, ensuring high-quality project development.","zh":"Vue Nuxt 项目开发标准提供了 JavaScript、TypeScript、TailwindCSS 等技术的最佳实践","ja":"Vue Nuxt プロジェクト開発標準は、JavaScript、TypeScript、TailwindCSS などの技術のベストプラクティスを提供する","ko":"Vue Nuxt 프로젝트 개발 표준은 JavaScript, TypeScript, TailwindCSS 등 기술의 최고 사례를 제공한다","es":"Los estándares de proyecto Vue y Nuxt proporcionan una guía para el desarrollo de aplicaciones frontend robustas y escalables. Aprende a utilizar JavaScript, TypeScript, TailwindCSS y más.","fr":"Les normes de projet Vue et Nuxt offrent un guide pour le développement d''applications frontend robustes et évolutives. Apprenez à utiliser JavaScript, TypeScript, TailwindCSS et plus.","de":"Die Projektstandards für Vue und Nuxt bieten eine Anleitung für die Entwicklung robuster und skalierbarer Frontend-Anwendungen. Erfahren Sie, wie Sie JavaScript, TypeScript, TailwindCSS und mehr verwenden können.","pt":"Padrões de projeto Vue Nuxt para melhorar a qualidade do código. Aprenda a configurar projetos com Vue 3, Nuxt 3 e TailwindCSS.","ru":"Стандарты проектирования Vue Nuxt для улучшения качества кода. Узнайте, как настроить проекты с помощью Vue 3, Nuxt 3 и TailwindCSS.","ar":"معايير تصميم مشروع فيو نكست لتحسين جودة الكود. تعلم كيفية ضبط المشاريع باستخدام فيو 3، نكست 3 وتايلويند سي إس إس."},"seo":{"title":{"en":"vue-nuxt-project-standards: Development Setup