INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('shotly/shotly/vue-nuxt-project-standards', 'vue-nuxt-project-standards', 'shotly', 'shotly', 'community', 'vue-nuxt-project-standards shotly shotly community vue-nuxt-project-standards provides expert guidelines for Senior Frontend Developers using Vue 3, Nuxt 3, and TypeScript, ensuring high-quality project development. Vue Nuxt 项目开发标准提供了 JavaScript、TypeScript、TailwindCSS 等技术的最佳实践 Vue Nuxt プロジェクト開発標準は、JavaScript、TypeScript、TailwindCSS などの技術のベストプラクティスを提供する Vue Nuxt 프로젝트 개발 표준은 JavaScript, TypeScript, TailwindCSS 등 기술의 최고 사례를 제공한다 Los estándares de proyecto Vue y Nuxt proporcionan una guía para el desarrollo de aplicaciones frontend robustas y escalables. Aprende a utilizar JavaScript, TypeScript, TailwindCSS y más. Les normes de projet Vue et Nuxt offrent un guide pour le développement d''applications frontend robustes et évolutives. Apprenez à utiliser JavaScript, TypeScript, TailwindCSS et plus. Die Projektstandards für Vue und Nuxt bieten eine Anleitung für die Entwicklung robuster und skalierbarer Frontend-Anwendungen. Erfahren Sie, wie Sie JavaScript, TypeScript, TailwindCSS und mehr verwenden können. Padrões de projeto Vue Nuxt para melhorar a qualidade do código. Aprenda a configurar projetos com Vue 3, Nuxt 3 e TailwindCSS. Стандарты проектирования Vue Nuxt для улучшения качества кода. Узнайте, как настроить проекты с помощью Vue 3, Nuxt 3 и TailwindCSS. معايير تصميم مشروع فيو نكست لتحسين جودة الكود. تعلم كيفية ضبط المشاريع باستخدام فيو 3، نكست 3 وتايلويند سي إس إس. how to use vue-nuxt-project-standards vue-nuxt-project-standards setup guide vue 3 project development standards nuxt 3 best practices typescript in vue-nuxt-project-standards tailwindcss integration with vue-nuxt-project-standards vue-nuxt-project-standards alternative vue-nuxt-project-standards vs vue-cli Vue Nuxt 项目开发标准 JavaScript 开发 TypeScript 开发 TailwindCSS 教程 Vue 3 开发 Nuxt 3 开发 前端开发标准 代码质量保证 Provides step-by-step pseudocode planning for complex project builds Ensures accurate and factual code implementation with TypeScript Utilizes TailwindCSS for efficient CSS styling and customization Follows expert guidelines for Vue 3 and Nuxt 3 project development Emphasizes thoughtful and nuanced approach to frontend development Supports HTML and CSS for comprehensive project structuring vue-nuxt-project-standards is a set of development standards for building robust Vue and Nuxt projects with JavaScript, TypeScript, and TailwindCSS.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('pesitwizard/pesitwizard/pesit-expert', 'community', 'pesitwizard', 'pesitwizard', 'pesitwizard/pesitwizard', 'pesit-expert', 0, 0, 23, '2026-03-08T01:57:15.539Z', '2026-03-08T02:11:10.736Z', 'cff109e8157ee2fef753adc68c7ba36ac0e79add88c651691d53a43fdfeb04f6', '{"id":"pesitwizard/pesitwizard/pesit-expert","name":"pesit-expert","description":{"en":"The pesit-expert skill streamlines PeSIT specific problem solving for developers, covering steps from checking documentation to creating releases. It benefits developers working with PeSIT modules.","zh":"PeSIT 专家解决方案提供了一套自动化的问题解决流程，包括编写单元测试和更新依赖项","ja":"PeSIT エキスパート AIエージェントは、単体テストの作成や依存関係の更新など、問題解決の自動化されたワークフローを提供します","ko":"PeSIT 전문가 가이드는 자동화된 문제 해결을 위한 단위 테스트 작성과 종속성 업데이트를 제공합니다","es":"PeSIT Expert es una herramienta para resolver problemas de manera efectiva con unit tests y GitHub Actions. Ofrece una guía paso a paso para la resolución de problemas.","fr":"PeSIT Expert est un outil pour résoudre des problèmes de manière efficace avec des tests unitaires et GitHub Actions. Il propose un guide étape par étape pour la résolution de problèmes.","de":"PeSIT-Experten ist ein Tool zur effektiven Lösung von Problemen mit Unit-Tests und GitHub-Actions. Es bietet einen Schritt-für-Schritt-Leitfaden zur Problemlösung.","pt":"O PeSIT Expert é uma ferramenta avançada para solução de problemas, que inclui testes unitários e atualizações de dependências","ru":"PeSIT Expert - это продвинутый инструмент для решения сложных проблем, включающий написание юнит-тестов и обновление зависимостей","ar":"PeSIT Expert هو أداة متقدمة لحل المشكلات، وتشمل كتابة الاختبارات الوحدوية و تحديث الإعتماديات"},"seo":{"title":{"en":"pesit-expert: PeSIT Problem Solving Setup Guide | AI Agen...","zh":"PeSIT 专家解决方案 Setup Guide","ja":"PeSIT エキスパート AIエージェントのベストプラクティス","ko":"PeSIT 전문가 가이드: 자동화된 문제 해결","