INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('pesitwizard/pesitwizard/pesit-expert', 'pesit-expert', 'pesitwizard', 'pesitwizard', 'community', 'pesit-expert pesitwizard pesitwizard community The pesit-expert skill streamlines PeSIT specific problem solving for developers, covering steps from checking documentation to creating releases. It benefits developers working with PeSIT modules. PeSIT 专家解决方案提供了一套自动化的问题解决流程，包括编写单元测试和更新依赖项 PeSIT エキスパート AIエージェントは、単体テストの作成や依存関係の更新など、問題解決の自動化されたワークフローを提供します PeSIT 전문가 가이드는 자동화된 문제 해결을 위한 단위 테스트 작성과 종속성 업데이트를 제공합니다 PeSIT Expert es una herramienta para resolver problemas de manera efectiva con unit tests y GitHub Actions. Ofrece una guía paso a paso para la resolución de problemas. PeSIT Expert est un outil pour résoudre des problèmes de manière efficace avec des tests unitaires et GitHub Actions. Il propose un guide étape par étape pour la résolution de problèmes. PeSIT-Experten ist ein Tool zur effektiven Lösung von Problemen mit Unit-Tests und GitHub-Actions. Es bietet einen Schritt-für-Schritt-Leitfaden zur Problemlösung. O PeSIT Expert é uma ferramenta avançada para solução de problemas, que inclui testes unitários e atualizações de dependências PeSIT Expert - это продвинутый инструмент для решения сложных проблем, включающий написание юнит-тестов и обновление зависимостей PeSIT Expert هو أداة متقدمة لحل المشكلات، وتشمل كتابة الاختبارات الوحدوية و تحديث الإعتماديات how to use pesit-expert pesit-expert setup guide what is pesit-expert pesit-expert alternative pesit-expert vs GitHub Actions pesit-expert install pesit-expert for PeSIT modules PeSIT problem solving with pesit-expert pesit-expert for AI agents PeSIT 专家解决方案 AI 工具 自动化问题解决 单元测试 changelog 更新 GitHub Actions pom 版本更新 依赖项更新 问题解决流程 Writes unit tests to cover PeSIT issues and their resolutions Updates changelog and pom version of impacted modules Creates commits once issues are fixed and tests pass Checks all GitHub Actions are up to date and pass Pushes updates to GitHub and creates releases Ensures compilation of all impacted modules pesit-expert is a specialized AI agent skill designed for PeSIT problem solving, facilitating efficient issue resolution through a structured approach.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('quileab/sae/pest-testing', 'community', 'quileab', 'sae', 'quileab/sae', 'pest-testing', 0, 0, 23, '2026-03-08T01:57:15.565Z', '2026-03-08T02:11:39.386Z', '05bb6cfd7acdeeaa3c2b2317ed71bb6fe329eafd204a072cfced0157e6ebd473', '{"id":"quileab/sae/pest-testing","name":"pest-testing","description":{"en":"Pest-Testing is a skill that enables AI agents to automate test generation for PHP applications. It benefits developers by simplifying the testing process.","zh":"Pest 测试是一种用于创建和管理测试的工具，支持创建测试、测试组织和调试","ja":"Pest テスティングは、テストの作成と管理を行うためのツールです。テストの作成、テストの組織、デバッグをサポートします","ko":"Pest 테스팅은 테스트를 생성하고 관리하는 도구로, 테스트 생성, 테스트 조직, 디버깅을 지원합니다","es":"Pest Testing es una herramienta para crear y depurar pruebas unitarias y de características con PHP y Artisan. Utilice `php artisan make:test --pest {name}` para crear pruebas","fr":"Pest Testing est un outil pour créer et déboguer des tests unitaires et de fonctionnalités avec PHP et Artisan. Utilisez `php artisan make:test --pest {name}` pour créer des tests","de":"Pest-Testing ist ein Tool zum Erstellen und Debuggen von Einheitstests und Funktionsprüfungen mit PHP und Artisan. Verwenden Sie `php artisan make:test --pest {name}`, um Tests zu erstellen","pt":"O pest-testing é uma habilidade que ajuda a melhorar a eficiência dos testes unitários e de recurso com o framework Pest 3","ru":"Pest-testing - это навык, который помогает повысить эффективность юнит-тестов и функциональных тестов с помощью фреймворка Pest 3","ar":"اختبار الحشرات هو مهارة تساعد على تحسين كفاءة الاختبارات الوحدوية ووظائف باستخدام إطار العمل Pest 3"},"seo":{"title":{"en":"Pest-Testing: Automated Test Generation Setup Guide | AI ...","zh":"Pest 测试设置指南","ja":"Pest テスティングベストプラクティス","ko":"Pest 테스팅 가이드","es":"Guía de configuración de Pest Testing para desarrolladores","fr":"Guide de mise en place de Pest Testing pour les développeurs","de":"Einrichtungsleitfaden für Pest-Testing-Tools","pt":"Guia de Configuração do Pest-Testing para Desenvolvedores","ru":"Настройка Pest-Testing: Руководство для Разработчиков ИИ ...","ar":"دليل إعداد اختبار الحشرات للbrateurs باستخدام أدوات الإي ..."},"description":{"en":"Discover how to streamline your testing process with Pest-Testing. Learn how to create, modify, and debug tests efficiently. Get started now!","zh":"了解 Pest 测试的基本用法和文档，包括创建测试、测试组织和调试","ja":"Pest テスティングの基本的な使い方とドキュメントを学ぶ、テストの作成、テストの組織、デバッグ","ko":"Pest 테스팅의 기본 사용법과 문서를 알아보세요. 테스트 생성, 테스트 조직, 디버깅 등","es":"Aprende a utilizar Pest Testing para crear y depurar pruebas unitarias y de características con PHP y Artisan","fr":"Découvrez comment utiliser Pest Testing pour créer et déboguer des tests unitaires et de fonctionnalités avec PHP et Artisan","de":"Erfahren Sie, wie Sie Pest-Testing-Tools verwenden, um Einheitstests und Funktionsprüfungen mit PHP und Artisan zu erstellen und zu debuggen","pt":"Aprenda a configurar o pest-testing para melhorar a eficiência dos testes unitários e de recurso com o framework Pest 3","ru":"Узнайте, как настроить pest-testing для повышения эффективности юнит-тестов и функциональных тестов с помощью фреймворка Pest 3 и ИИ Агентов","ar":"تعلم كيفية إعداد اختبار الحشرات لتحسين كفاءة الاختبارات الوحدوية ووظائف باستخدام إطار العمل Pest 3 وأدوات الإي الإلكترونية"},"definition":{"en":"Pest-testing is a testing framework that allows developers to write and organize tests using the Pest 3 pattern.","zh":"Pest 测试是 PHP 项目中用于创建和管理测试的工具","ja":"Pest テスティングは、PHP プロジェクトでテストを作成し管理するためのツールです","ko":"Pest 테스팅은 PHP 프로젝트에서 테스트를 생성하고 관리하는 도구입니다","es":"Pest Testing es una herramienta de prueba que permite a los desarrolladores crear y depurar pruebas unitarias y de características","fr":"Pest Testing est un outil de test qui permet aux développeurs de créer et de déboguer des tests unitaires et de fonctionnalités","de":"Pest-Testing ist ein Testtool, mit dem Entwickler Einheitstests und Funktionsprüfungen erstellen und debuggen können","pt":"Pest-testing é uma técnica de teste que utiliza o framework Pest 3 para criar e organizar testes unitários e de recurso","ru":"Pest-testing - это техника тестирования, которая использует фреймворк Pest 3 для создания и организации юнит-тестов и функциональных тестов","ar":"اختبار الحشرات هو تقنية اختبار تستخدم إطار العمل Pest 3 لإنشاء وتنظيم الاختبارات الوحدوية ووظائف"},"features":{"en":["Creates tests using the `php artisan make:test --pest {name}` command","Organizes tests in the `tests/Feature` directory","Supports debugging test failures and modifying existing tests","Enables writing architecture tests using Pest 3 patterns","Integrates with `search-docs` for detailed documentation and patterns"],"zh":["使用 Pest 创建测试","支持测试组织和管理","调试测试失败","使用 PHP artisan 命令创建测试","支持测试数据和模拟"],"ja":["Pest を使用してテストを作成","テストの組織と管理をサポート","テストのデバッグ","PHP artisan コマンドを使用してテストを作成","テストデータとモックのサポート"],"ko":["Pest를 사용하여 테스트 생성","테스트 조직 및 관리 지원","테스트 디버깅","PHP artisan 명령어를 사용하여 테스트 생성","테스트 데이터 및 모의 지원"],"es":["Creación de pruebas unitarias y de características con PHP y Artisan","Depuración de pruebas con `php artisan make:test --pest {name}`","Organización de pruebas en `tests/Feature`","Compatibilidad con datasets, mocking y organización de pruebas","Soporte para pruebas de arquitectura"],"fr":["Création de tests unitaires et de fonctionnalités avec PHP et Artisan","Débogage de tests avec `php artisan make:test --pest {name}`","Organisation de tests dans `tests/Feature`","Compatibilité avec les datasets, le mocking et l''organisation de tests","Support pour les tests d''architecture"],"de":["Erstellung von Einheitstests und Funktionsprüfungen mit PHP und Artisan","Debuggen von Tests mit `php artisan make:test --pest {name}`","Organisation von Tests in `tests/Feature`","Kompatibilität mit Datenbeständen, Mocking und Testorganisation","Unterstützung für Architekturtests"],"pt":["Criação de testes unitários e de recurso com o comando php artisan make:test --pest {name}","Organização de testes em pastas e subpastas","Utilização do framework Pest 3 para criar testes mais eficientes","Suporte à depuração de falhas de teste","Integração com datasets e mocking"],"ru":["Создание юнит-тестов и функциональных тестов с помощью команды php artisan make:test --pest {name}","Организация тестов в папках и подпапках","Использование фреймворка Pest 3 для создания более эффективных тестов","Поддержка отладки тестовых сбоев","Интеграция с datasets и mocking"],"ar":["إنشاء اختبارات وحدوية ووظائف باستخدام الأمر php artisan make:test --pest {name}","تنظيم الاختبارات في المجلدات والفرعي","استخدام إطار العمل Pest 3 لإنشاء اختبارات أكثر كفاءة","دعم调试 فشل الاختبار","التكامل مع datasets وmocking"]},"keywords":{"en":["how to use pest-testing","pest-testing setup guide","pest-testing vs phpunit","pest-testing install","what is pest-testing","pest-testing tutorial","pest-testing alternative","pest-testing documentation"],"zh":["Pest 测试","PHP 测试工具","Pest 测试设置","Pest 测试文档","PHP artisan 测试","Pest 测试调试","Pest 测试组织","Pest 测试数据"],"ja":["Pest テスティング","PHP テスティングツール","Pest テスティング設定","Pest テスティングドキュメント","PHP artisan テスト","Pest テスティングデバッグ","Pest テスティング組織","Pest テスティングデータ"],"ko":["Pest 테스팅","PHP 테스팅 도구","Pest 테스팅 설정","Pest 테스팅 문서","PHP artisan 테스트","Pest 테스팅 디버깅","Pest 테스팅 조직","Pest 테스팅 데이터"],"es":["Pest Testing","pruebas unitarias","pruebas de características","PHP","Artisan","depuración de pruebas","organización de pruebas","datasets","mocking","pruebas de arquitectura"],"fr":["Pest Testing","tests unitaires","tests de fonctionnalités","PHP","Artisan","débogage de tests","organisation de tests","datasets","mocking","tests d''architecture"],"de":["Pest-Testing","Einheitstests","Funktionsprüfungen","PHP","Artisan","Debuggen von Tests","Testorganisation","Datenbestände","Mocking","Architekturtests"],"pt":["pest-testing","teste unitário","teste de recurso","framework Pest 3","php artisan","desenvolvimento de software","testes automatizados"],"ru":["pest-testing","юнит-тест","функциональный тест","фреймворк Pest 3","php artisan","разработка программного обеспечения","автоматизированное тестирование","ИИ Агенты"],"ar":["اختبار الحشرات","اختبار وحدوي","اختبار وظيفي","إطار العمل Pest 3","php artisan","تطوير البرمجيات","اختبارات آلية","أدوات الإي الإلكترونية"]}},"owner":"quileab","repo":"sae","repoPath":"quileab/sae","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.565Z","topics":[],"category":"community","skillMd":{"name":"pest-testing","description":">-","bodyPreview":"# Pest Testing 3\n\n## When to Apply\n\nActivate this skill when:\n- Creating new tests (unit or feature)\n- Modifying existing tests\n- Debugging test failures\n- Working with datasets, mocking, or test organization\n- Writing architecture tests\n\n## Documentation\n\nUse `search-docs` for detailed Pest 3 patterns and documentation.\n\n## Basic Usage\n\n### Creating Tests\n\nAll tests must be written using Pest. Use `php artisan make:test --pest {name}`.\n\n### Test Organization\n\n- Tests live in the `tests/Feature`","body":"# Pest Testing 3\n\n## When to Apply\n\nActivate this skill when:\n- Creating new tests (unit or feature)\n- Modifying existing tests\n- Debugging test failures\n- Working with datasets, mocking, or test organization\n- Writing architecture tests\n\n## Documentation\n\nUse `search-docs` for detailed Pest 3 patterns and documentation.\n\n## Basic Usage\n\n### Creating Tests\n\nAll tests must be written using Pest. Use `php artisan make:test --pest {name}`.\n\n### Test Organization\n\n- Tests live in the `tests/Feature` and `tests/Unit` directories.\n- Do NOT remove tests without approval - these are core application code.\n- Test happy paths, failure paths, and edge cases.\n\n### Basic Test Structure\n\n<code-snippet name=\"Basic Pest Test Example\" lang=\"php\">\n\nit(''is true'', function () {\n    expect(true)->toBeTrue();\n});\n\n</code-snippet>\n\n### Running Tests\n\n- Run minimal tests with filter before finalizing: `php artisan test --compact --filter=testName`.\n- Run all tests: `php artisan test --compact`.\n- Run file: `php artisan test --compact tests/Feature/ExampleTest.php`.\n\n## Assertions\n\nUse specific assertions (`assertSuccessful()`, `assertNotFound()`) instead of `assertStatus()`:\n\n<code-snippet name=\"Pest Response Assertion\" lang=\"php\">\n\nit(''returns all'', function () {\n    $this->postJson(''/api/docs'', [])->assertSuccessful();\n});\n\n</code-snippet>\n\n| Use | Instead of |\n|-----|------------|\n| `assertSuccessful()` | `assertStatus(200)` |\n| `assertNotFound()` | `assertStatus(404)` |\n| `assertForbidden()` | `assertStatus(403)` |\n\n## Mocking\n\nImport mock function before use: `use function Pest\\Laravel\\mock;`\n\n## Datasets\n\nUse datasets for repetitive tests (validation rules, etc.):\n\n<code-snippet name=\"Pest Dataset Example\" lang=\"php\">\n\nit(''has emails'', function (string $email) {\n    expect($email)->not->toBeEmpty();\n})->with([\n    ''james'' => ''james@laravel.com'',\n    ''taylor'' => ''taylor@laravel.com'',\n]);\n\n</code-snippet>\n\n## Pest 3 Features\n\n### Architecture Testing\n\nPest 3 includes architecture testing to enforce code conventions:\n\n<code-snippet name=\"Architecture Test Example\" lang=\"php\">\n\narch(''controllers'')\n    ->expect(''App\\Http\\Controllers'')\n    ->toExtendNothing()\n    ->toHaveSuffix(''Controller'');\n\narch(''models'')\n    ->expect(''App\\Models'')\n    ->toExtend(''Illuminate\\Database\\Eloquent\\Model'');\n\narch(''no debugging'')\n    ->expect([''dd'', ''dump'', ''ray''])\n    ->not->toBeUsed();\n\n</code-snippet>\n\n### Type Coverage\n\nPest 3 provides improved type coverage analysis. Run with `--type-coverage` flag.\n\n## Common Pitfalls\n\n- Not importing `use function Pest\\Laravel\\mock;` before using mock\n- Using `assertStatus(200)` instead of `assertSuccessful()`\n- Forgetting datasets for repetitive validation tests\n- Deleting tests without approval"},"lastSynced":"2026-03-08T02:11:39.386Z","agentAnalysis":{"suitability":{"en":"Ideal for PHP-focused AI Agents seeking to streamline test generation and automation for PHP applications","zh":"适合专注于PHP的AI代理，旨在简化PHP应用程序的测试生成和自动化","ja":"PHPに焦点を当てたAIエージェントに適しており、PHPアプリケーションのテスト生成と自動化を簡素化する","ko":"PHP에 중점을 둔 AI 에이전트에게 적합하며 PHP 애플리케이션의 테스트 생성 및 자동화를 간소화","es":"Ideal para agentes de inteligencia artificial centrados en PHP que buscan optimizar la generación y automatización de pruebas para aplicaciones PHP","fr":"Idéal pour les agents d''intelligence artificielle axés sur PHP qui cherchent à rationaliser la génération et l''automatisation de tests pour les applications PHP","de":"Ideal für PHP-fokussierte KI-Agents, die die Testgenerierung und -automatisierung für PHP-Anwendungen optimieren möchten","pt":"Ideal para Agentes de IA focados em PHP que buscam simplificar a geração de testes e automação para aplicações PHP","ru":"Идеально для агентов ИИ, ориентированных на PHP, которые стремятся оптимизировать генерацию тестов и автоматизацию для приложений PHP","ar":"مثالي للوكلاء الذكيين ذوي التركيز على PHP الذين يسعون لتبسيط إنشاء الاختبارات وتوضيح تطبيق PHP"},"recommendation":{"en":"Empowers agents to automate test generation for PHP applications using Pest, simplifying the testing process with features like test organization and debugging of test failures, utilizing PHP artisan commands and Pest 3 patterns","zh":"赋予代理使用Pest自动化PHP应用程序的测试生成，简化测试过程，具有测试组织和调试测试失败等功能，利用PHP artisan命令和Pest 3模式","ja":"Pestを使用してPHPアプリケーションのテスト生成を自動化するエージェントを可能にし、テストの整理やテスト失敗のデバッグなどの機能によりテストプロセスを簡素化し、PHP artisanコマンドやPest 3パターンを利用","ko":"Pest를 사용하여 PHP 애플리케이션의 테스트 생성을 자동화하는 에이전트를 가능하게 하며 테스트 프로세스를 단순화하기 위해 테스트 조직 및 테스트 실패 디버깅 등의 기능을 제공하며 PHP artisan 명령어 및 Pest 3 패턴을 활용","es":"Habilita a los agentes a automatizar la generación de pruebas para aplicaciones PHP utilizando Pest, simplificando el proceso de prueba con características como la organización de pruebas y la depuración de fallos de prueba, utilizando comandos de PHP artisan y patrones de Pest 3","fr":"Permet aux agents d''automatiser la génération de tests pour les applications PHP en utilisant Pest, en simplifiant le processus de test avec des fonctionnalités telles que l''organisation des tests et le débogage des échecs de test, en utilisant des commandes PHP artisan et des modèles Pest 3","de":"Ermächtigt Agents, die Testgenerierung für PHP-Anwendungen mithilfe von Pest zu automatisieren, wodurch der Testprozess durch Funktionen wie Testorganisation und Fehlersuche bei Testfehlern vereinfacht wird, unter Verwendung von PHP-Artisan-Befehlen und Pest-3-Mustern","pt":"Habilita os agentes a automatizar a geração de testes para aplicações PHP usando Pest, simplificando o processo de teste com recursos como organização de testes e depuração de falhas de teste, utilizando comandos PHP artisan e padrões do Pest 3","ru":"Наделяет агентов возможностью автоматизировать генерацию тестов для приложений PHP с помощью Pest, упрощая процесс тестирования с помощью функций, таких как организация тестов и отладка неудач тестов, используя команды PHP artisan и шаблоны Pest 3","ar":"تمكين الوكلاء من توفير автоматиة لإنشاء الاختبارات الخاصة بتطبيقات PHP باستخدام Pest، وتسهيل عملية الاختبار باستخدام ميزات مثل تنظيم الاختبارات وتشخيص عيوب الاختبارات، باستخدام أوامر PHP artisan ونماذج Pest 3"},"useCases":{"en":["Automating test creation for new PHP features","Debugging test failures in existing PHP applications","Organizing and maintaining tests in the tests/Feature directory","Generating architecture tests for PHP projects"],"zh":["为新PHP功能自动创建测试","调试现有PHP应用程序中的测试失败","组织和维护tests/Feature目录中的测试","为PHP项目生成架构测试"],"ja":["新しいPHP機能のテスト自動生成","既存のPHPアプリケーションのテスト失敗のデバッグ","tests/Featureディレクトリのテストの整理とメンテナンス","PHPプロジェクトのアーキテクチャテストの生成"],"ko":["새로운 PHP 기능에 대한 테스트 자동 생성","既存 PHP 애플리케이션의 테스트 실패 디버깅","tests/Feature 디렉토리 내 테스트 조직 및 유지 보수","PHP 프로젝트를 위한 아키텍처 테스트 생성"],"es":["Automatización de la creación de pruebas para nuevas características PHP","Depuración de fallos de prueba en aplicaciones PHP existentes","Organización y mantenimiento de pruebas en el directorio tests/Feature","Generación de pruebas de arquitectura para proyectos PHP"],"fr":["Automatisation de la création de tests pour les nouvelles fonctionnalités PHP","Débogage des échecs de test dans les applications PHP existantes","Organisation et maintenance des tests dans le répertoire tests/Feature","Génération de tests d''architecture pour les projets PHP"],"de":["Automatisierung der Testerstellung für neue PHP-Funktionen","Fehlersuche bei Testfehlern in bestehenden PHP-Anwendungen","Organisation und Wartung von Tests im Verzeichnis tests/Feature","Generierung von Architekturtests für PHP-Projekte"],"pt":["Automatizar a criação de testes para novos recursos PHP","Depurar falhas de teste em aplicações PHP existentes","Organizar e manter testes no diretório tests/Feature","Gerar testes de arquitetura para projetos PHP"],"ru":["Автоматизировать создание тестов для новых функций PHP","Отладить неудачи тестов в существующих приложениях PHP","Организовать и поддерживать тесты в директории tests/Feature","Генерировать тесты архитектуры для проектов PHP"],"ar":["تحويل إنشاء الاختبارات إلى автоматиة لخصائص PHP الجديدة","تشخيص عيوب الاختبارات في تطبيقات PHP الحالية","تنظيم الاختبارات وضمان استمراريتها في دليل tests/Feature","توليد اختبارات هيكلية لمشاريع PHP"]},"limitations":{"en":["Requires PHP and Pest 3 setup","Limited to PHP applications","Needs access to the terminal for running PHP artisan commands"],"zh":["需要PHP和Pest 3设置","仅限PHP应用程序","需要访问终端以运行PHP artisan命令"],"ja":["PHPとPest 3の設定が必要","PHPアプリケーションに限定","PHP artisanコマンドを実行するためにターミナルへのアクセスが必要"],"ko":["PHP 및 Pest 3 설정이 필요","PHP 애플리케이션에만 국한","PHP artisan 명령어를 실행하기 위해 터미널에 접근할 수 있어야 함"],"es":["Requiere configuración de PHP y Pest 3","Limitado a aplicaciones PHP","Requiere acceso a la terminal para ejecutar comandos de PHP artisan"],"fr":["Nécessite une configuration PHP et Pest 3","Limité aux applications PHP","Nécessite un accès à la terminal pour exécuter des commandes PHP artisan"],"de":["Benötigt PHP- und Pest-3-Setup","Begrenzt auf PHP-Anwendungen","Benötigt Zugriff auf die Konsole zum Ausführen von PHP-Artisan-Befehlen"],"pt":["Requer configuração PHP e Pest 3","Limitado a aplicações PHP","Necessita acesso ao terminal para executar comandos PHP artisan"],"ru":["Требует настройки PHP и Pest 3","Ограничен приложениями PHP","Требует доступа к терминалу для запуска команд PHP artisan"],"ar":["يتطلب إعداد PHP و Pest 3","محدود لتطبيقات PHP","يحتاج إلى الوصول إلى الطرفية لتشغيل أوامر PHP artisan"]},"version":4},"contentHash":"05bb6cfd7acdeeaa3c2b2317ed71bb6fe329eafd204a072cfced0157e6ebd473","qualityScore":23}');
