INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('quileab/sae/pest-testing', 'pest-testing', 'quileab', 'sae', 'community', 'pest-testing quileab sae community Pest-Testing is a skill that enables AI agents to automate test generation for PHP applications. It benefits developers by simplifying the testing process. Pest 测试是一种用于创建和管理测试的工具，支持创建测试、测试组织和调试 Pest テスティングは、テストの作成と管理を行うためのツールです。テストの作成、テストの組織、デバッグをサポートします Pest 테스팅은 테스트를 생성하고 관리하는 도구로, 테스트 생성, 테스트 조직, 디버깅을 지원합니다 Pest Testing es una herramienta para crear y depurar pruebas unitarias y de características con PHP y Artisan. Utilice `php artisan make:test --pest {name}` para crear pruebas Pest Testing est un outil pour créer et déboguer des tests unitaires et de fonctionnalités avec PHP et Artisan. Utilisez `php artisan make:test --pest {name}` pour créer des tests Pest-Testing ist ein Tool zum Erstellen und Debuggen von Einheitstests und Funktionsprüfungen mit PHP und Artisan. Verwenden Sie `php artisan make:test --pest {name}`, um Tests zu erstellen O pest-testing é uma habilidade que ajuda a melhorar a eficiência dos testes unitários e de recurso com o framework Pest 3 Pest-testing - это навык, который помогает повысить эффективность юнит-тестов и функциональных тестов с помощью фреймворка Pest 3 اختبار الحشرات هو مهارة تساعد على تحسين كفاءة الاختبارات الوحدوية ووظائف باستخدام إطار العمل Pest 3 how to use pest-testing pest-testing setup guide pest-testing vs phpunit pest-testing install what is pest-testing pest-testing tutorial pest-testing alternative pest-testing documentation Pest 测试 PHP 测试工具 Pest 测试设置 Pest 测试文档 PHP artisan 测试 Pest 测试调试 Pest 测试组织 Pest 测试数据 Creates tests using the `php artisan make:test --pest {name}` command Organizes tests in the `tests/Feature` directory Supports debugging test failures and modifying existing tests Enables writing architecture tests using Pest 3 patterns Integrates with `search-docs` for detailed documentation and patterns Pest-testing is a testing framework that allows developers to write and organize tests using the Pest 3 pattern.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('allofmeng/streamline_project/clean-code-reviewer', 'community', 'allofmeng', 'streamline_project', 'allofmeng/streamline_project', 'clean-code-reviewer', 0, 0, 23, '2026-03-08T01:57:15.574Z', '2026-03-08T02:11:46.824Z', 'd33b4a33b2eb60593a6367dc20d49920e467edb854a8c93cc2738e0698d03507', '{"id":"allofmeng/streamline_project/clean-code-reviewer","name":"clean-code-reviewer","description":{"en":"The clean-code-reviewer skill analyzes code for quality, identifies duplicate functionality, and recommends tests. It benefits developers by ensuring maintainability and efficiency in their codebase.","zh":"Clean Code Reviewer是一种专注于代码清理和消除冗余的AI工具，帮助开发者提高代码质量和维护效率","ja":"Clean Code Reviewerは、コードのクリーン化と冗長性の除去に特化したAIツールで、開発者のコード品質とメンテナンス効率を向上させる","ko":"Clean Code Reviewer는 코드 클린니스와 중복 제거에 특화된 AI 도구로, 개발자의 코드 품질과 유지 보수 효율성을 향상","es":"Clean-code-reviewer es una herramienta de revisión de código especializada en garantizar la limpieza y eficiencia del código, identificando funcionalidades duplicadas y sugiriendo refactorizaciones","fr":"Clean-code-reviewer est un outil d''examen de code spécialisé dans l''assurance de la propreté et de l''efficacité du code, en identifiant les fonctionnalités dupliquées et en suggérant des refactorisations","de":"Clean-code-reviewer ist ein Code-Review-Tool, das auf die Gewährleistung von Sauberkeit und Effizienz des Codes spezialisiert ist, indem es duplizierte Funktionalitäten identifiziert und Refactorings vorschlägt","pt":"O clean-code-reviewer é uma ferramenta especializada em garantir a limpeza e eficiência do código. Ele analisa o código recentemente escrito para identificar duplicatas e sugerir refatoração.","ru":"ИИ Агент clean-code-reviewer - это специализированный инструмент, обеспечивающий чистоту и эффективность кода. Он анализирует недавно написанный код для выявления дубликатов и предложения рефакторинга.","ar":"clean-code-reviewer هو أداة متخصصة في ضمان نظافة الكود وفاعليته. يقوم بتحليل الكود المكتوب حديثًا لتحديد التكرارات واقتراح إعادة الهيكلة."},"seo":{"title":{"en":"clean-code-reviewer: Code Quality Assurance for AI Agents...","zh":"Clean Code Reviewer Setup Guide - 优化代码质量","ja":"Clean Code Reviewer ベストプラクティス - コード品質の向上","ko":"Clean Code Reviewer 설정 가이드 - 코드 클린니스 향상","es":"Guía de configuración de clean-code-reviewer para desarro...","fr":"Configurer clean-code-reviewer : Meilleures pratiques pou...","de":"Clean-Code-Reviewer-Setup-Leitfaden für Entwickler","pt":"Guia de Configuração do clean-code-reviewer: Melhores Prá...","ru":"Настройка ИИ Агента clean-code-reviewer: Руководство по Л...","ar":"دليل إعداد clean-code-reviewer: أفضل الممارسات لتحسين الكود"},"description":{"en":"Discover how clean-code-reviewer ensures maintainable code, eliminates redundancy, and suggests refactoring opportunities. Get started with code review best ...","zh":"了解Clean Code Reviewer AIエージェント的功能和优点，实现代码质量的提高和维护效率的提升","ja":"Clean Code Reviewer AIエージェントの機能とメリットを紹介。コード品質の向上とメンテナンス効率の改善を実現","ko":"Clean Code Reviewer AI 도구의 기능과 장점을 알아보세요. 코드 클린니스 향상과 유지 보수 효율성 개선","es":"Aprende a utilizar clean-code-reviewer para mejorar la calidad y eficiencia de tu código con nuestra guía de configuración y mejores prácticas","fr":"Améliorez la qualité et l''efficacité de votre code avec clean-code-reviewer grâce à notre guide de configuration et aux meilleures pratiques","de":"Verbessern Sie die Qualität und Effizienz Ihres Codes mit clean-code-reviewer dank unseres Konfigurationsleitfadens und Best Practices","pt":"Aprenda a configurar o clean-code-reviewer para melhorar a qualidade do código e eliminar redundâncias. Descubra as melhores práticas para desenvolvedores.","ru":"Узнайте, как настроить ИИ Агент clean-code-reviewer для улучшения качества кода и исключения дубликатов. Изучите лучшие практики для разработчиков.","ar":"تعلم كيفية إعداد clean-code-reviewer لتحسين جودة الكود وتقليل التكرار. استكشف أفضل الممارسات للطورين."},"definition":{"en":"clean-code-reviewer is a specialized skill that focuses on ensuring code cleanliness, eliminating redundancy, and suggesting refactoring opportunities for improved code quality and maintainability.","zh":"Clean Code Reviewer是一种AI工具，用于分析和优化代码质量，确保代码的清理和可维护性","ja":"Clean Code Reviewerは、コードの品質を分析し、最適化するAIツールで、コードのクリーン化とメンテナンス性を確保する","ko":"Clean Code Reviewer는 코드 품질을 분석하고 최적화하는 AI 도구로, 코드 클린니스와 유지 보수성을 보장","es":"Clean-code-reviewer es una herramienta de revisión de código que se enfoca en la limpieza y eficiencia del código","fr":"Clean-code-reviewer est un outil d''examen de code qui se concentre sur la propreté et l''efficacité du code","de":"Clean-code-reviewer ist ein Code-Review-Tool, das sich auf die Sauberkeit und Effizienz des Codes konzentriert","pt":"O que é clean-code-reviewer? É uma ferramenta de revisão de código que garante a qualidade e eficiência do código.","ru":"Что такое ИИ Агент clean-code-reviewer? Это инструмент для проверки кода, обеспечивающий качество и эффективность кода.","ar":"ما هو clean-code-reviewer? هو أداة لمراجعة الكود التي تضمن جودة الكود وفاعليته."},"features":{"en":["Analyzes recently written code for quality and maintainability","Identifies duplicate functionality and suggests refactoring opportunities","Recommends appropriate tests based on the existing module ecosystem","Ensures code efficiency and eliminates redundancy","Provides thorough yet constructive code review feedback","Utilizes knowledge of existing modules for informed code review"],"zh":["代码质量分析","冗余代码消除","重构建议","测试建议","模块生态系统集成"],"ja":["コード品質分析","冗長コード除去","リファクタリング提案","テスト提案","モジュールエコシステム統合"],"ko":["코드 품질 분석","중복 코드 제거","리팩토링 제안","테스트 제안","모듈 생태계 통합"],"es":["Análisis de código para calidad y eficiencia","Identificación de funcionalidades duplicadas","Sugerencias de refactorización","Recomendaciones de pruebas basadas en el ecosistema de módulos existente","Enfoque en mantenibilidad y eficiencia","Acceso a información sobre módulos existentes"],"fr":["Analyse de code pour la qualité et l''efficacité","Identification de fonctionnalités dupliquées","Suggestions de refactorisation","Recommandations de tests basées sur l''écosystème de modules existant","Focus sur la maintenabilité et l''efficacité","Accès à l''information sur les modules existants"],"de":["Code-Analyse für Qualität und Effizienz","Identifizierung von duplizierten Funktionalitäten","Vorschläge für Refactorings","Empfehlungen für Tests basierend auf dem bestehenden Modul-Ökosystem","Fokus auf Wartbarkeit und Effizienz","Zugriff auf Informationen über bestehende Module"],"pt":["Análise de código para identificar duplicatas e redundâncias","Sugestão de refatoração para melhorar a eficiência do código","Recomendação de testes baseados no ecossistema de módulos existente","Foco em manutenibilidade e eficiência do código","Acesso a informações sobre módulos existentes"],"ru":["Анализ кода для выявления дубликатов и избыточностей","Предложение рефакторинга для улучшения эффективности кода","Рекомендация тестов на основе существующего модульного экосистемы","Фокус на поддерживаемости и эффективности кода","Доступ к информации о существующих модулях"],"ar":["تحليل الكود لتحديد التكرارات والتكرار","اقتراح إعادة الهيكلة لتحسين فاعلية الكود","توصية باختبارات temel على النظام البيئي الحالي للمكونات","التركيز على صيانة الكود وفاعليته","الوصول إلى المعلومات حول المكونات الحالية"]},"keywords":{"en":["how to use clean-code-reviewer","clean-code-reviewer setup guide","code quality assurance tools","clean-code-reviewer alternative","clean-code-reviewer vs sonarqube","what is clean-code-reviewer","clean-code-reviewer install","code review best practices","clean-code-reviewer tutorial","maintainable code principles"],"zh":["Clean Code Reviewer","代码质量优化","AI代码分析","代码清理","代码维护","代码重构","代码测试"],"ja":["Clean Code Reviewer","コード品質最適化","AIコード分析","コードクリーン化","コードメンテナンス","コードリファクタリング","コードテスト"],"ko":["Clean Code Reviewer","코드 품질 최적화","AI 코드 분석","코드 클린니스","코드 유지 보수","코드 리팩토링","코드 테스트"],"es":["clean-code-reviewer","herramientas de revisión de código","mejores prácticas de codificación","refactorización de código","pruebas de código","mantenimiento de código","eficiencia del código","calidad del código","desarrollo de software","ingeniería de software"],"fr":["clean-code-reviewer","outils d''examen de code","meilleures pratiques de codage","refactorisation de code","tests de code","maintenance de code","efficacité du code","qualité du code","développement de logiciels","ingénierie de logiciels"],"de":["clean-code-reviewer","Code-Review-Tools","Best Practices für Codierung","Code-Refactorierung","Code-Tests","Code-Wartung","Code-Effizienz","Code-Qualität","Software-Entwicklung","Software-Ingenieurwesen"],"pt":["clean-code-reviewer","revisão de código","melhores práticas para desenvolvedores","análise de código","refatoração","testes de unidade","manutenibilidade de código","eficiência de código","desenvolvimento de software"],"ru":["ИИ Агент clean-code-reviewer","проверка кода","лучшие практики для разработчиков","анализ кода","рефакторинг","юнит-тесты","поддерживаемость кода","эффективность кода","разработка программного обеспечения"],"ar":["clean-code-reviewer","مراجعة الكود","أفضل الممارسات للطورين","تحليل الكود","إعادة الهيكلة","اختبارات الوحدة","صيانة الكود","فاعلية الكود","تطوير البرمجيات"]}},"owner":"allofmeng","repo":"streamline_project","repoPath":"allofmeng/streamline_project","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.574Z","topics":[],"category":"community","skillMd":{"name":"clean-code-reviewer","description":"Use this agent when reviewing recently written code to identify redundancy, improve cleanliness, suggest refactoring opportunities, and recommend tests based on existing modules and project architecture.","bodyPreview":"You are an expert code reviewer with a specialized focus on ensuring code cleanliness and eliminating redundancy. Your primary responsibilities include analyzing recently written code for quality, identifying duplicate functionality, suggesting refactoring opportunities, and recommending appropriate tests based on the existing module ecosystem.\n\nYour approach should be thorough yet constructive, focusing on maintainability and efficiency. You have access to information about existing modules and","body":"You are an expert code reviewer with a specialized focus on ensuring code cleanliness and eliminating redundancy. Your primary responsibilities include analyzing recently written code for quality, identifying duplicate functionality, suggesting refactoring opportunities, and recommending appropriate tests based on the existing module ecosystem.\n\nYour approach should be thorough yet constructive, focusing on maintainability and efficiency. You have access to information about existing modules and the overall project architecture, which you should leverage when making recommendations.\n\nWhen reviewing code, you will:\n\n1. Analyze the submitted code for potential redundancies by comparing it against existing modules and common patterns in the codebase\n2. Identify areas where code can be simplified, consolidated, or made more readable\n3. Check for adherence to clean code principles including proper naming, single responsibility, and appropriate abstraction levels\n4. Suggest specific refactoring techniques where applicable (extract method, extract class, replace conditional with polymorphism, etc.)\n5. Recommend unit, integration, or end-to-end tests based on the functionality being implemented and how it interacts with existing modules\n6. Point out potential performance issues or maintainability concerns\n7. Verify that error handling and edge cases are properly addressed\n\nYour feedback should be structured as follows:\n- Summary: Brief overview of the code''s quality and main findings\n- Redundancy Issues: Any duplicated functionality or unnecessary complexity found\n- Clean Code Improvements: Specific suggestions for improving readability and maintainability\n- Refactoring Suggestions: Concrete recommendations with implementation approaches\n- Test Recommendations: Specific types of tests that should be added with reasoning based on existing modules\n- Additional Notes: Other observations about code quality, security, or performance\n\nBe specific in your recommendations, providing code examples when necessary. Always justify your suggestions with reference to clean code principles, maintainability, or best practices. When possible, relate your suggestions to how similar functionality is handled in existing modules.\n\nFor test suggestions, consider the interaction between the new code and existing modules, boundary conditions, error scenarios, and critical functionality that should be verified. Prioritize tests that would increase confidence in the code''s correctness and resilience.\n"},"lastSynced":"2026-03-08T02:11:46.824Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Review Agents needing advanced code analysis and refactoring capabilities for maintainability and efficiency.","zh":"非常适合需要高级代码分析和重构功能来提高可维护性和效率的代码审查代理","ja":"コードの可維持性と効率を向上させるための高度なコード分析とリファクタリング機能を必要とするコードレビュー代理に最適","ko":"유지 보수성과 효율성을 높이기 위한 고급 코드 분석 및 리팩토링 기능이 필요한 코드 리뷰 에이전트에 적합","es":"Perfecto para Agentes de Revisión de Código que necesitan capacidades de análisis y refactorización de código avanzadas para mantener la capacidad de mantenimiento y eficiencia.","fr":"Parfait pour les Agents de Revue de Code nécessitant des capacités d''analyse et de réorganisation de code avancées pour la maintenabilité et l''efficacité.","de":"Perfekt für Code-Review-Agents, die erweiterte Codeanalyse- und Refactoring-Funktionen für Wartbarkeit und Effizienz benötigen.","pt":"Perfeito para Agentes de Revisão de Código que necessitam de análise de código avançada e capacidades de refatoração para manutenibilidade e eficiência.","ru":"Идеально подходит для агентов код-ревью, которым необходимы продвинутые возможности анализа и рефакторинга кода для поддерживаемости и эффективности.","ar":"مثالي لوكلاء مراجعة الشفرة الذين بحاجة إلى تحليل متقدم للشفرة وقدرات إعادة الهيكلة من أجل الصيانة والكفاءة."},"recommendation":{"en":"Empowers agents to analyze code quality, identify duplicate functionality, and recommend tests based on existing module ecosystems, utilizing protocols such as code review and refactoring opportunities to ensure a clean and efficient codebase.","zh":"赋予代理分析代码质量、识别重复功能并根据现有的模块生态系统推荐测试的能力，利用代码审查和重构机会等协议以确保代码库干净高效","ja":"コードの品質を分析し、重複する機能を特定し、既存のモジュールのエコシステムに基づいてテストを推奨する能力を代理に与え、コードレビューとリファクタリングの機会などのプロトコルを使用してクリーンで効率的なコードベースを確保する","ko":"에이전트가 코드 품질을 분석하고 중복 기능을 식별하며 기존 모듈의 생태계에 따라 테스트를 권장하는 기능을 제공하여 코드 리뷰 및 리팩토링 기회와 같은 프로토콜을 사용하여 깨끗하고 효율적인 코드베이스를 보장","es":"Habilita a los agentes a analizar la calidad del código, identificar la funcionalidad duplicada y recomendar pruebas basadas en los ecosistemas de módulos existentes, utilizando protocolos como la revisión y las oportunidades de reorganización de código para garantizar una base de código limpia y eficiente.","fr":"Permet aux agents d''analyser la qualité du code, d''identifier les fonctionnalités dupliquées et de recommander des tests basés sur les écosystèmes de modules existants, en utilisant des protocoles tels que l''examen et les opportunités de réorganisation de code pour garantir une base de code propre et efficace.","de":"Ermöglicht es Agents, die Codequalität zu analysieren, doppelte Funktionalitäten zu identifizieren und Tests basierend auf bestehenden Modul-Ökosystemen zu empfehlen, indem sie Protokolle wie Code-Review und Refactoring-Möglichkeiten nutzen, um eine saubere und effiziente Codebasis sicherzustellen.","pt":"Habilita os agentes a analisar a qualidade do código, identificar funcionalidades duplicadas e recomendar testes com base nos ecossistemas de módulos existentes, utilizando protocolos como revisão de código e oportunidades de refatoração para garantir uma base de código limpa e eficiente.","ru":"Наделяет агентов возможностью анализировать качество кода, выявлять дублирующую функциональность и рекомендовать тесты на основе существующих модульных экосистем, используя такие протоколы, как код-ревью и возможности рефакторинга, для обеспечения чистой и эффективной кодовой базы.","ar":"تمكّن الوكلاء من تحليل جودة الشفرة وتحديد الوظائف المكررة وتقديم توصيات لاختبارات بناءً على بيئات الوحدات الحالية، باستخدام بروتوكولات مثل مراجعة الشفرة وفرص إعادة الهيكلة لضمان قاعدة شفرة نظيفة وفعّالة."},"useCases":{"en":["Analyzing recently written code for quality and redundancy","Identifying and eliminating duplicate functionality"," Recommending appropriate tests for existing modules","Suggesting refactoring opportunities for improved maintainability"],"zh":["分析最近编写的代码以检查质量和冗余性","识别并消除重复功能","为现有的模块推荐适当的测试","建议改进可维护性的重构机会"],"ja":["最近に書かれたコードを品質と冗長性のために分析する","重複する機能を特定し、除去する","既存のモジュールに適したテストを推奨する","保守性の向上のためのリファクタリングの機会を提案する"],"ko":["최근 작성된 코드를 품질과 중복성으로 분석","중복 기능을 식별하고 제거","기존 모듈에 적합한 테스트를 권장","유지 보수성을 개선하기 위한 리팩토링 기회를 제안"],"es":["Analizar el código recientemente escrito para la calidad y la redundancia","Identificar y eliminar la funcionalidad duplicada","Recomendar pruebas adecuadas para módulos existentes","Sugerir oportunidades de reorganización para una mejor mantenibilidad"],"fr":["Analyser le code récemment écrit pour la qualité et la redondance","Identifier et éliminer les fonctionnalités dupliquées","Recommander des tests appropriés pour les modules existants","Suggérer des opportunités de réorganisation pour une meilleure maintenabilité"],"de":["Kürzlich geschriebenen Code auf Qualität und Redundanz analysieren","Doppelte Funktionalitäten identifizieren und eliminieren","Für bestehende Module geeignete Tests empfehlen","Refactoring-Möglichkeiten für eine verbesserte Wartbarkeit vorschlagen"],"pt":["Analisar o código recentemente escrito para qualidade e redundância","Identificar e eliminar funcionalidades duplicadas","Recomendar testes apropriados para módulos existentes","Sugerir oportunidades de refatoração para melhor manutenibilidade"],"ru":["Анализировать недавно написанный код на качество и избыточность","Выявлять и устранять дублирующую функциональность","Рекомендовать подходящие тесты для существующих модулей","Предлагать возможности рефакторинга для улучшения поддерживаемости"],"ar":["تحليل الشفرة المكتوبة حديثًا لجودة والتكرار","تحديد القضاء على الوظائف المكررة","توصية باختبارات مناسبة للوحدات الحالية","اقتراح فرص إعادة الهيكلة لتحسين الصيانة"]},"limitations":{"en":["Requires access to existing module information","Focus on code quality and maintainability may not cover all aspects of code development"],"zh":["需要访问现有的模块信息","对代码质量和可维护性的关注可能无法涵盖代码开发的所有方面"],"ja":["既存のモジュール情報へのアクセスが必要","コードの品質と保守性への焦点は、コード開発のすべての側面をカバーできない可能性がある"],"ko":["기존 모듈 정보에 대한 액세스가 필요","코드 품질 및 유지 보수성에 대한 중점은 코드 개발의 모든 측면을 다루지 못할 수 있음"],"es":["Requiere acceso a la información del módulo existente","El enfoque en la calidad y la mantenibilidad del código puede no cubrir todos los aspectos del desarrollo de código"],"fr":["Nécessite un accès à l''information du module existant","L''accent mis sur la qualité et la maintenabilité du code peut ne pas couvrir tous les aspects du développement de code"],"de":["Benötigt Zugriff auf die Informationen des bestehenden Moduls","Der Fokus auf die Codequalität und Wartbarkeit kann nicht alle Aspekte der Codeentwicklung abdecken"],"pt":["Requer acesso a informações de módulos existentes","O foco na qualidade do código e na manutenibilidade pode não cobrir todos os aspectos do desenvolvimento de código"],"ru":["Требует доступа к информации о существующих модулях","Фокус на качестве кода и поддерживаемости может не охватывать все аспекты разработки кода"],"ar":["يتطلب الوصول إلى معلومات الوحدات الحالية","التركيز على جودة الشفرة والصيانة قد لا يغطي جميع جوانب تطوير الشفرة"]},"version":4},"contentHash":"d33b4a33b2eb60593a6367dc20d49920e467edb854a8c93cc2738e0698d03507","qualityScore":23}');
