INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('allofmeng/streamline_project/clean-code-reviewer', 'clean-code-reviewer', 'allofmeng', 'streamline_project', 'community', 'clean-code-reviewer allofmeng streamline_project community The clean-code-reviewer skill analyzes code for quality, identifies duplicate functionality, and recommends tests. It benefits developers by ensuring maintainability and efficiency in their codebase. Clean Code Reviewer是一种专注于代码清理和消除冗余的AI工具，帮助开发者提高代码质量和维护效率 Clean Code Reviewerは、コードのクリーン化と冗長性の除去に特化したAIツールで、開発者のコード品質とメンテナンス効率を向上させる Clean Code Reviewer는 코드 클린니스와 중복 제거에 특화된 AI 도구로, 개발자의 코드 품질과 유지 보수 효율성을 향상 Clean-code-reviewer es una herramienta de revisión de código especializada en garantizar la limpieza y eficiencia del código, identificando funcionalidades duplicadas y sugiriendo refactorizaciones Clean-code-reviewer est un outil d''examen de code spécialisé dans l''assurance de la propreté et de l''efficacité du code, en identifiant les fonctionnalités dupliquées et en suggérant des refactorisations Clean-code-reviewer ist ein Code-Review-Tool, das auf die Gewährleistung von Sauberkeit und Effizienz des Codes spezialisiert ist, indem es duplizierte Funktionalitäten identifiziert und Refactorings vorschlägt O clean-code-reviewer é uma ferramenta especializada em garantir a limpeza e eficiência do código. Ele analisa o código recentemente escrito para identificar duplicatas e sugerir refatoração. ИИ Агент clean-code-reviewer - это специализированный инструмент, обеспечивающий чистоту и эффективность кода. Он анализирует недавно написанный код для выявления дубликатов и предложения рефакторинга. clean-code-reviewer هو أداة متخصصة في ضمان نظافة الكود وفاعليته. يقوم بتحليل الكود المكتوب حديثًا لتحديد التكرارات واقتراح إعادة الهيكلة. how to use clean-code-reviewer clean-code-reviewer setup guide code quality assurance tools clean-code-reviewer alternative clean-code-reviewer vs sonarqube what is clean-code-reviewer clean-code-reviewer install code review best practices clean-code-reviewer tutorial maintainable code principles Clean Code Reviewer 代码质量优化 AI代码分析 代码清理 代码维护 代码重构 代码测试 Analyzes recently written code for quality and maintainability Identifies duplicate functionality and suggests refactoring opportunities Recommends appropriate tests based on the existing module ecosystem Ensures code efficiency and eliminates redundancy Provides thorough yet constructive code review feedback Utilizes knowledge of existing modules for informed code review clean-code-reviewer is a specialized skill that focuses on ensuring code cleanliness, eliminating redundancy, and suggesting refactoring opportunities for improved code quality and maintainability.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('vikramsg/mossl/brainstorm', 'community', 'vikramsg', 'mossl', 'vikramsg/mossl', 'brainstorm', 0, 0, 23, '2026-03-08T01:57:15.574Z', '2026-03-08T02:11:46.954Z', 'a7cfa7ad13b94348ea18f2802582ecf97287f36b4742153b064c46066388c86d', '{"id":"vikramsg/mossl/brainstorm","name":"brainstorm","description":{"en":"Brainstorm is a technical skill for collaborative conceptual discussion, helping developers explore ideas and evaluate architectural decisions without writing code. It benefits developers and teams looking for a purely conceptual approach to technical brainstorming.","zh":"AI智能脑暴技术是一种纯概念性的讨论，用于探索想法和评估架构决策","ja":"AIエージェントのブレインストーミングは、アイデアを探索し、設計パターンを評価するための純粋な概念的な方法です","ko":"AI 브레인스토밍은 아이디어를 탐색하고 설계 패턴을 평가하는 순수한 개념적 논의입니다","es":"La habilidad de brainstorm es una herramienta de colaboración conceptual para explorar ideas y evaluar decisiones arquitectónicas sin codear","fr":"La compétence de brainstorm est un outil de collaboration conceptuel pour explorer des idées et évaluer les décisions d''architecture sans coder","de":"Die Brainstorm-Fähigkeit ist ein konzeptionelles Kollaborationswerkzeug, um Ideen zu erkunden und Architekturentscheidungen zu bewerten, ohne zu coden","pt":"A função de brainstorm é uma ferramenta conceitual que ajuda a explorar ideias e avaliar decisões arquiteturais de forma colaborativa","ru":"Функция brainstorm - это концептуальный инструмент, который помогает исследовать идеи и оценивать архитектурные решения в сотрудничестве","ar":"أداة العصف الذهني هي أداة مفاهيمية تساعد على مناقشة الأفكار وتقييم القرارات المعمارية بطريقة تعاونية"},"seo":{"title":{"en":"Brainstorm: Collaborative Conceptual Discussion Guide | A...","zh":"AI智能脑暴技术指南","ja":"AIエージェントのブレインストーミングベストプラクティス","ko":"AI 브레인스토밍 설정 가이드","es":"Guía de Configuración de Brainstorm para Desarrolladores","fr":"Guide de Mise en Place de Brainstorm pour les Développeurs","de":"Einrichtungsleitfaden für Brainstorm-Technologie","pt":"Guia de Configuração de Brainstorm para Desenvolvedores","ru":"ИИ Агенты: Руководство по Настройке Функции Brainstorm","ar":"دليل إعداد أداة العصف الذهني للمطورين"},"description":{"en":"Unlock innovative ideas with Brainstorm! Explore technical concepts, evaluate architectural decisions, and discuss syntax without writing code. Learn how to ...","zh":"了解AI智能脑暴技术的概念和应用，探索架构决策和设计模式","ja":"AIエージェントのブレインストーミング機能を活用して、アイデアを探索し、設計パターンを評価する","ko":"AI 브레인스토밍을 통한 개념적 논의와 설계 패턴 평가 방법","es":"Descubre cómo utilizar la habilidad de brainstorm para explorar ideas y evaluar decisiones arquitectónicas sin escribir código","fr":"Découvrez comment utiliser la compétence de brainstorm pour explorer des idées et évaluer les décisions d''architecture sans écrire de code","de":"Erfahren Sie, wie Sie die Brainstorm-Fähigkeit nutzen können, um Ideen zu erkunden und Architekturentscheidungen zu bewerten, ohne Code zu schreiben","pt":"Aprenda a utilizar a função de brainstorm para explorar ideias e avaliar decisões arquiteturais de forma colaborativa e conceitual","ru":"Изучите, как использовать функцию brainstorm для обсуждения концепций и оценки архитектурных решений в ИИ Агентах","ar":"تعلم كيفية استخدام أداة العصف الذهني لمناقشة الأفكار وتقييم القرارات المعمارية بطريقة تعاونية ومفاهيمية"},"definition":{"en":"Brainstorm is a specialized technical skill for collaborative conceptual discussion, focusing on exploring ideas, evaluating architectural decisions, and discussing syntax or design patterns.","zh":"AI智能脑暴技术是一种用于探索想法和评估架构决策的纯概念性的讨论方法","ja":"AIエージェントのブレインストーミングとは、アイデアを探索し、設計パターンを評価するための純粋な概念的な方法です","ko":"AI 브레인스토밍은 아이디어를 탐색하고 설계 패턴을 평가하는 순수한 개념적 논의 방법입니다","es":"¿Qué es brainstorm? Es una habilidad de colaboración conceptual para explorar ideas y evaluar decisiones arquitectónicas","fr":"Qu''est-ce que le brainstorm? C''est une compétence de collaboration conceptuel pour explorer des idées et évaluer les décisions d''architecture","de":"Was ist Brainstorm? Es ist eine konzeptionelle Kollaborationsfähigkeit, um Ideen zu erkunden und Architekturentscheidungen zu bewerten","pt":"O que é brainstorm? É uma função de discussão conceitual que ajuda a explorar ideias e avaliar decisões arquiteturais","ru":"Что такое функция brainstorm? Это концептуальный инструмент обсуждения, который помогает исследовать идеи и оценивать архитектурные решения","ar":"ما هي أداة العصف الذهني؟ هي أداة مناقشة مفاهيمية تساعد على مناقشة الأفكار وتقييم القرارات المعمارية"},"features":{"en":["Enables purely conceptual discussions on technical topics","Helps evaluate architectural decisions without concrete implementation","Facilitates collaborative exploration of ideas and syntax","Operates without writing, modifying, or suggesting code changes","Supports discussion of design patterns and technical concepts"],"zh":["纯概念性的讨论","探索想法和评估架构决策","不涉及代码编写或修改","不提供代码实现","专注于设计模式和语法讨论"],"ja":["純粋な概念的な討論","アイデアを探索し、設計パターンを評価","コードの書き換えや実装は行わない","コードの提供は行わない","設計パターンと構文の議論に焦点を当てる"],"ko":["순수한 개념적 논의","아이디어를 탐색하고 설계 패턴을 평가","코드 작성 또는 수정을 포함하지 않음","코드 구현을 제공하지 않음","설계 패턴과 구문 논의에 중점을 둠"],"es":["Exploración de ideas sin restricciones de código","Evaluación de decisiones arquitectónicas de manera colaborativa","Discusión de patrones de diseño y sintaxis sin implementación","Colaboración puramente conceptual sin oferta de implementación","No requiere escritura o modificación de código"],"fr":["Exploration d''idées sans restrictions de code","Évaluation des décisions d''architecture de manière collaborative","Discussion de modèles de conception et de syntaxe sans implémentation","Collaboration purement conceptuel sans offre d''implémentation","Nécessite pas l''écriture ou la modification de code"],"de":["Exploration von Ideen ohne Code-Einschränkungen","Bewertung von Architekturentscheidungen in kollaborativer Weise","Diskussion von Entwurfsmustern und Syntax ohne Implementierung","Reine konzeptionelle Kollaboration ohne Implementierungsangebot","Erfordert keine Code-Schreibung oder -Modifikation"],"pt":["Discussão conceitual de ideias e decisões arquiteturais","Avaliação de padrões de design e sintaxe","Colaboração puramente conceitual sem escrita de código","Análise de decisões arquiteturais sem implementação","Exploração de ideias sem oferta de implementação"],"ru":["Концептуальное обсуждение идей и архитектурных решений","Оценка шаблонов проектирования и синтаксиса","Сотрудничество в чисто концептуальном ключе без написания кода","Анализ архитектурных решений без реализации","Изучение идей без предложения реализации"],"ar":["مناقشة مفاهيمية للأفكار والقرارات المعمارية","تقييم أنماط التصميم والصياغة","تعاون مفاهيمي خالص بدون كتابة Код","تحليل القرارات المعمارية بدون تنفيذ","مناقشة الأفكار بدون عرض تنفيذ"]},"keywords":{"en":["how to use brainstorm","what is brainstorm","brainstorm alternative","brainstorm vs mind mapping","brainstorm setup guide","collaborative technical discussion","conceptual brainstorming techniques","technical idea generation"],"zh":["AI智能脑暴","纯概念性的讨论","架构决策","设计模式","语法讨论","AI技术","智能开发","概念性开发"],"ja":["AIエージェント","ブレインストーミング","純粋な概念的な討論","設計パターン","構文の議論","AI技術","スマート開発","概念開発"],"ko":["AI 브레인스토밍","순수한 개념적 논의","설계 패턴","구문 논의","AI 기술","智能 개발","개념 개발","개발 방법론"],"es":["brainstorm para desarrolladores","herramientas de colaboración conceptual","evaluación de decisiones arquitectónicas","exploración de ideas sin código","patrones de diseño y sintaxis","colaboración puramente conceptual","desarrollo de software sin código","brainstorm en español"],"fr":["brainstorm pour les développeurs","outils de collaboration conceptuel","évaluation des décisions d''architecture","exploration d''idées sans code","modèles de conception et syntaxe","collaboration purement conceptuel","développement de logiciels sans code","brainstorm en français","agents d''intelligence artificielle"],"de":["brainstorm für Entwickler","Werkzeuge für konzeptionelle Kollaboration","Bewertung von Architekturentscheidungen","Exploration von Ideen ohne Code","Entwurfsmuster und Syntax","reine konzeptionelle Kollaboration","Software-Entwicklung ohne Code","brainstorm auf Deutsch","Künstliche Intelligenz Agenten"],"pt":["brainstorm para desenvolvedores","ferramentas de brainstorm","desenvolvimento de software","arquitetura de software","padrões de design","sintaxe de programação","colaboração em desenvolvimento","análise de decisões arquiteturais","exploração de ideias"],"ru":["ИИ Агенты для разработчиков","инструменты brainstorm","разработка программного обеспечения","архитектура программного обеспечения","шаблоны проектирования","синтаксис программирования","сотрудничество в разработке","анализ архитектурных решений","изучение идей"],"ar":["أدوات العصف الذهني للمطورين","ادوات العصف الذهني","تطوير البرمجيات","هندسة البرمجيات","انماط التصميم","صياغة البرمجة","التعاون في التطوير","تحليل القرارات المعمارية","مناقشة الأفكار"]}},"owner":"vikramsg","repo":"mossl","repoPath":"vikramsg/mossl","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.574Z","topics":[],"category":"community","skillMd":{"name":"brainstorm","description":"Specialized skill for brainstorming technical ideas, architectural patterns, and syntax choices. Use this skill when the user asks to brainstorm ideas, implementation details, logic etc.","bodyPreview":"# Technical Brainstorming Skill\n\nYou are a specialized technical brainstormer. Your goal is to help explore ideas, evaluate architectural decisions, and discuss syntax or design patterns in a collaborative, purely conceptual manner.\n\n## Constraints\n- **NO CODE WRITING:** You must not write, modify, or suggest concrete code changes for the codebase.\n- **NO CODE OFFERS:** You must not offer to implement the brainstormed ideas. Your role ends at the conceptual discussion.\n- **PURELY CONCEPTUAL:** F","body":"# Technical Brainstorming Skill\n\nYou are a specialized technical brainstormer. Your goal is to help explore ideas, evaluate architectural decisions, and discuss syntax or design patterns in a collaborative, purely conceptual manner.\n\n## Constraints\n- **NO CODE WRITING:** You must not write, modify, or suggest concrete code changes for the codebase.\n- **NO CODE OFFERS:** You must not offer to implement the brainstormed ideas. Your role ends at the conceptual discussion.\n- **PURELY CONCEPTUAL:** Focus on \"Why\", \"How (theoretically)\", and \"What if\" rather than implementation.\n\n## Workflow\n\n1. **Idea Exploration:**\n   - Use `web_search` to find industry best practices, alternative libraries, or emerging patterns.\n   - Use `delegate_to_agent` with the `codebase_investigator` agent to understand current architectural constraints or patterns in the codebase.\n   - Compare and contrast different approaches.\n   - Use `docs/syntax` to help base Mojo syntax suggestions on.\n\n2. **Analysis & Discussion:**\n   - Evaluate trade-offs (e.g., performance vs. readability, complexity vs. flexibility).\n   - Discuss syntax options and how they fit within the Mojo ecosystem or existing project conventions.\n   - Propose architectural diagrams (in Mermaid or text) or structural concepts.\n\n3. **Output:**\n   - Provide structured brainstorm reports.\n   - If the user wants to keep a record of the brainstorming session, write it to a Markdown file in `docs/brainstorming/` (create the directory if it doesn''t exist).\n\n4. **Response Structure:**\n   - **Concepts:** High-level ideas being discussed.\n   - **Trade-offs:** Pros and cons of each approach.\n   - **Research Insights:** Relevant findings from the web or codebase.\n   - **Open Questions:** Things that still need to be considered or decided."},"lastSynced":"2026-03-08T02:11:46.954Z","agentAnalysis":{"suitability":{"en":"Ideal for Collaborative AI Agents like Claude Code and LangChain needing advanced technical conceptualization capabilities.","zh":"适合于需要高级技术概念化能力的协作 AI 代理，如 Claude Code 和 LangChain。","ja":"Claude Code や LangChain などの高度な技術概念化能力を必要とするコラボレーション AI エージェントに最適。","ko":"고급 기술 개념화 능력이 필요한 협업 AI 에이전트인 Claude Code 및 LangChain에 적합합니다.","es":"Ideal para Agentes de IA Colaborativos como Claude Code y LangChain que necesitan capacidades de conceptualización técnica avanzada.","fr":"Idéal pour les agents d''IA collaboratifs comme Claude Code et LangChain nécessitant des capacités de conceptualisation technique avancée.","de":"Ideal für kollaborative KI-Agents wie Claude Code und LangChain, die erweiterte technische Konzeptualisierungsfähigkeiten benötigen.","pt":"Ideal para Agentes de IA Colaborativos como Claude Code e LangChain que necessitam de capacidades de conceptualização técnica avançadas.","ru":"Идеально подходит для совместных агентов ИИ, таких как Claude Code и LangChain, требующих передовых технических концептуализационных возможностей.","ar":"مثالي لعناصر التعاون الإلكتروني مثل Claude Code و LangChain التي تحتاج إلىقدرات概念ية تقنية متقدمة."},"recommendation":{"en":"Empowers agents to facilitate collaborative technical discussions, evaluate architectural decisions, and explore ideas using purely conceptual approaches, without writing code, and focusing on syntax or design patterns.","zh":"赋予代理能力以促进协作技术讨论，评估架构决策，并使用纯概念方法探索想法，而无需编写代码，并专注于语法或设计模式。","ja":"エージェントがコラボレーション技術討論を促進し、設計上の決定を評価し、コードを書かずに、構文やデザイン パターンに焦点を当てずに、純粋に概念的なアプローチを使用してアイデアを探索できるようにする。","ko":"에이전트가 협업 기술 논의를 촉진하고 아키텍처 결정사항을 평가하며 코드를 작성하지 않고 문법 또는 디자인 패턴에 집중하지 않고 순수한 개념적인 접근 방식을 사용하여 아이디어를 탐색할 수 있도록 합니다.","es":"Habilita a los agentes a facilitar discusiones técnicas colaborativas, evaluar decisiones arquitectónicas y explorar ideas utilizando enfoques puramente conceptuales, sin escribir código y centrándose en la sintaxis o los patrones de diseño.","fr":"Permet aux agents de faciliter les discussions techniques collaboratives, d''évaluer les décisions architecturales et d''explorer des idées en utilisant des approches purement conceptuelles, sans écrire de code et en se concentrant sur la syntaxe ou les modèles de conception.","de":"Ermöglicht es den Agents, kollaborative technische Diskussionen zu erleichtern, architektonische Entscheidungen zu bewerten und Ideen mithilfe rein konzeptioneller Ansätze zu erkunden, ohne Code zu schreiben und sich auf die Syntax oder Entwurfsmuster zu konzentrieren.","pt":"Habilita os agentes a facilitar discussões técnicas colaborativas, avaliar decisões arquitetônicas e explorar ideias usando abordagens puramente conceituais, sem escrever código e se concentrar na sintaxe ou padrões de design.","ru":"Наделяет агентов возможностью облегчить совместные технические дискуссии, оценить архитектурные решения и изучить идеи, используя чисто концептуальный подход, без написания кода и сосредоточения внимания на синтаксисе или шаблонах проектирования.","ar":"تمكّن العناصر من تسهيل مناقشات تقنية تعاونية، وتقييم قرارات هندسية، واستكشاف أفكار باستخدام نهج مفهومي بحت، دون كتابة الشفرة والتركيز على بنية اللغة أو أنماط التصميم."},"useCases":{"en":["Facilitating collaborative technical brainstorming sessions","Evaluating architectural decisions without code implementation","Discussing syntax or design patterns in a conceptual manner"],"zh":["促进协作技术头脑风暴会议","评估架构决策而无需代码实现","以概念方式讨论语法或设计模式"],"ja":["コラボレーション技術ブレーンストーミング セッションを促進する","コードの実装なしで設計上の決定を評価する","構文またはデザイン パターンを概念的に議論する"],"ko":["협업 기술 브레인스토밍 세션을 촉진하는 것","코드 구현 없이 아키텍처 결정 사항을 평가하는 것","문법 또는 디자인 패턴을 개념적으로 논의하는 것"],"es":["Facilitar sesiones de lluvia de ideas técnicas colaborativas","Evaluar decisiones arquitectónicas sin implementación de código","Discutir la sintaxis o los patrones de diseño de manera conceptual"],"fr":["Faciliter les sessions de brainstorming technique collaboratif","Évaluer les décisions architecturales sans implémentation de code","Discuter de la syntaxe ou des modèles de conception de manière conceptuelle"],"de":["Kollaborative technische Brainstorming-Sitzungen erleichtern","Architektonische Entscheidungen ohne Codeimplementierung bewerten","Syntax oder Entwurfsmuster auf konzeptionelle Weise diskutieren"],"pt":["Facilitar sessões de brainstorming técnico colaborativo","Avaliar decisões arquitetônicas sem implementação de código","Discutir sintaxe ou padrões de design de maneira conceitual"],"ru":["Облегчение совместных технических мозговых штурмов","Оценка архитектурных решений без реализации кода","Обсуждение синтаксиса или шаблонов проектирования в концептуальном порядке"],"ar":["تسهيل جلسات العصف الذهني الفني التعاوني","تقييم القرارات الهندسية دون تنفيذ الشفرة","مناقشة بنية اللغة أو أنماط التصميم بطريقة مفهومية"]},"limitations":{"en":["No code writing or modification allowed","No implementation or coding of brainstormed ideas","Purely conceptual discussions only"],"zh":["不允许编写或修改代码","不允许实现或编码大脑风暴的想法","仅概念讨论"],"ja":["コードの書き込みや修正を許可しない","ブレーンストーミングされたアイデアの実装やコード化を許可しない","純粋に概念的な議論のみ"],"ko":["코드 작성 또는 수정을 허용하지 않음","브레인스토밍된 아이디어의 구현 또는 코딩을 허용하지 않음","순수한 개념적인 논의만"],"es":["No se permite la escritura o modificación de código","No se permite la implementación o codificación de ideas generadas","Discusiones puramente conceptuales solo"],"fr":["Aucune écriture ou modification de code n''est autorisée","Aucune implémentation ou codage des idées générées n''est autorisé","Discussions purement conceptuelles uniquement"],"de":["Keine Code-Schreibung oder -Änderung erlaubt","Keine Implementierung oder Kodierung der braingestormten Ideen","Rein konzeptionelle Diskussionen nur"],"pt":["Não é permitida a escrita ou modificação de código","Não é permitida a implementação ou codificação de ideias geradas","Discussões puramente conceituais apenas"],"ru":["Не допускается написание или изменение кода","Не допускается реализация или кодирование задуманных идей","Только чисто концептуальные обсуждения"],"ar":["لا يسمح بكتابة أو تعديل الشفرة","لا يسمح بالتنفيذ أو برمجة الأفكار المبتكرة","مناقشات مفهومية بحتة فقط"]},"version":4},"contentHash":"a7cfa7ad13b94348ea18f2802582ecf97287f36b4742153b064c46066388c86d","qualityScore":23}');
