INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('vikramsg/mossl/brainstorm', 'brainstorm', 'vikramsg', 'mossl', 'community', 'brainstorm vikramsg mossl community Brainstorm is a technical skill for collaborative conceptual discussion, helping developers explore ideas and evaluate architectural decisions without writing code. It benefits developers and teams looking for a purely conceptual approach to technical brainstorming. AI智能脑暴技术是一种纯概念性的讨论，用于探索想法和评估架构决策 AIエージェントのブレインストーミングは、アイデアを探索し、設計パターンを評価するための純粋な概念的な方法です AI 브레인스토밍은 아이디어를 탐색하고 설계 패턴을 평가하는 순수한 개념적 논의입니다 La habilidad de brainstorm es una herramienta de colaboración conceptual para explorar ideas y evaluar decisiones arquitectónicas sin codear La compétence de brainstorm est un outil de collaboration conceptuel pour explorer des idées et évaluer les décisions d''architecture sans coder Die Brainstorm-Fähigkeit ist ein konzeptionelles Kollaborationswerkzeug, um Ideen zu erkunden und Architekturentscheidungen zu bewerten, ohne zu coden A função de brainstorm é uma ferramenta conceitual que ajuda a explorar ideias e avaliar decisões arquiteturais de forma colaborativa Функция brainstorm - это концептуальный инструмент, который помогает исследовать идеи и оценивать архитектурные решения в сотрудничестве أداة العصف الذهني هي أداة مفاهيمية تساعد على مناقشة الأفكار وتقييم القرارات المعمارية بطريقة تعاونية how to use brainstorm what is brainstorm brainstorm alternative brainstorm vs mind mapping brainstorm setup guide collaborative technical discussion conceptual brainstorming techniques technical idea generation AI智能脑暴 纯概念性的讨论 架构决策 设计模式 语法讨论 AI技术 智能开发 概念性开发 Enables purely conceptual discussions on technical topics Helps evaluate architectural decisions without concrete implementation Facilitates collaborative exploration of ideas and syntax Operates without writing, modifying, or suggesting code changes Supports discussion of design patterns and technical concepts Brainstorm is a specialized technical skill for collaborative conceptual discussion, focusing on exploring ideas, evaluating architectural decisions, and discussing syntax or design patterns.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('cggonzal/monolith/monolith-websocket-pubsub', 'community', 'cggonzal', 'monolith', 'cggonzal/monolith', 'monolith-websocket-pubsub', 0, 0, 23, '2026-03-08T01:57:15.583Z', '2026-03-08T02:11:55.353Z', '43f2fd627b5158f47587208d1600798762d12f6ab1a53d12f384c63c4ee4a68f', '{"id":"cggonzal/monolith/monolith-websocket-pubsub","name":"monolith-websocket-pubsub","description":{"en":"monolith-websocket-pubsub is a Go framework for building full-stack web apps with built-in support for WebSocket pub/sub. It benefits developers building real-time applications.","zh":"monolith-websocket-pubsub 是一个 Go 框架，用于构建全栈 Web 应用，具有代码生成、认证、ORM 和 WebSocket 支持等功能","ja":"monolith-websocket-pubsub は、Go で構築されたフルスタック Web アプリケーションのフレームワークで、コード生成、認証、ORM、WebSocket などをサポートしています","ko":"monolith-websocket-pubsub는 Go로 구축된 풀스택 웹 애플리케이션 프레임워크로 코드 생성, 인증, ORM, WebSocket 등을 지원합니다","es":"Monolith-websocket-pubsub es un framework de Go para aplicaciones web full stack con soporte integrado para generación de código, autenticación, ORM y más","fr":"Monolith-websocket-pubsub est un framework Go pour les applications web full stack avec prise en charge intégrée de la génération de code, de l''authentification, de l''ORM et plus","de":"Monolith-websocket-pubsub ist ein Go-Framework für Full-Stack-Webanwendungen mit integrierter Unterstützung für Codegenerierung, Authentifizierung, ORM und mehr","pt":"O monolith-websocket-pubsub é um framework Go para aplicativos web full stack com recursos como code generation, autenticação e pub/sub via web sockets","ru":"monolith-websocket-pubsub - это фреймворк Go для веб-приложений с поддержкой кода, аутентификации и pub/sub через веб-сокеты. ИИ Агенты","ar":"monolith-websocket-pubsub هو إطار عمل Go لتطبيقات الويب الكاملة مع ميزات مثل توليد الكود والتحقق والنشر/الاشتراك عبر сокيتات الويب"},"seo":{"title":{"en":"monolith-websocket-pubsub: WebSocket Pub/Sub Setup Guide ...","zh":"monolith-websocket-pubsub 实时更新指南","ja":"monolith-websocket-pubsub のリアルタイム更新設定","ko":"monolith-websocket-pubsub 실시간 업데이트 설정 가이드","es":"Guía de configuración de monolith-websocket-pubsub para a...","fr":"Guide de mise en place de monolith-websocket-pubsub pour ...","de":"Einrichtungsleitfaden für monolith-websocket-pubsub in Ec...","pt":"Guia de Configuração do monolith-websocket-pubsub para Ap...","ru":"Настройка monolith-websocket-pubsub для веб-приложений: И...","ar":"دليل إعداد monolith-websocket-pubsub للأجهزة الاصطناعية ف..."},"description":{"en":"Unlock real-time updates with monolith-websocket-pubsub. Learn how to implement WebSocket pub/sub for chat and live updates. Get started now!","zh":"使用 monolith-websocket-pubsub 实现实时更新和聊天功能，了解其工作原理和关键特性","ja":"monolith-websocket-pubsub を使用してリアルタイム更新とチャット機能を実現します。其のしくみと主な特徴をご紹介します","ko":"monolith-websocket-pubsub를 사용하여 실시간 업데이트와 채팅 기능을 구현하는 방법과 주요 특징에 대해 알아보세요","es":"Aprenda a utilizar monolith-websocket-pubsub para crear aplicaciones web con actualizaciones en tiempo real y funcionalidades de chat","fr":"Découvrez comment utiliser monolith-websocket-pubsub pour créer des applications web avec mises à jour en temps réel et fonctionnalités de chat","de":"Erfahren Sie, wie Sie monolith-websocket-pubsub verwenden können, um Webanwendungen mit Echtzeit-Updates und Chat-Funktionen zu erstellen","pt":"Aprenda a configurar o monolith-websocket-pubsub para aplicativos web full stack com suporte a code generation, autenticação e muito mais","ru":"Узнайте, как настроить monolith-websocket-pubsub для веб-приложений с поддержкой кода, аутентификации и многого другого. ИИ Агенты","ar":"تعلم كيفية إعداد monolith-websocket-pubsub لتطبيقات الويب الكاملة مع دعم توليد الكود والتحقق والكثير غير ذلك"},"definition":{"en":"monolith-websocket-pubsub is a Go framework providing built-in support for code generation, authentication, and WebSocket pub/sub for real-time updates.","zh":"monolith-websocket-pubsub 是一个支持 WebSocket 的 Go 框架","ja":"monolith-websocket-pubsub は WebSocket をサポートする Go フレームワークです","ko":"monolith-websocket-pubsub는 WebSocket을 지원하는 Go 프레임워크입니다","es":"Monolith-websocket-pubsub es un framework de Go que permite crear aplicaciones web con funcionalidades de pub/sub y WebSocket","fr":"Monolith-websocket-pubsub est un framework Go qui permet de créer des applications web avec des fonctionnalités de pub/sub et WebSocket","de":"Monolith-websocket-pubsub ist ein Go-Framework, das die Erstellung von Webanwendungen mit Pub/Sub- und WebSocket-Funktionen ermöglicht","pt":"O monolith-websocket-pubsub é um framework Go para aplicativos web que fornece recursos de pub/sub via web sockets","ru":"monolith-websocket-pubsub - это фреймворк Go для веб-приложений, обеспечивающий функции pub/sub через веб-сокеты","ar":"monolith-websocket-pubsub هو إطار عمل Go لتطبيقات الويب التي يوفر ميزات النشر/الاشتراك عبر сокيتات الويب"},"features":{"en":["Supports WebSocket pub/sub via JSON commands","Includes implementation in ws/ws.go for server behavior","Uses persistent message model in app/models/ws.go","Allows subscription and publishing via GET /ws route","Sends JSON commands for subscribe and publish actions","Tracks hub subscriptions for efficient message broadcasting"],"zh":["代码生成","认证和授权","ORM（gorm）支持","WebSocket 实时更新","pub/sub 消息广播","Job 队列和部署支持"],"ja":["コード生成","認証と認可","ORM（gorm）サポート","WebSocket リアルタイム更新","pub/sub メッセージブロードキャスト","ジョブキューとデプロイサポート"],"ko":["코드 생성","인증과 인가","ORM（gorm）지원","WebSocket 실시간 업데이트","pub/sub 메시지 방송","작업 큐와 배포 지원"],"es":["Soporte integrado para código generación","Autenticación y ORM con gorm","Funcionalidades de pub/sub y WebSocket","Colas de trabajo y sesiones","Soporte para despliegues y depuración"],"fr":["Prise en charge intégrée de la génération de code","Authentification et ORM avec gorm","Fonctionnalités de pub/sub et WebSocket","Files d''attente et sessions","Prise en charge des déploiements et de la débogage"],"de":["Integrierte Unterstützung für Codegenerierung","Authentifizierung und ORM mit gorm","Pub/Sub- und WebSocket-Funktionen","Warteschlangen und Sitzungen","Unterstützung für Bereitstellungen und Debugging"],"pt":["Suporte a code generation","Autenticação e sessions","ORM (gorm) para gerenciamento de banco de dados","Suporte a pub/sub via web sockets","Filas de trabalhos e deploy"],"ru":["Поддержка кода","Аутентификация и сессии","ORM (gorm) для управления базой данных","Поддержка pub/sub через веб-сокеты","Очереди заданий и deploy"],"ar":["دعم توليد الكود","التحقق والجلسات","نظام إدارة قواعد البيانات (gorm)","دعم النشر/الاشتراك عبر сокيتات الويب","الوظائف والتركيب"]},"keywords":{"en":["how to use monolith-websocket-pubsub","monolith-websocket-pubsub alternative","monolith-websocket-pubsub setup guide","what is monolith-websocket-pubsub","monolith-websocket-pubsub vs Rails","monolith-websocket-pubsub install","WebSocket pub/sub implementation","Go framework for real-time updates","monolith-websocket-pubsub documentation"],"zh":["monolith-websocket-pubsub","Go 框架","WebSocket","实时更新","聊天功能","代码生成","认证和授权","ORM"],"ja":["monolith-websocket-pubsub","Go フレームワーク","WebSocket","リアルタイム更新","チャット機能","コード生成","認証と認可","ORM"],"ko":["monolith-websocket-pubsub","Go 프레임워크","WebSocket","실시간 업데이트","채팅 기능","코드 생성","인증과 인가","ORM"],"es":["monolith-websocket-pubsub","framework de Go","aplicaciones web full stack","pub/sub","WebSocket","generación de código","autenticación","ORM","despliegues"],"fr":["monolith-websocket-pubsub","framework Go","applications web full stack","pub/sub","WebSocket","génération de code","authentification","ORM","déploiements"],"de":["monolith-websocket-pubsub","Go-Framework","Full-Stack-Webanwendungen","Pub/Sub","WebSocket","Codegenerierung","Authentifizierung","ORM","Bereitstellungen"],"pt":["monolith-websocket-pubsub","framework Go","aplicativos web full stack","code generation","autenticação","pub/sub via web sockets","ORM gorm","filas de trabalhos"],"ru":["monolith-websocket-pubsub","фреймворк Go","веб-приложения","поддержка кода","аутентификация","pub/sub через веб-сокеты","ORM gorm","очереди заданий","ИИ Агенты"],"ar":["monolith-websocket-pubsub","إطار عمل Go","تطبيقات الويب الكاملة","توليد الكود","التحقق","النشر/الاشتراك عبر сокيتات الويب","نظام إدارة قواعد البيانات","الوظائف","الأجهزة الاصطناعية"]}},"owner":"cggonzal","repo":"monolith","repoPath":"cggonzal/monolith","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.583Z","topics":[],"category":"community","skillMd":{"name":"monolith-websocket-pubsub","description":"Use when implementing real-time functionality using the built-in websocket pub/sub layer (`/ws`), including subscribe/message protocol and channel design.","bodyPreview":"# Monolith WebSocket Pub/Sub\n\n## Use this skill when\n- Building chat/live updates.\n- Debugging channel subscriptions or message broadcast behavior.\n\n## Entry points\n- Route: `GET /ws` in `app/routes/routes.go`\n- Implementation: `ws/ws.go`\n- Persistent message model: `app/models/ws.go`\n\n## Client protocol\nSend JSON commands:\n- Subscribe: `{\"command\":\"subscribe\",\"identifier\":\"ChatChannel\"}`\n- Publish: `{\"command\":\"message\",\"identifier\":\"ChatChannel\",\"data\":\"Hello\"}`\n\n## Server behavior\n- Hub track","body":"# Monolith WebSocket Pub/Sub\n\n## Use this skill when\n- Building chat/live updates.\n- Debugging channel subscriptions or message broadcast behavior.\n\n## Entry points\n- Route: `GET /ws` in `app/routes/routes.go`\n- Implementation: `ws/ws.go`\n- Persistent message model: `app/models/ws.go`\n\n## Client protocol\nSend JSON commands:\n- Subscribe: `{\"command\":\"subscribe\",\"identifier\":\"ChatChannel\"}`\n- Publish: `{\"command\":\"message\",\"identifier\":\"ChatChannel\",\"data\":\"Hello\"}`\n\n## Server behavior\n- Hub tracks channel subscriptions.\n- `message` commands are persisted then broadcast to subscribed clients.\n- Client loop handles register/unregister and ping/pong lifecycle.\n\n## Extension workflow\n1. Pick channel naming strategy (room, user, domain event).\n2. Add frontend websocket client logic in `static/js/application.js` or app-specific JS.\n3. Optionally enforce auth checks before allowing subscribe/publish.\n4. Add tests in `ws/ws_test.go` style for command handling.\n"},"lastSynced":"2026-03-08T02:11:55.353Z","agentAnalysis":{"suitability":{"en":"Ideal for Real-Time Agents needing WebSocket pub/sub capabilities for building full-stack web apps.","zh":"适用于需要 WebSocket 发布/订阅功能以构建全栈 Web 应用的实时代理。","ja":"リアルタイムエージェントが WebSocket の pub/sub 機能を使用してフルスタック Web アプリを構築するのに適しています。","ko":"WebSocket 발행/구독 기능을 사용하여 전체 스택 웹 애플리케이션을 구축하는 실시간 에이전트에 적합합니다.","es":"Ideal para Agentes en Tiempo Real que necesitan capacidades de publicación/suscripción de WebSocket para construir aplicaciones web de pilas completas.","fr":"Idéal pour les agents en temps réel ayant besoin de capacités de publication/abonnement WebSocket pour construire des applications web full-stack.","de":"Ideal für Echtzeit-Agents, die WebSocket-Veröffentlichungs-/Abonnementsfunktionen für den Bau von Full-Stack-Web-Anwendungen benötigen.","pt":"Ideal para Agentes em Tempo Real que necessitam de capacidades de pub/sub WebSocket para construir aplicativos web full-stack.","ru":"Идеально для агентов реального времени, которым необходимы возможности WebSocket pub/sub для построения полноценных веб-приложений.","ar":"مثالي للوكلاء في وقت واحد الذين يحتاجون إلى قدرات WebSocket pub/sub لبناء تطبيقات الويب الكاملة"},"recommendation":{"en":"Empowers agents to establish real-time communication using WebSocket protocol, supporting JSON commands for subscribe and publish operations, and enabling features like chat and live updates through built-in pub/sub functionality.","zh":"使代理能够使用 WebSocket 协议建立实时通信，支持 JSON 命令用于订阅和发布操作，并通过内置的 pub/sub 功能启用聊天和实时更新等功能。","ja":"エージェントが WebSocket プロトコルを使用してリアルタイム通信を確立できるようにし、JSON コマンドを使用してサブスクライブおよびパブリッシュ操作をサポートし、チャットやリアルタイム更新などの機能をビルトインの pub/sub 機能を介して有効にします。","ko":"에이전트가 WebSocket 프로토콜을 사용하여 실시간 통신을 설정할 수 있도록 하며 JSON 명령을 사용하여 구독 및 발행操作을 지원하며 내장된 발행/구독 기능을 통해 채팅 및 실시간 업데이트와 같은 기능을 활성화합니다.","es":"Habilita a los agentes a establecer comunicaciones en tiempo real utilizando el protocolo WebSocket, que admite comandos JSON para operaciones de suscripción y publicación, y que permite características como chat y actualizaciones en vivo a través de la funcionalidad de publicación/suscripción integrada.","fr":"Permet aux agents d''établir des communications en temps réel en utilisant le protocole WebSocket, qui prend en charge les commandes JSON pour les opérations d''abonnement et de publication, et qui permet des fonctionnalités telles que le chat et les mises à jour en temps réel grâce à la fonctionnalité d''abonnement/pub intégrée.","de":"Ermächtigt die Agents, Echtzeitkommunikation mit dem WebSocket-Protokoll herzustellen, das JSON-Befehle für Abonnieren- und Veröffentlichen-Operationen unterstützt und Funktionen wie Chat und Live-Updates durch die integrierte Pub/Sub-Funktionalität ermöglicht.","pt":"Habilita os agentes a estabelecer comunicação em tempo real usando o protocolo WebSocket, suportando comandos JSON para operações de inscrição e publicação, e habilitando recursos como chat e atualizações em tempo real por meio da funcionalidade de pub/sub incorporada.","ru":"Позволяет агентам устанавливать связь в реальном времени с использованием протокола WebSocket, поддерживая JSON-команды для операций подписки и публикации, и предоставляя функции, такие как чат и обновления в реальном времени посредством встроенной функциональности pub/sub.","ar":"تمكين الوكلاء من建立 اتصال في الوقت الحقيقي باستخدام بروتوكول WebSocket ، ودعم أوامر JSON للعمليات المشتركة والنشر ، وتقديم ميزات مثل الدردشة وتحديثات الوقت الحقيقي من خلال وظيفة pub/sub المدمجة"},"useCases":{"en":["Building chat applications with real-time updates","Debugging channel subscriptions or message broadcast behavior","Implementing live update features in web applications"],"zh":["构建具有实时更新的聊天应用程序","调试频道订阅或消息广播行为","在 Web 应用程序中实现实时更新功能"],"ja":["リアルタイム更新を備えたチャットアプリケーションを構築する","チャンネルサブスクリプションまたはメッセージブロードキャスト動作をデバッグする","Webアプリケーションにリアルタイム更新機能を実装する"],"ko":["실시간 업데이트가 있는 채팅 애플리케이션을 구축하는 것","채널 구독 또는 메시지 방송 동작을 디버깅하는 것","웹 애플리케이션에 실시간 업데이트 기능을 구현하는 것"],"es":["Construir aplicaciones de chat con actualizaciones en tiempo real","Depurar el comportamiento de suscripción de canales o difusión de mensajes","Implementar características de actualización en vivo en aplicaciones web"],"fr":["Construire des applications de chat avec des mises à jour en temps réel","Déboguer le comportement d''abonnement de canaux ou de diffusion de messages","Mettre en œuvre des fonctionnalités de mise à jour en temps réel dans les applications web"],"de":["Erstellen von Chat-Anwendungen mit Echtzeit-Updates","Debuggen des Abonnieren-Verhaltens von Kanälen oder Nachrichten-Übertragungsverhaltens","Implementieren von Live-Update-Funktionen in Web-Anwendungen"],"pt":["Construir aplicativos de chat com atualizações em tempo real","Depurar assinaturas de canal ou comportamento de transmissão de mensagens","Implementar recursos de atualização em tempo real em aplicações web"],"ru":["Построение приложений чата с обновлениями в реальном времени","Отладка подписок на каналы или поведения при передаче сообщений","Реализация функций обновления в реальном времени в веб-приложениях"],"ar":["بناء تطبيقات الدردشة مع تحديثات في الوقت الحقيقي","تصحيح أخطاء في اشتراكات القناة أو سلوك بث الرسائل","تنفيذ ميزات التحديث في الوقت الحقيقي في تطبيقات الويب"]},"limitations":{"en":["Requires Go framework knowledge","Dependent on WebSocket protocol support"],"zh":["需要 Go 框架知识","依赖于 WebSocket 协议支持"],"ja":["Go フレームワークの知識が必要","WebSocket プロトコルのサポートに依存"],"ko":["Go 프레임워크 지식이 필요함","WebSocket 프로토콜 지원에 의존"],"es":["Requiere conocimiento del framework Go","Dependiente del soporte del protocolo WebSocket"],"fr":["Nécessite des connaissances du framework Go","Dépend du support du protocole WebSocket"],"de":["Benötigt Kenntnisse des Go-Frameworks","Abhängig von der Unterstützung des WebSocket-Protokolls"],"pt":["Requer conhecimento do framework Go","Dependente do suporte ao protocolo WebSocket"],"ru":["Требует знания фреймворка Go","Зависит от поддержки протокола WebSocket"],"ar":["يتطلب معرفة إطار العمل Go","يعتمد على دعم بروتوكول WebSocket"]},"version":4},"contentHash":"43f2fd627b5158f47587208d1600798762d12f6ab1a53d12f384c63c4ee4a68f","qualityScore":23}');
