INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('cggonzal/monolith/monolith-websocket-pubsub', 'monolith-websocket-pubsub', 'cggonzal', 'monolith', 'community', 'monolith-websocket-pubsub cggonzal monolith community monolith-websocket-pubsub is a Go framework for building full-stack web apps with built-in support for WebSocket pub/sub. It benefits developers building real-time applications. monolith-websocket-pubsub 是一个 Go 框架，用于构建全栈 Web 应用，具有代码生成、认证、ORM 和 WebSocket 支持等功能 monolith-websocket-pubsub は、Go で構築されたフルスタック Web アプリケーションのフレームワークで、コード生成、認証、ORM、WebSocket などをサポートしています monolith-websocket-pubsub는 Go로 구축된 풀스택 웹 애플리케이션 프레임워크로 코드 생성, 인증, ORM, WebSocket 등을 지원합니다 Monolith-websocket-pubsub es un framework de Go para aplicaciones web full stack con soporte integrado para generación de código, autenticación, ORM y más Monolith-websocket-pubsub est un framework Go pour les applications web full stack avec prise en charge intégrée de la génération de code, de l''authentification, de l''ORM et plus Monolith-websocket-pubsub ist ein Go-Framework für Full-Stack-Webanwendungen mit integrierter Unterstützung für Codegenerierung, Authentifizierung, ORM und mehr O monolith-websocket-pubsub é um framework Go para aplicativos web full stack com recursos como code generation, autenticação e pub/sub via web sockets monolith-websocket-pubsub - это фреймворк Go для веб-приложений с поддержкой кода, аутентификации и pub/sub через веб-сокеты. ИИ Агенты monolith-websocket-pubsub هو إطار عمل Go لتطبيقات الويب الكاملة مع ميزات مثل توليد الكود والتحقق والنشر/الاشتراك عبر сокيتات الويب how to use monolith-websocket-pubsub monolith-websocket-pubsub alternative monolith-websocket-pubsub setup guide what is monolith-websocket-pubsub monolith-websocket-pubsub vs Rails monolith-websocket-pubsub install WebSocket pub/sub implementation Go framework for real-time updates monolith-websocket-pubsub documentation monolith-websocket-pubsub Go 框架 WebSocket 实时更新 聊天功能 代码生成 认证和授权 ORM Supports WebSocket pub/sub via JSON commands Includes implementation in ws/ws.go for server behavior Uses persistent message model in app/models/ws.go Allows subscription and publishing via GET /ws route Sends JSON commands for subscribe and publish actions Tracks hub subscriptions for efficient message broadcasting monolith-websocket-pubsub is a Go framework providing built-in support for code generation, authentication, and WebSocket pub/sub for real-time updates.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('mvappshub/chalange/observability-guidelines', 'community', 'mvappshub', 'chalange', 'mvappshub/chalange', 'observability-guidelines', 0, 0, 23, '2026-03-08T01:57:15.585Z', '2026-03-08T02:11:55.787Z', 'e881dc3c43bd16dc6208cec78455e94df2290d3bcc229293568d77a2998100cb', '{"id":"mvappshub/chalange/observability-guidelines","name":"observability-guidelines","description":{"en":"The observability-guidelines skill ensures comprehensive visibility into distributed systems and microservices by applying core observability principles and integrating OpenTelemetry. This benefits developers working with complex systems.","zh":"可观测性指南提供了确保分布式系统和微服务全面可见性的原则，包括使用 OpenTelemetry 和 Clean Architecture","ja":"可観測性ガイドは、分散システムとマイクロサービスの全面的な可視性を確保するための原則を提供します。OpenTelemetry と Clean Architecture を使用します","ko":"관측 가능성 가이드는 분산 시스템과 마이크로 서비스의 전체적인 가시성을 확보하는 원칙을 제공합니다. OpenTelemetry와 Clean Architecture를 사용합니다","es":"Aplica principios de observabilidad para obtener visibilidad completa en sistemas distribuidos y microservices","fr":"Assurez-vous une visibilité complète dans les systèmes distribués et les microservices avec les principes d''observabilité","de":"Wenden Sie Observability-Prinzipien an, um umfassende Sichtbarkeit in verteilten Systemen und Microservices zu erhalten","pt":"As diretrizes de observabilidade fornecem princípios para desenvolver código com visibilidade integrada, modular e de alto desempenho com OpenTelemetry","ru":"Руководство по наблюдаемости предлагает принципы для разработки кода с встроенной наблюдаемостью, модульной конструкции и высокой производительностью с OpenTelemetry","ar":"إرشادات المراقبة توفر مبادئ لتطوير رمز مع رؤية مدمجة وتصميم موديولار وعالية الأداء مع OpenTelemetry"},"seo":{"title":{"en":"Observability-Guidelines: Best Practices for Distributed ...","zh":"可观测性指南 Setup Guide - AIエージェント开发最佳实践","