INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('akihiro4321/favefit/ai-module-dev', 'ai-module-dev', 'akihiro4321', 'favefit', 'community', 'ai-module-dev akihiro4321 favefit community The ai-module-dev skill supports the development and modification of FaveFit''s AI features, including Agents, Functions, and Workflows. It provides a structured approach to AI system development. AI模块开发是FaveFit的AI功能开发和修正的支持工具，包括agents、functions、workflows、prompts和types的开发 AIモジュール開発は、FaveFitのAI機能（Agent、Function、Workflow）の開発と修正を支援するスキルです AI 모듈 개발은 FaveFit의 AI 기능开发과 수정을 지원하는 도구입니다 AI Module Dev es un conjunto de herramientas para desarrollar y mejorar los módulos de inteligencia artificial de FaveFit. Permite la creación de nuevos módulos y la modificación de la lógica existente. AI Module Dev est un ensemble d''outils pour développer et améliorer les modules d''intelligence artificielle de FaveFit. Il permet la création de nouveaux modules et la modification de la logique existante. AI-Module-Entwicklung ist eine Sammlung von Tools zur Entwicklung und Verbesserung der KI-Module von FaveFit. Sie ermöglicht die Erstellung neuer Module und die Änderung der bestehenden Logik. O ai-module-dev é um skill para desenvolvedores que visa apoiar a criação e modificação de funcionalidades de IA na plataforma FaveFit. ИИ Агенты с ai-module-dev - это навык для разработчиков, предназначенный для поддержки создания и изменения функций ИИ на платформе FaveFit. الوكلاء الذكاء الاصطناعي مع ai-module-dev هو مهارة للعاملين في مجال التطوير لدعم إنشاء وتعديل وظائف الذكاء الاصطناعي على منصة FaveFit. how to use ai-module-dev ai-module-dev setup guide ai-module-dev alternative ai-module-dev vs FaveFit AI ai-module-dev install what is ai-module-dev ai-module-dev development best practices ai-module-dev workflow creation ai-module-dev agent development AI模块开发 FaveFit AI功能 AIエージェント开发 AI模块开发工具 AI开发最佳实践 AI模块开发setup guide Follows a 3-layer architecture defined in references/architecture.md Supports creation of new modules and modification of existing logic in src/server/ai/ Utilizes a directory structure with agents/, functions/, workflows/, prompts/, and types/ subdirectories Enforces basic rules and references for AI-related development Includes type definitions for AI-related components in types/ Orchestrates Service layer interactions through workflows/ ai-module-dev is a skill that assists in the development and modification of FaveFit''s AI functionality, following a design that prioritizes separation of concerns and scalability.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('damacus/home-ops/failing-deployments', 'community', 'damacus', 'home-ops', 'damacus/home-ops', 'failing-deployments', 0, 0, 23, '2026-03-08T01:57:15.612Z', '2026-03-08T02:13:13.645Z', '2241dc286efc0b531ba87208841e619986a7c3668bd9cabd73bcf8830b905db2', '{"id":"damacus/home-ops/failing-deployments","name":"failing-deployments","description":{"en":"The failing-deployments skill provides a structured workflow for investigating and reporting on failing deployments within Kubernetes clusters, benefiting DevOps teams and developers.","zh":"故障部署AIエージェント提供结构化工作流程，用于调查和报告Kubernetes集群中的故障部署","ja":"デプロイ障害AIエージェントは、Kubernetesクラスター内のデプロイ障害を調査して報告するための構造化されたワークフローを提供します","ko":"실패한 배포 AI 에이전트는 Kubernetes 클러스터에서 실패한 배포를 조사하고 보고하는 구조화된 워크플로를 제공합니다","es":"Esta habilidad proporciona un flujo de trabajo estructurado para investigar y reportar deploy fallidos en el clúster de Kubernetes.","fr":"Cette compétence fournit un flux de travail structuré pour enquêter et signaler les déploiements échoués dans le cluster Kubernetes.","de":"Diese Fähigkeit bietet einen strukturierten Workflow, um fehlgeschlagene Deployments im Kubernetes-Cluster zu untersuchen und zu melden.","pt":"O agente de failing deployments fornece um fluxo de trabalho estruturado para investigar e relatar falhas de implantação no cluster Kubernetes.","ru":"Агент failing deployments предоставляет структурированный рабочий процесс для расследования и сообщения о неудачах развертывания в кластере Kubernetes.","ar":"عامل فشل النشر يوفر تدفق عمل منظم لتحقيق وتبليغ فشل النشر في кластер Kubernetes."},"seo":{"title":{"en":"Failing-Deployments: Kubernetes Troubleshooting Setup Gui...","zh":"故障部署故障排除指南 - AIエージェント","ja":"デプロイ障害対策ガイド - AIエージェント","ko":"실패한 배포 문제 해결 가이드 - AI 에이전트","es":"Guía de Configuración para Deploys Fallidos con Kubernetes","fr":"Déploiements échoués : Guide de configuration pour Kubern...","de":"Fehlgeschlagene Deployments: Einrichtungsleitfaden für Ku...","pt":"Guia de Configuração para Failing Deployments: Kubernetes...","ru":"Настройка ИИ Агентов для Failing Deployments: Руководство...","ar":"دليل إعداد فشل النشر: إصدار Kubernetes Cluster Home"},"description":{"en":"Discover how to identify and report failing deployments in your Kubernetes cluster with this AI agent skill - get started now and optimize your workflow!","zh":"使用故障部署AIエージェント排除Kubernetes集群故障，提高部署成功率","ja":"デプロイ障害を解決するAIエージェントを使用してKubernetesクラスターの信頼性を高める","ko":"실패한 배포 AI 에이전트를 사용하여 Kubernetes 클러스터의 안정성을 높이십시오","es":"Identifique y resuelva problemas de deploy fallidos en su clúster de Kubernetes con nuestra guía de configuración","fr":"Identifiez et résolvez les problèmes de déploiement échoués dans votre cluster Kubernetes avec notre guide de configuration","de":"Ermitteln und beheben Sie Probleme mit fehlgeschlagenen Deployments in Ihrem Kubernetes-Cluster mit unserem Einrichtungsleitfaden","pt":"Aprenda a identificar e relatar falhas de implantação no cluster Kubernetes com o agente de failing deployments. Obtenha dicas práticas e comandos CLI para m...","ru":"Узнайте, как выявлять и сообщать о неудачах развертывания в кластере Kubernetes с помощью агента failing deployments. Получите практические советы и команды ...","ar":"تعرف على كيفية تحديد ومعالجة فشل النشر في кластер Kubernetes باستخدام عامل فشل النشر. احصل على نصائح عملية وأوامر CLI لتحسين استقرار клаسترك."},"definition":{"en":"Failing-deployments is a Kubernetes troubleshooting skill that identifies failing pods and HelmReleases, providing insights into cluster health and deployment issues.","zh":"故障部署AIエージェント是一种用于调查和报告Kubernetes集群中故障部署的工具","ja":"デプロイ障害AIエージェントは、Kubernetesクラスター内のデプロイ障害を調査して報告するためのツールです","ko":"실패한 배포 AI 에이전트는 Kubernetes 클러스터에서 실패한 배포를 조사하고 보고하는 도구입니다","es":"Un agente de deploy fallido es una herramienta que ayuda a identificar y solucionar problemas de deploy en un clúster de Kubernetes","fr":"Un agent de déploiement échoué est un outil qui aide à identifier et à résoudre les problèmes de déploiement dans un cluster Kubernetes","de":"Ein Agent für fehlgeschlagene Deployments ist ein Tool, das dabei hilft, Probleme mit Deployments in einem Kubernetes-Cluster zu identifizieren und zu beheben","pt":"O que é um agente de failing deployments? É uma ferramenta que ajuda a identificar e relatar falhas de implantação no cluster Kubernetes.","ru":"Что такое агент failing deployments? Это инструмент, который помогает выявлять и сообщать о неудачах развертывания в кластере Kubernetes.","ar":"ما هو عامل فشل النشر؟ هو أداة تساعد في تحديد ومعالجة فشل النشر في кластер Kubernetes."},"features":{"en":["Identifies failing pods across all namespaces using `kubectl get pods` command","Checks Flux HelmReleases for failures or stalled states with `flux get helmreleases`","Provides a structured workflow for investigating deployment issues","Supports Kubernetes Cluster Home Edition","Utilizes `grep` for filtering and parsing pod and HelmRelease data","Enables reporting on failing deployments for optimized cluster management"],"zh":["识别Kubernetes集群中未运行或未完成的Pod","检查Flux HelmReleases中的故障或停滞状态","使用kubectl和grep命令调查故障部署","支持多个命名空间和HelmRelease"],"ja":["Kubernetesクラスター内の未実行または未完了のPodを識別する","Flux HelmReleases内の障害または停滞状態をチェックする","kubectlとgrepコマンドを使用してデプロイ障害を調査する","複数の名前空間とHelmReleaseをサポートする"],"ko":["Kubernetes 클러스터에서 실행되지 않은 또는 완료되지 않은 Pod를 식별","Flux HelmReleases에서 故障 또는 정체 상태를 확인","kubectl 및 grep 명령을 사용하여 배포 오류를 조사","複数의 네임스페이스와 HelmRelease를 지원"],"es":["Identificar pods con errores en todos los namespaces","Verificar HelmReleases para fallos o estados bloqueados","Uso de comandos kubectl para obtener información","Integración con Flux para HelmReleases","Soporte para clústeres de Kubernetes"],"fr":["Identifier les pods avec des erreurs dans tous les namespaces","Vérifier les HelmReleases pour les échecs ou les états bloqués","Utilisation de commandes kubectl pour obtenir des informations","Intégration avec Flux pour les HelmReleases","Prise en charge des clusters Kubernetes"],"de":["Identifizierung von Pods mit Fehlern in allen Namespaces","Überprüfung von HelmReleases auf Fehler oder blockierte Zustände","Verwendung von kubectl-Befehlen zur Informationsbeschaffung","Integration mit Flux für HelmReleases","Unterstützung für Kubernetes-Cluster"],"pt":["Identificação de pods com falha","Verificação de HelmReleases com falha ou estado parado","Uso de comandos CLI como `kubectl get pods` e `flux get helmreleases`","Suporte ao cluster Kubernetes","Fluxo de trabalho estruturado para investigar e relatar falhas"],"ru":["Определение подов с неудачами","Проверка HelmReleases на неудачи или остановленное состояние","Использование команд CLI, таких как `kubectl get pods` и `flux get helmreleases`","Поддержка кластера Kubernetes","Структурированный рабочий процесс для расследования и сообщения о неудачах"],"ar":["تحديد pods مع فشل","فحص HelmReleases مع فشل أو حالة متوقفة","استخدام أوامر CLI مثل `kubectl get pods` و `flux get helmreleases`","دعم клаستر Kubernetes","تدفق عمل منظم لتحقيق وتبليغ فشل النشر"]},"keywords":{"en":["how to use failing-deployments","kubernetes deployment troubleshooting","failing-deployments alternative","failing-deployments vs kubectl","failing-deployments install","failing-deployments setup guide","kubernetes cluster health check","helmrelease failure detection"],"zh":["Kubernetes故障部署","AIエージェント","故障排除","kubectl","grep","Flux HelmReleases","多个命名空间","HelmRelease"],"ja":["Kubernetesデプロイ障害","AIエージェント","障害対策","kubectl","grep","Flux HelmReleases","複数の名前空間","HelmRelease"],"ko":["Kubernetes 배포 오류","AI 에이전트","오류 해결","kubectl","grep","Flux HelmReleases","複数의 네임스페이스","HelmRelease"],"es":["deploy fallido","kubernetes","flux","helm releases","kubectl","agente de deploy","herramientas de deploy","clúster de kubernetes","solución de problemas de deploy"],"fr":["déploiement échoué","kubernetes","flux","helm releases","kubectl","agent de déploiement","outils de déploiement","cluster kubernetes","résolution de problèmes de déploiement"],"de":["fehlgeschlagene deployment","kubernetes","flux","helm releases","kubectl","agent für deployment","tools für deployment","kubernetes-cluster","fehlerbehebung bei deployment"],"pt":["failing deployments","Kubernetes cluster","agente de failing deployments","implantação de software","cluster de contêineres","Kubernetes Home Edition","falhas de implantação","comandos CLI","flux get helmreleases"],"ru":["failing deployments","Кластер Kubernetes","ИИ Агенты для failing deployments","Развертывание программного обеспечения","Кластер контейнеров","Кластер Kubernetes Home Edition","Неудачи развертывания","Команды CLI","flux get helmreleases"],"ar":["فشل النشر","كلاستر Kubernetes","عامل فشل النشر","نشر البرمجيات","كلاستر الحاويات","كلاستر Kubernetes Home Edition","فشل النشر","أوامر CLI","flux get helmreleases"]}},"owner":"damacus","repo":"home-ops","repoPath":"damacus/home-ops","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.612Z","topics":[],"category":"community","skillMd":{"name":"failing-deployments","description":"Investigates failing Kubernetes pods and Flux HelmReleases to identify root causes of deployment issues in the home-ops cluster.","bodyPreview":"# Failing Deployments Agent\n\nThis skill provides a structured workflow for investigating and reporting on failing deployments within the Kubernetes cluster.\n\n## Workflow\n\n### 1. Identify Failing Pods\nList all pods across all namespaces that are NOT in `Running` or `Completed` states.\n- Command: `kubectl get pods -A | grep -v -E \"Running|Completed|NAME\"`\n\n### 2. Identify Failing HelmReleases\nCheck Flux HelmReleases for failures or stalled states.\n- Command: `flux get helmreleases -A | grep -v -E","body":"# Failing Deployments Agent\n\nThis skill provides a structured workflow for investigating and reporting on failing deployments within the Kubernetes cluster.\n\n## Workflow\n\n### 1. Identify Failing Pods\nList all pods across all namespaces that are NOT in `Running` or `Completed` states.\n- Command: `kubectl get pods -A | grep -v -E \"Running|Completed|NAME\"`\n\n### 2. Identify Failing HelmReleases\nCheck Flux HelmReleases for failures or stalled states.\n- Command: `flux get helmreleases -A | grep -v -E \"True|NAME\"`\n\n### 3. Deep Dive into Failures\nFor each failing resource identified:\n- **Pods**:\n    - Describe the pod: `kubectl describe pod <pod_name> -n <namespace>`\n    - Check recent logs: `kubectl logs <pod_name> -n <namespace> --tail=50 --all-containers`\n    - Look for events: `kubectl get events -n <namespace> --field-selector involvedObject.name=<pod_name>`\n- **HelmReleases**:\n    - Describe the release: `kubectl describe helmrelease <release_name> -n <namespace>`\n    - Check the associated Kustomization or Source if applicable.\n\n### 4. Report Findings\nConsolidate the information and report back to the main thread with:\n- Resource Name and Namespace.\n- Current Status.\n- Error message or Reason for failure (from `describe`).\n- Relevant log snippets that pinpoint the issue.\n- Potential fix or next steps."},"lastSynced":"2026-03-08T02:13:13.645Z","agentAnalysis":{"suitability":{"en":"Perfect for Kubernetes Agents needing automated deployment failure analysis and reporting.","zh":"适用于需要自动化部署失败分析和报告的Kubernetes Agents。","ja":"Kubernetes Agentが自動化されたデプロイメントの障害分析とレポートが必要な場合に適しています。","ko":"자동화된 배포 실패 분석 및 보고가 필요한 Kubernetes 에이전트에 적합합니다.","es":"Perfecto para agentes de Kubernetes que necesitan un análisis y un informe de fallos de implementación automatizados.","fr":"Parfait pour les agents Kubernetes nécessitant une analyse et un rapport de défaillance de déploiement automatisés.","de":"Perfekt für Kubernetes-Agents, die eine automatisierte Analyse und Berichterstellung über Deploy-Fehler benötigen.","pt":"Perfeito para Agents Kubernetes que precisam de análise e relatórios de falhas de implantação automatizados.","ru":"Идеально подходит для агентов Kubernetes, которым необходимы автоматизированный анализ и отчетность о сбоях в развертывании.","ar":"مثالي للوكلاء كوبرنيتس الذين يحتاجون إلى تحليل و تقارير فشل التثبيت الآلي."},"recommendation":{"en":"Empowers agents to investigate and report on failing deployments within Kubernetes clusters using kubectl commands and Flux HelmReleases, streamlining DevOps workflows and enhancing cluster reliability.","zh":"赋予代理调查和报告Kubernetes集群中失败的部署的能力，使用kubectl命令和Flux HelmReleases，简化DevOps工作流程，提高集群可靠性。","ja":"エージェントにKubernetesクラスター内で失敗したデプロイメントを調査し、レポートする能力を付与することで、kubectlコマンドとFlux HelmReleasesを使用してDevOpsワークフローをストリーミングし、クラスターの信頼性を高めます。","ko":"에이전트가 kubectl 명령과 Flux HelmReleases를 사용하여 Kubernetes 클러스터 내에서 실패한 배포를 조사하고 보고하는 능력을 부여하여 DevOps 작업을 간소화하고 클러스터의 신뢰성을 향상합니다.","es":"Habilita a los agentes a investigar y informar sobre implementaciones con fallos dentro de los clusters de Kubernetes utilizando comandos kubectl y Flux HelmReleases, lo que simplifica los flujos de trabajo de DevOps y mejora la confiabilidad del clúster.","fr":"Permet aux agents d''enquêter et de signaler les déploiements défaillants au sein des clusters Kubernetes en utilisant des commandes kubectl et Flux HelmReleases, ce qui rationalise les flux de travail DevOps et améliore la fiabilité du cluster.","de":"Ermächtigt Agents, um Deploy-Fehler innerhalb von Kubernetes-Clustern mit kubectl-Befehlen und Flux HelmReleases zu untersuchen und zu melden, wodurch DevOps-Workflows gestreamt und die Cluster-Zuverlässigkeit verbessert werden.","pt":"Concede aos agentes a capacidade de investigar e relatar sobre implantações com falha dentro de clusters Kubernetes usando comandos kubectl e Flux HelmReleases, simplificando fluxos de trabalho DevOps e melhorando a confiabilidade do cluster.","ru":"Наделяет агентов возможностью расследовать и сообщать о сбоях в развертывании внутри кластеров Kubernetes с помощью команд kubectl и Flux HelmReleases, оптимизируя рабочие процессы DevOps и повышая надежность кластера.","ar":"يمنح الوكلاء القدرة على التحقيق و الإبلاغ عن فشل التثبيت داخل مجموعات كوبرنيتس باستخدام أوامر kubectl و Flux HelmReleases، و تحسين تدفقات عمل DevOps و تعزيز موثوقية المجموعة."},"useCases":{"en":["Identifying failing pods across all namespaces","Debugging stalled or failed HelmReleases","Automating deployment failure reporting for DevOps teams"],"zh":["跨所有命名空间识别失败的pod","调试停滞或失败的HelmReleases","为DevOps团队自动化部署失败报告"],"ja":["すべての名前空間を横断して障害が発生しているポッドを特定する","停止または失敗したHelmReleasesのデバッグ","DevOpsチームのデプロイメント障害レポートの自動化"],"ko":["모든 네임스페이스에서 실패한 pod를 식별하는 것","중단되거나 실패한 HelmReleases를 디버깅하는 것","DevOps 팀을 위한 배포 실패 보고서의 자동화"],"es":["Identificar pods con fallos en todos los espacios de nombres","Depurar HelmReleases detenidos o fallidos","Automatizar el informe de fallos de implementación para equipos de DevOps"],"fr":["Identifier les pods défaillants dans tous les espaces de noms","Déboguer les HelmReleases bloqués ou défaillants","Automatiser le signalement des défaillances de déploiement pour les équipes DevOps"],"de":["Fehlgeschlagene Pods in allen Namespaces identifizieren","Gestoppte oder fehlgeschlagene HelmReleases debuggen","Automatisieren des Deploy-Fehlerberichts für DevOps-Teams"],"pt":["Identificar pods com falha em todos os namespaces","Depurar HelmReleases travados ou com falha","Automatizar a criação de relatórios de falha de implantação para equipes DevOps"],"ru":["Определение неудачных pods во всех namespace","Отладка зависших или неудачных HelmReleases","Автоматизация создания отчетов о сбоях в развертывании для команд DevOps"],"ar":["تحديد pods الفاشلة في جميع Namespaces","تصحيح الأخطاء في HelmReleases المتوقفة أو الفاشلة","تأتمة إنشاء تقارير فشل التثبيت لفريق DevOps"]},"limitations":{"en":["Requires kubectl access to Kubernetes cluster","Limited to Flux HelmReleases for release management","Dependent on grep and command-line tools for data processing"],"zh":["需要kubectl访问Kubernetes集群","仅限于Flux HelmReleases进行版本管理","依赖grep和命令行工具进行数据处理"],"ja":["Kubernetesクラスターへのkubectlアクセスが必要","リリース管理にはFlux HelmReleasesのみがサポートされる","データ処理にはgrepおよびコマンドラインツールに依存する"],"ko":["Kubernetes 클러스터에 대한 kubectl 액세스가 필요함","릴리즈 관리는 Flux HelmReleases에만 제한됨","데이터 처리는 grep 및 명령줄 도구에 의존함"],"es":["Requiere acceso kubectl al clúster de Kubernetes","Limitado a Flux HelmReleases para la administración de versiones","Dependiente de grep y herramientas de línea de comandos para el procesamiento de datos"],"fr":["Nécessite un accès kubectl au cluster Kubernetes","Limité à Flux HelmReleases pour la gestion des versions","Dépendant de grep et d''outils de ligne de commande pour le traitement des données"],"de":["Benötigt kubectl-Zugriff auf den Kubernetes-Cluster","Begrenzt auf Flux HelmReleases für die Versionverwaltung","Abhängig von grep und Kommandozeilen-Tools für die Datenverarbeitung"],"pt":["Requer acesso kubectl ao cluster Kubernetes","Limitado a Flux HelmReleases para gerenciamento de lançamento","Dependente de grep e ferramentas de linha de comando para processamento de dados"],"ru":["Требуется доступ kubectl к кластеру Kubernetes","Ограничен до Flux HelmReleases для управления выпусками","Зависит от grep и инструментов командной строки для обработки данных"],"ar":["يتطلب الوصول إلى كوبرنيتس كلاستر عبر kubectl","محدود ب Flux HelmReleases لإدارة الإصدار","يعتمد على grep وأدوات سطر الأوامر لمعالجة البيانات"]},"version":4},"contentHash":"2241dc286efc0b531ba87208841e619986a7c3668bd9cabd73bcf8830b905db2","qualityScore":23}');
