INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('damacus/home-ops/failing-deployments', 'failing-deployments', 'damacus', 'home-ops', 'community', 'failing-deployments damacus home-ops community The failing-deployments skill provides a structured workflow for investigating and reporting on failing deployments within Kubernetes clusters, benefiting DevOps teams and developers. 故障部署AIエージェント提供结构化工作流程，用于调查和报告Kubernetes集群中的故障部署 デプロイ障害AIエージェントは、Kubernetesクラスター内のデプロイ障害を調査して報告するための構造化されたワークフローを提供します 실패한 배포 AI 에이전트는 Kubernetes 클러스터에서 실패한 배포를 조사하고 보고하는 구조화된 워크플로를 제공합니다 Esta habilidad proporciona un flujo de trabajo estructurado para investigar y reportar deploy fallidos en el clúster de Kubernetes. Cette compétence fournit un flux de travail structuré pour enquêter et signaler les déploiements échoués dans le cluster Kubernetes. Diese Fähigkeit bietet einen strukturierten Workflow, um fehlgeschlagene Deployments im Kubernetes-Cluster zu untersuchen und zu melden. O agente de failing deployments fornece um fluxo de trabalho estruturado para investigar e relatar falhas de implantação no cluster Kubernetes. Агент failing deployments предоставляет структурированный рабочий процесс для расследования и сообщения о неудачах развертывания в кластере Kubernetes. عامل فشل النشر يوفر تدفق عمل منظم لتحقيق وتبليغ فشل النشر في кластер Kubernetes. how to use failing-deployments kubernetes deployment troubleshooting failing-deployments alternative failing-deployments vs kubectl failing-deployments install failing-deployments setup guide kubernetes cluster health check helmrelease failure detection Kubernetes故障部署 AIエージェント 故障排除 kubectl grep Flux HelmReleases 多个命名空间 HelmRelease Identifies failing pods across all namespaces using `kubectl get pods` command Checks Flux HelmReleases for failures or stalled states with `flux get helmreleases` Provides a structured workflow for investigating deployment issues Supports Kubernetes Cluster Home Edition Utilizes `grep` for filtering and parsing pod and HelmRelease data Enables reporting on failing deployments for optimized cluster management Failing-deployments is a Kubernetes troubleshooting skill that identifies failing pods and HelmReleases, providing insights into cluster health and deployment issues.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('jakubpradzynski/przegladai.news/Clear links from query params', 'community', 'jakubpradzynski', 'przegladai.news', 'jakubpradzynski/przegladai.news', 'Clear links from query params', 0, 0, 23, '2026-03-08T01:57:15.613Z', '2026-03-08T02:13:17.109Z', '8d54ace3f7ea89b562085217eabda3f1c69c1ce3c4e843c946c90dc87b86fe76', '{"id":"jakubpradzynski/przegladai.news/Clear links from query params","name":"Clear links from query params","description":{"en":"The Clear links from query params skill removes unwanted query parameters from links, benefiting developers who need to clean URLs. It preserves link order and format.","zh":"本AIエージェント技能可以清除链接中的查询参数，优化链接格式，提高用户体验。","ja":"このAIエージェントのスキルはリンクからクエリパラメータを削除し、リンクのフォーマットを最適化します。","ko":"이 AI 도구는 링크에서 쿼리 파라미터를 제거하여 링크 형식을 최적화합니다.","es":"Elimina parámetros de consulta de enlaces como utm_source y utm_medium. Conserva el formato y la secuencia de los enlaces.","fr":"Supprimez les paramètres de requête des liens tels que utm_source et utm_medium. Conservez le format et la séquence des liens.","de":"Entfernen Sie Abfrageparameter aus Links wie utm_source und utm_medium. Bewahren Sie das Format und die Reihenfolge der Links.","pt":"Nossa ferramenta de IA limpa links de parâmetros de consulta, removendo utm_source, utm_medium e outros parâmetros indesejados.","ru":"Наш ИИ Агент очищает ссылки от параметров запроса, удаляя utm_source, utm_medium и другие нежелательные параметры.","ar":"أداة الذكاء الاصطناعي تزيل معلمات الاستعلام من الروابط، بإزالة utm_source و utm_medium وغيرها من المعلمات غير المرغوب فيها."},"seo":{"title":{"en":"Clear links from query params: Query Parameter Removal Se...","zh":"AIエージェント清除链接查询参数Setup Guide","ja":"クエリパラメータを削除するAIエージェントのベストプラクティス","ko":"링크 쿼리 파라미터를 지우는 AI 도구 설정 가이드","es":"Guía de configuración para eliminar parámetros de consult...","fr":"Paramètres de suppression des paramètres de requête des l...","de":"Leitfaden zur Entfernung von Abfrageparametern aus Links","pt":"Guia de Configuração: Limpeza de Links de Parâmetros de C...","ru":"Настройка ИИ Агентов: Очистка ссылок от параметров запроса","ar":"إعداد أداة الذكاء الاصطناعي: إزالة 매개 변수 الاستعلام من الر..."},"description":{"en":"Learn how to remove unwanted query parameters like utm_source and utm_medium from links with our Clear links from query params AI agent skill. Get started now!","zh":"了解如何使用AIエージェント清除链接查询参数，优化您的链接格式，提高用户体验","ja":"クエリパラメータを削除してリンクを最適化する方法を学ぶ","ko":"링크 쿼리 파라미터를 지워서 링크를 최적화하는 방법을 알아보세요","es":"Aprende a eliminar parámetros de consulta como utm_source y utm_medium de tus enlaces con nuestra herramienta de AI","fr":"Découvrez comment supprimer les paramètres de requête tels que utm_source et utm_medium de vos liens avec notre outil d''IA","de":"Erfahren Sie, wie Sie Abfrageparameter wie utm_source und utm_medium aus Ihren Links entfernen können, mit unserem AI-Tool","pt":"Aprenda a limpar links de parâmetros de consulta com nossa ferramenta de IA. Remova utm_source, utm_medium e outros parâmetros indesejados.","ru":"Узнайте, как очистить ссылки от параметров запроса с помощью нашего ИИ Агента. Удалите utm_source, utm_medium и другие нежелательные параметры.","ar":"تعرف على كيفية إزالة 매개 변수 الاستعلام من الروابط باستخدام أداة الذكاء الاصطناعي. قم بإزالة utm_source و utm_medium وغيرها من المعلمات غير المرغوب فيها."},"definition":{"en":"Clear links from query params is a skill that removes specific query parameters like utm_source and _bhlid from URLs, preserving the original link format and order.","zh":"清除链接查询参数是一种AIエージェント技能，用于优化链接格式","ja":"クエリパラメータの削除は、リンクのフォーマットを最適化するAIエージェントのスキルです","ko":"링크 쿼리 파라미터를 지우는 것은 링크 형식을 최적화하는 AI 도구의 기능입니다","es":"Herramienta de AI que elimina parámetros de consulta de enlaces","fr":"Outil d''IA qui supprime les paramètres de requête des liens","de":"AI-Tool, das Abfrageparameter aus Links entfernt","pt":"Limpeza de links de parâmetros de consulta é um processo de remoção de parâmetros indesejados de URLs.","ru":"Очистка ссылок от параметров запроса - это процесс удаления нежелательных параметров из URL-адресов.","ar":"إزالة معلمات الاستعلام من الروابط هي عملية إزالة معلمات غير مرغوب فيها من عناوين URL."},"features":{"en":["Removes query parameters like utm_source, utm_medium, and utm_campaign from links","Preserves link order and format, including fragments starting with #","Supports removal of additional query parameters like _bhlid, lid, and r","Writes cleaned links to a new file named cleaned_...","Maintains the original file format and structure"],"zh":["支持从链接中删除utm_source、utm_medium、utm_campaign等查询参数","保留链接的原始格式和顺序","支持在链接末尾保留#符号后的文本","优化链接格式，提高用户体验"],"ja":["utm_source、utm_medium、utm_campaignなどのクエリパラメータをリンクから削除する機能","リンクの元のフォーマットと順序を保つ","リンクの末尾に#記号が付いている場合、記号後のテキストを保つ","リンクのフォーマットを最適化してユーザーエクスペリエンスを向上させる"],"ko":["utm_source, utm_medium, utm_campaign 등 쿼리 파라미터를 링크에서 제거하는 기능","링크의 원래 형식과 순서를 유지","링크末尾의 # 기호 이후의 텍스트를 유지","링크 형식을 최적화하여 사용자 경험을 향상"],"es":["Eliminación de parámetros de consulta como utm_source y utm_medium","Conservación del formato y la secuencia de los enlaces","Compatibilidad con enlaces que contienen # y texto adicional","Eliminación de parámetros como _bhlid, lid, r, triedRedirect e IR"],"fr":["Suppression des paramètres de requête tels que utm_source et utm_medium","Conservation du format et de la séquence des liens","Compatibilité avec les liens qui contiennent # et du texte supplémentaire","Suppression des paramètres tels que _bhlid, lid, r, triedRedirect et IR"],"de":["Entfernung von Abfrageparametern wie utm_source und utm_medium","Bewahrung des Formats und der Reihenfolge der Links","Kompatibilität mit Links, die # und zusätzlichen Text enthalten","Entfernung von Parametern wie _bhlid, lid, r, triedRedirect und IR"],"pt":["Remoção de parâmetros utm_source, utm_medium e utm_campaign","Manutenção da ordem dos links","Preservação do formato do arquivo","Remoção de parâmetros _bhlid, lid, r, triedRedirect e IR"],"ru":["Удаление параметров utm_source, utm_medium и utm_campaign","Сохранение порядка ссылок","Сохранение формата файла","Удаление параметров _bhlid, lid, r, triedRedirect и IR"],"ar":["إزالة معلمات utm_source و utm_medium و utm_campaign","الحفاظ على ترتيب الروابط","الحفاظ على تنسيق الملف","إزالة معلمات _bhlid و lid و r و triedRedirect و IR"]},"keywords":{"en":["how to remove query parameters from links","Clear links from query params alternative","what is Clear links from query params","Clear links from query params setup guide","Clear links from query params vs URL cleaner","install Clear links from query params AI agent skill"],"zh":["AIエージェント","清除链接查询参数","链接优化","用户体验","utm_source","utm_medium","utm_campaign"],"ja":["AIエージェント","クエリパラメータの削除","リンクの最適化","ユーザーエクスペリエンス","utm_source","utm_medium","utm_campaign"],"ko":["AI 도구","링크 쿼리 파라미터를 지우는","링크 최적화","사용자 경험","utm_source","utm_medium","utm_campaign"],"es":["eliminar parámetros de consulta","herramienta de AI para enlaces","utm_source","utm_medium","parámetros de consulta","enlaces limpios","herramientas de desarrollo web"],"fr":["supprimer les paramètres de requête","outil d''IA pour les liens","utm_source","utm_medium","paramètres de requête","liens propres","outils de développement web"],"de":["Abfrageparameter entfernen","AI-Tool für Links","utm_source","utm_medium","Abfrageparameter","saubere Links","Webentwicklungstools"],"pt":["limpeza de links","parâmetros de consulta","utm_source","utm_medium","ferramenta de IA","otimização de URL","remoção de parâmetros indesejados"],"ru":["очистка ссылок","параметры запроса","utm_source","utm_medium","ИИ Агент","оптимизация URL","удаление нежелательных параметров"],"ar":["إزالة الروابط","معلمات الاستعلام","utm_source","utm_medium","أداة الذكاء الاصطناعي","تحسين URL","إزالة معلمات غير مرغوب فيها"]}},"owner":"jakubpradzynski","repo":"przegladai.news","repoPath":"jakubpradzynski/przegladai.news","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.613Z","topics":[],"category":"community","skillMd":{"name":"Clear links from query params","description":"Usuwa query parametry z linków w podanym pliku","bodyPreview":"# Kroki\n\n1. Wczytaj podany plik\n2. Usuń query parametry z linków\n3. Zapisz zmiany w pliku `cleaned_...`\n\n# Wytyczne\n\n- Nie zmieniaj linków w żaden inny sposób niż usunięcie query parametrów\n- Zachowaj kolejność linków\n- Zachowaj format pliku\n- Jeżeli na końcu linku jest `#` z tekstem po nim, ten tekst powinien zostać w linku\n\n# Jakie query parametry usuwać\n\n- `utm_source`\n- `utm_medium`\n- `utm_campaign`\n- `utm_term`\n- `utm_content`\n- `_bhlid`\n- `lid`\n- `r`\n- `triedRedirect`\n- `IR`\n- `isFreemail`","body":"# Kroki\n\n1. Wczytaj podany plik\n2. Usuń query parametry z linków\n3. Zapisz zmiany w pliku `cleaned_...`\n\n# Wytyczne\n\n- Nie zmieniaj linków w żaden inny sposób niż usunięcie query parametrów\n- Zachowaj kolejność linków\n- Zachowaj format pliku\n- Jeżeli na końcu linku jest `#` z tekstem po nim, ten tekst powinien zostać w linku\n\n# Jakie query parametry usuwać\n\n- `utm_source`\n- `utm_medium`\n- `utm_campaign`\n- `utm_term`\n- `utm_content`\n- `_bhlid`\n- `lid`\n- `r`\n- `triedRedirect`\n- `IR`\n- `isFreemail`\n- `mod`\n- `module`\n- `pgtype`\n- `post_id`\n- `publication_id`\n- `reflink`\n- `s`"},"lastSynced":"2026-03-08T02:13:17.109Z","agentAnalysis":{"suitability":{"en":"Perfect for Web Scraping Agents needing clean URL processing without modifying link order or format.","zh":"非常适合需要清洁URL处理的Web Scraping Agents，不会修改链接顺序或格式。","ja":"Web ScrapingエージェントがクリーンなURL処理を必要とする場合に最適です。リンクの順序やフォーマットを変更しません。","ko":"웹 스크래핑 에이전트가 깨끗한 URL 처리를 필요로 할 때 완벽합니다. 링크 순서 또는 형식을 수정하지 않습니다.","es":"Perfecto para Agentes de Scraping Web que necesitan un procesamiento de URL limpio sin modificar el orden o formato de los enlaces.","fr":"Parfait pour les Agents de Scraping Web ayant besoin d''un traitement d''URL propre sans modifier l''ordre ou le format des liens.","de":"Perfekt für Web-Scraping-Agents, die ein sauberes URL-Verarbeitung benötigen, ohne die Reihenfolge oder das Format der Links zu ändern.","pt":"Perfeito para Agentes de Web Scraping que precisam de processamento de URL limpo sem modificar a ordem ou formato do link.","ru":"Идеально подходит для агентов веб-скрапинга, требующих чистой обработки URL без изменения порядка или формата ссылки.","ar":"مثالي للوكلاء لاستخلاص الويب الذين يحتاجون إلى معالجة عنوان URL نظيف دون تغيير ترتيب أو تنسيق الارتباط."},"recommendation":{"en":"Empowers agents to remove unwanted query parameters like utm_source, utm_medium, and _bhlid from URLs, preserving link integrity and format, while maintaining any # anchor text, using standard URL parsing protocols.","zh":"赋予代理删除不需要的查询参数（如utm_source、utm_medium和_bhlid）从URL中，保持链接完整性和格式，同时保持任何#锚文本，使用标准的URL解析协议。","ja":"エージェントが不要なクエリパラメータ（utm_source、utm_medium、_bhlidなど）をURLから削除することを可能にします。リンクの完全性とフォーマットを維持し、任意の#アンカー テキストを保持します。標準のURL解析プロトコルを使用します。","ko":"에이전트가 불필요한 쿼리 매개 변수(예: utm_source, utm_medium, _bhlid)를 URL에서 제거할 수 있도록 합니다. 링크의完整性와 형식을 유지하고, 任意의 #錨テキスト를 유지합니다. 표준 URL 파싱 프로토콜을 사용합니다.","es":"Habilita a los agentes a eliminar parámetros de consulta no deseados como utm_source, utm_medium y _bhlid de las URLs, preservando la integridad y el formato del enlace, manteniendo cualquier texto de ancla #, utilizando protocolos de análisis de URL estándar.","fr":"Permet aux agents de supprimer les paramètres de requête indésirables tels que utm_source, utm_medium et _bhlid des URLs, préservant l''intégrité et le format du lien, en conservant tout texte d''ancre #, en utilisant des protocoles d''analyse d''URL standard.","de":"Ermöglicht es Agenten, unerwünschte Abfrageparameter wie utm_source, utm_medium und _bhlid aus URLs zu entfernen, die Integrität und das Format des Links zu erhalten, während sie jeden #-Anker-Text beibehalten, unter Verwendung standardisierter URL-Analyseprotokolle.","pt":"Habilita os agentes a remover parâmetros de consulta indesejados como utm_source, utm_medium e _bhlid dos URLs, preservando a integridade e o formato do link, além de manter qualquer texto de âncora #, usando protocolos de análise de URL padrão.","ru":"Позволяет агентам удалять нежелательные параметры запроса, такие как utm_source, utm_medium и _bhlid из URL, сохраняя целостность и формат ссылки, а также поддерживая любой текст якоря #, используя стандартные протоколы парсинга URL.","ar":"تمكين الوكلاء من إزالة 매개 Variables غير المرغوب فيها مثل utm_source و utm_medium و _bhlid من عناوين URL، مع الحفاظ على سلامة الرابط وتنسيقه، مع الحفاظ على أي نص مرجعي #، باستخدام بروتوكولات تحليل عنوان URL القياسية."},"useCases":{"en":["Cleaning URLs for web scraping projects","Removing tracking parameters from links","Normalizing URLs for data analysis"],"zh":["用于Web Scraping项目的URL清理","从链接中删除跟踪参数","用于数据分析的URL标准化"],"ja":["Web ScrapingプロジェクトのURLクリーンアップ","リンクからトラッキングパラメータを削除","データ分析のためのURL標準化"],"ko":["웹 스크래핑 프로젝트를 위한 URL 클리닝","링크에서 추적 매개 변수 제거","데이터 분석을 위한 URL 표준화"],"es":["Limpieza de URLs para proyectos de scraping web","Eliminación de parámetros de seguimiento de los enlaces","Normalización de URLs para análisis de datos"],"fr":["Nettoyage des URLs pour les projets de scraping web","Suppression des paramètres de suivi des liens","Normalisation des URLs pour l''analyse de données"],"de":["Reinigung von URLs für Web-Scraping-Projekte","Entfernen von Tracking-Parametern aus Links","Normalisierung von URLs für Datenanalyse"],"pt":["Limpeza de URLs para projetos de web scraping","Remoção de parâmetros de rastreamento de links","Normalização de URLs para análise de dados"],"ru":["Очистка URL для проектов веб-скрапинга","Удаление параметров отслеживания из ссылок","Нормализация URL для анализа данных"],"ar":["تنظيف عناوين URL لمشاريع استخلاص الويب","إزالة معايير التتبع من الروابط","تطبيع عناوين URL لتحليل البيانات"]},"limitations":{"en":["Does not support modification of link order or format beyond query parameter removal","Preserves # anchor text but does not handle other URL fragments","Specifically targets removal of predefined query parameters like utm_source and _bhlid"],"zh":["不支持除查询参数删除之外的链接顺序或格式的修改","保持#锚文本，但不处理其他URL片段","专门针对预定义的查询参数（如utm_source和_bhlid）的删除"],"ja":["クエリパラメータの削除を超えたリンクの順序またはフォーマットの変更はサポートされません","#アンカー テキストは保持しますが、他のURLフラグメントは処理しません","事前に定義されたクエリパラメータ（utm_sourceや_bhlidなど）の削除を対象としています"],"ko":["쿼리 매개 변수 제거를 넘어서 링크 순서 또는 형식의 수정을 지원하지 않습니다","#錨テキスト는 유지하지만, 다른 URL 조각은 처리하지 않습니다","事前に 정의된 쿼리 매개 변수(예: utm_source, _bhlid)의 제거를 대상으로 합니다"],"es":["No admite la modificación del orden o formato de los enlaces más allá de la eliminación de parámetros de consulta","Mantiene el texto de ancla #, pero no maneja otros fragmentos de URL","Apunta específicamente a la eliminación de parámetros de consulta predefinidos como utm_source y _bhlid"],"fr":["N''admet pas la modification de l''ordre ou du format des liens au-delà de la suppression des paramètres de requête","Préserve le texte d''ancre #, mais ne gère pas d''autres fragments d''URL","Cible spécifiquement la suppression de paramètres de requête prédéfinis tels que utm_source et _bhlid"],"de":["Unterstützt keine Änderung der Reihenfolge oder des Formats der Links über die Entfernung von Abfrageparametern hinaus","Behält den #-Anker-Text bei, bearbeitet jedoch keine anderen URL-Fragmente","Zielt speziell auf die Entfernung von vordefinierten Abfrageparametern wie utm_source und _bhlid ab"],"pt":["Não suporta modificação da ordem ou formato do link além da remoção de parâmetros de consulta","Preserva o texto de âncora #, mas não lida com outros fragmentos de URL","Destina-se especificamente à remoção de parâmetros de consulta predefinidos como utm_source e _bhlid"],"ru":["Не поддерживает изменение порядка или формата ссылки за пределами удаления параметров запроса","Сохраняет текст якоря #, но не обрабатывает другие фрагменты URL","Конкретно нацелен на удаление предопределенных параметров запроса, таких как utm_source и _bhlid"],"ar":["لا يدعم تعديل ترتيب أو تنسيق الارتباط أبعد من إزالة معايير الاستعلام","تحافظ على نص المرجع #، ولكن لا تتناول أجزاء أخرى من عنوان URL","يستهدف تحديداً إزالة معايير الاستعلام المحددة مسبقاً مثل utm_source و _bhlid"]},"version":4},"contentHash":"8d54ace3f7ea89b562085217eabda3f1c69c1ce3c4e843c946c90dc87b86fe76","qualityScore":23}');
