INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('0xSahils/lawyer_portfolio_1/motion-systems', 'motion-systems', '0xSahils', 'lawyer_portfolio_1', 'community', 'motion-systems 0xSahils lawyer_portfolio_1 community The motion-systems skill helps developers create intentional and refined animations, enhancing UX and guiding users. It provides techniques like staggered animations for a clear and impressive user interface. Motion Systems 是一种创建高质量运动体验的技术，旨在提升用户体验和交互设计。 Motion Systems は、アニメーションを適切に実装し、UX を高めるための技術です。 Motion Systems 은 의도적인 동작을 구축하고 사용자 경험을 향상시키는 기술입니다. Crea sistemas de movimiento que mejoran la experiencia del usuario con técnicas como animaciones escalonadas Créez des systèmes de mouvement qui améliorent l''expérience utilisateur avec des techniques comme les animations échelonnées Erstellen Sie Bewegungssysteme, die die Benutzererfahrung verbessern, mit Techniken wie gestaffelten Animationen Desenvolva sistemas de movimento que sejam intencionais, melhorem a UX e sejam sutis, mas impressionantes, utilizando referências como Apple e Linear Разработайте системы движения, которые являются намеренными, улучшают UX и являются тонкими, но впечатляющими, используя ссылки на Apple и Linear قم بإنشاء أنظمة حركة تكون مقصودة وتحسن تجربة المستخدم وتكون رفيعة المستوى، مع استخدام المراجع مثل Apple و Linear how to use motion-systems what is motion-systems motion-systems setup guide motion-systems vs Linear motion-systems alternative to Vercel install motion-systems motion-systems best practices motion-systems for AI agents motion-systems UX design Motion Systems AIエージェント 高质量运动体验 UX 设计 交互设计 staggered animations intentional 动作设计 Applies core principles of intentional, UX-enhancing, and non-distracting motion Utilizes staggered animations for revealing lists, cards, or grid items Follows reference designs from Apple, Linear, Vercel, and Stripe for inspiration Supports the creation of refined and subtle animations Guides developers in crafting motion that supports and delights users motion-systems is a set of principles and techniques for building motion that feels intentional, enhances UX, and never distracts, aiming for subtle but impressive effects.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('pekral/pint-rules/rewrite-tests-pest', 'community', 'pekral', 'pint-rules', 'pekral/pint-rules', 'rewrite-tests-pest', 0, 0, 23, '2026-03-08T01:57:15.625Z', '2026-03-08T02:13:34.005Z', '57b8a85d72ee664cd3b9194dabfc981f725abe092af9f4fd56dfec89fec647d4', '{"id":"pekral/pint-rules/rewrite-tests-pest","name":"rewrite-tests-pest","description":{"en":"The rewrite-tests-pest skill converts PHPUnit test classes to PEST syntax, applying testing rules from standards.mdc and php-testing.mdc. It ensures 100% coverage for changed code without modifying production code.","zh":"rewrite-tests-pest技能专为将PHPUnit测试类转换为PEST语法而设计，确保测试规则和100%代码覆盖率","ja":"rewrite-tests-pestスキルは、PHPUnitテストクラスをPESTシンタックスに変換するために設計されており、テストルールと100%のコードカバレッジを確保","ko":"rewrite-tests-pest 기술은 PHPUnit 테스트 클래스를 PEST 문법으로 변환하기 위해 설계되었으며 테스트 규칙과 100% 코드 커버리지 보장","es":"Rewrite-tests-pest es una herramienta especializada para convertir clases de prueba de PHPUnit a sintaxis PEST, aplicando reglas de testing y mejorando la cobertura de pruebas","fr":"Rewrite-tests-pest est un outil spécialisé pour convertir les classes de test PHPUnit en syntaxe PEST, en appliquant les règles de testing et en améliorant la couverture des tests","de":"Rewrite-tests-pest ist ein Spezialtool für die Umwandlung von PHPUnit-Testklassen in PEST-Syntax, wobei Testregeln angewendet und die Testabdeckung verbessert werden","pt":"O agente rewrite-tests-pest é um especialista em converter classes de teste PHPUnit para sintaxe PEST. Ele aplica regras de teste do arquivo .cursor/rules/php/standards.mdc.","ru":"Агент rewrite-tests-pest является специалистом по конвертации классов тестов PHPUnit в синтаксис PEST. Он применяет правила тестирования из файла .cursor/rules/php/standards.mdc.","ar":"العميل rewrite-tests-pest هو خبير في تحويل فئات الاختبار PHPUnit إلى بناء جملة PEST. يطبق قواعد ا