INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('pekral/pint-rules/rewrite-tests-pest', 'rewrite-tests-pest', 'pekral', 'pint-rules', 'community', 'rewrite-tests-pest pekral pint-rules community The rewrite-tests-pest skill converts PHPUnit test classes to PEST syntax, applying testing rules from standards.mdc and php-testing.mdc. It ensures 100% coverage for changed code without modifying production code. rewrite-tests-pest技能专为将PHPUnit测试类转换为PEST语法而设计，确保测试规则和100%代码覆盖率 rewrite-tests-pestスキルは、PHPUnitテストクラスをPESTシンタックスに変換するために設計されており、テストルールと100%のコードカバレッジを確保 rewrite-tests-pest 기술은 PHPUnit 테스트 클래스를 PEST 문법으로 변환하기 위해 설계되었으며 테스트 규칙과 100% 코드 커버리지 보장 Rewrite-tests-pest es una herramienta especializada para convertir clases de prueba de PHPUnit a sintaxis PEST, aplicando reglas de testing y mejorando la cobertura de pruebas Rewrite-tests-pest est un outil spécialisé pour convertir les classes de test PHPUnit en syntaxe PEST, en appliquant les règles de testing et en améliorant la couverture des tests Rewrite-tests-pest ist ein Spezialtool für die Umwandlung von PHPUnit-Testklassen in PEST-Syntax, wobei Testregeln angewendet und die Testabdeckung verbessert werden O agente rewrite-tests-pest é um especialista em converter classes de teste PHPUnit para sintaxe PEST. Ele aplica regras de teste do arquivo .cursor/rules/php/standards.mdc. Агент rewrite-tests-pest является специалистом по конвертации классов тестов PHPUnit в синтаксис PEST. Он применяет правила тестирования из файла .cursor/rules/php/standards.mdc. العميل rewrite-tests-pest هو خبير في تحويل فئات الاختبار PHPUnit إلى بناء جملة PEST. يطبق قواعد الاختبار من الملف .cursor/rules/php/standards.mdc how to use rewrite-tests-pest what is rewrite-tests-pest rewrite-tests-pest alternative rewrite-tests-pest vs PHPUnit rewrite-tests-pest install rewrite-tests-pest setup guide PEST syntax conversion PHPUnit test conversion rewrite-tests-pest PHPUnit PEST 测试规则 代码覆盖率 PHP 测试自动化 代码转换 Converts PHPUnit test classes to PEST syntax Applies testing rules from .cursor/rules/php/standards.mdc and .cursor/rules/php-testing.mdc Ensures 100% coverage for changed code Adds missing tests if needed Loads rules from .cursor/rules/php/standard rewrite-tests-pest is a specialist skill for converting PHPUnit test classes to PEST syntax, following specific testing rules and constraints.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('DivineDominion/textbundler-extension/textbundler-reviewer', 'community', 'DivineDominion', 'textbundler-extension', 'DivineDominion/textbundler-extension', 'textbundler-reviewer', 0, 0, 23, '2026-03-08T01:57:15.636Z', '2026-03-08T02:13:37.523Z', '4f2d6088bb5c4d0e9dc1b9dfd069ec8c18c2a85d99671d5684f61251cd77e728', '{"id":"DivineDominion/textbundler-extension/textbundler-reviewer","name":"textbundler-reviewer","description":{"en":"The textbundler-reviewer skill is a browser extension that exports current articles as TextBundle, a format combining Markdown with attachments, benefiting developers and content creators. It reviews the current feature branch against main and outputs comments in COMMENTS.md.","zh":"TextBundler Reviewer 是一个浏览器扩展，用于导出当前文章为 TextBundle（Markdown 附件）格式，并对比主分支进行代码审查","ja":"TextBundler Reviewer は、AIエージェントを使用して、現在の記事を TextBundle（Markdown 添付ファイル）形式でエクスポートし、コードレビューを実施するブラウザ拡張機能です","ko":"TextBundler Reviewer는 현재 기사를 TextBundle(Markdown 첨부 파일) 형식으로 내보내고 코드를 검토하는 브라우저 확장 프로그램입니다","es":"textbundler-reviewer es una extensión de navegador que permite exportar artículos como TextBundle, utilizando markdown y adjuntos. Sigue el procedimiento de revisión completo para garantizar la calidad de tus artículos","fr":"textbundler-reviewer est une extension de navigateur qui permet d''exporter des articles au format TextBundle, en utilisant markdown et pièces jointes. Suivez la procédure de révision complète pour assurer la qualité de vos articles","de":"textbundler-reviewer ist eine Browser-Erweiterung, die es ermöglicht, Artikel als TextBundle zu exportieren, mit Markdown und Anhängen. Befolgen Sie das vollständige Überprüfungsverfahren, um die Qualität Ihrer Artikel zu gewährleisten","pt":"O textbundler-reviewer é uma extensão de navegador que exporta artigos como TextBundle, com suporte a anexos em Markdown. Siga o procedimento de revisão completo definido em `.codex/agents/reviewer.md`","ru":"textbundler-reviewer — это расширение браузера, которое экспортирует статьи как TextBundle с вложениями в формате Markdown. Следуйте полной процедуре проверки, определенной в `.codex/agents/reviewer.md`, используя ИИ Агенты","ar":"textbundler-reviewer ملحقات المتصفح التي توفر خاصية تصدير المقال الحالي كملف TextBundle مع مرفقات في صيغة Markdown. اتبع الإجراء الكامل لمراجعة الملفات كما هو محدد في `.codex/agents/reviewer.md`"},"seo":{"title":{"en":"textbundler-reviewer: Export Articles as TextBundle | AI ...","zh":"TextBundler Reviewer 设置指南：Markdown 附件导出","ja":"TextBundler Reviewer のベストプラクティス：AIエージェントによるMarkdown添付ファイル...","ko":"TextBundler Reviewer 사용법: Markdown 첨부 파일 내보내기","es":"Guía de configuración de textbundler-reviewer: Exportació...","fr":"Guide d''installation de textbundler-reviewer: Exporter de...","de":"Einrichtungsleitfaden für textbundler-reviewer: Artikel a...","pt":"Guia de Configuração do textbundler-reviewer: Extensão de...","ru":"Настройка textbundler-reviewer: Расширение браузера для э...","ar":"دليل إعداد textbundler-reviewer: ملحقات المتصفح لتخزين ال..."},"description":{"en":"Discover how textbundler-reviewer simplifies article export as Markdown with attachments. Learn how to use this browser extension and improve your workflow t...","zh":"了解 TextBundler Reviewer 的功能和特点，包括导出 Markdown 附件和对比主分支的代码审查","ja":"TextBundler Reviewer を使用して、Markdown 添付ファイルをエクスポートし、コードレビューを実施します。AIエージェントの機能を最大限に活用しましょう","ko":"TextBundler Reviewer 기능과 장점을 소개합니다. Markdown 첨부 파일을 내보내고 메인 브랜치와 비교하여 코드를 검토합니다","es":"Aprende a utilizar textbundler-reviewer, una extensión de navegador para exportar artículos como TextBundle con markdown y adjuntos","fr":"Découvrez comment utiliser textbundler-reviewer, une extension de navigateur pour exporter des articles au format TextBundle avec markdown et pièces jointes","de":"Erfahren Sie, wie Sie textbundler-reviewer verwenden, eine Browser-Erweiterung zum Export von Artikeln als TextBundle mit Markdown und Anhängen","pt":"Aprenda a configurar o textbundler-reviewer, uma extensão de navegador que exporta artigos como TextBundle, com suporte a anexos em Markdown","ru":"Узнайте, как настроить textbundler-reviewer, расширение браузера, которое экспортирует статьи как TextBundle с вложениями в формате Markdown, используя ИИ Аг...","ar":"اكتشف كيفية إعداد textbundler-reviewer، ملحقات المتصفح التي توفر خاصية تصدير المقال الحالي كملف TextBundle مع مرفقات في صيغة Markdown"},"definition":{"en":"textbundler-reviewer is a browser extension that enables the export of articles as TextBundle, a file format that combines Markdown text with attachments.","zh":"TextBundler Reviewer 是一个用于导出 Markdown 附件和代码审查的浏览器扩展","ja":"TextBundler Reviewer は、Markdown 添付ファイルをエクスポートし、コードレビューを実施する AIエージェントの一種です","ko":"TextBundler Reviewer는 Markdown 첨부 파일을 내보내고 코드를 검토하는 브라우저 확장 프로그램의 일종입니다","es":"textbundler-reviewer es una herramienta de revisión de artículos que exporta contenido como TextBundle con markdown y adjuntos","fr":"textbundler-reviewer est un outil de révision d''articles qui exporte du contenu au format TextBundle avec markdown et pièces jointes","de":"textbundler-reviewer ist ein Werkzeug zur Überprüfung von Artikeln, das Inhalte als TextBundle mit Markdown und Anhängen exportiert","pt":"O textbundler-reviewer é uma extensão de navegador que permite exportar artigos como TextBundle, com suporte a anexos em Markdown","ru":"textbundler-reviewer — это расширение браузера, которое позволяет экспортировать статьи как TextBundle с вложениями в формате Markdown, используя ИИ Агенты","ar":"textbundler-reviewer ملحقات المتصفح التي تمكنك من تصدير المقال الحالي كملف TextBundle مع مرفقات في صيغة Markdown"},"features":{"en":["Exports articles as TextBundle, combining Markdown with attachments","Reviews the current feature branch against main","Follows the full review procedure defined in .codex/agents/reviewer.md","Outputs comments in COMMENTS.md committed to the branch","Utilizes the Markdown file format for text content","Supports attachment inclusion in the exported TextBundle"],"zh":["导出 Markdown 附件","对比主分支进行代码审查","使用 .codex/agents/reviewer.md 进行代码审查","输出 COMMENTS.md 文件","提交代码审查结果到分支"],"ja":["Markdown 添付ファイルのエクスポート","メインブランチとのコードレビュー",".codex/agents/reviewer.md によるコードレビュー","COMMENTS.md ファイルの出力","コードレビュー結果のブランチへのコミット"],"ko":["Markdown 첨부 파일 내보내기","메인 브랜치와의 코드 검토",".codex/agents/reviewer.md를 사용한 코드 검토","COMMENTS.md 파일 출력","코드 검토 결과를 브랜치에 커밋"],"es":["Exportación de artículos como TextBundle","Utilización de markdown para la formateo de texto","Inclusión de adjuntos en el archivo TextBundle","Seguimiento del procedimiento de revisión completo","Generación de un archivo COMMENTS.md para la retroalimentación","Compatibilidad con la rama principal para la revisión"],"fr":["Exportation d''articles au format TextBundle","Utilisation de markdown pour la mise en forme du texte","Inclusion de pièces jointes dans le fichier TextBundle","Suivi de la procédure de révision complète","Génération d''un fichier COMMENTS.md pour la rétroaction","Compatibilité avec la branche principale pour la révision"],"de":["Export von Artikeln als TextBundle","Verwendung von Markdown für die Textformatierung","Einclusion von Anhängen in der TextBundle-Datei","Befolgen des vollständigen Überprüfungsverfahrens","Erstellung einer COMMENTS.md-Datei für die Rückmeldung","Kompatibilität mit dem Hauptzweig für die Überprüfung"],"pt":["Exportação de artigos como TextBundle","Suporte a anexos em Markdown","Integração com procedimento de revisão completo","Saída em formato COMMENTS.md","Commit automático para o branch"],"ru":["Экспорт статей как TextBundle","Поддержка вложений в формате Markdown","Интеграция с полной процедурой проверки","Выходные данные в формате COMMENTS.md","Автоматический коммит в ветку, использующий ИИ Агенты"],"ar":["تصدير المقال الحالي كملف TextBundle","دعم المرفقات في صيغة Markdown","التكامل مع الإجراء الكامل لمراجعة الملفات","إخراج البيانات في صيغة COMMENTS.md","التعدين التلقائي إلى الفرع"]},"keywords":{"en":["how to use textbundler-reviewer","textbundler-reviewer alternative","textbundler-reviewer setup guide","what is textbundler-reviewer","textbundler-reviewer vs markdown exporters","textbundler-reviewer install","textbundler-reviewer browser extension","export article as TextBundle","TextBundle format"],"zh":["TextBundler Reviewer","Markdown 附件","代码审查","浏览器扩展","AI 工具","代码管理","版本控制"],"ja":["TextBundler Reviewer","Markdown 添付ファイル","コードレビュー","ブラウザ拡張機能","AIエージェント","コード管理","バージョン管理"],"ko":["TextBundler Reviewer","Markdown 첨부 파일","코드 검토","브라우저 확장 프로그램","AI 도구","코드 관리","버전 관리"],"es":["textbundler-reviewer","herramientas de revisión de artículos","exportación de artículos como TextBundle","markdown","adjuntos","revisión de código","desarrollo de software","herramientas de desarrollo","Herramientas de AI"],"fr":["textbundler-reviewer","outils de révision d''articles","exportation d''articles au format TextBundle","markdown","pièces jointes","révision de code","développement de logiciels","outils de développement","Outils d''IA"],"de":["textbundler-reviewer","Werkzeuge zur Überprüfung von Artikeln","Export von Artikeln als TextBundle","Markdown","Anhänge","Code-Überprüfung","Software-Entwicklung","Entwicklungs-Werkzeuge","KI-Tools"],"pt":["textbundler-reviewer","extensão de navegador","TextBundle","Markdown","anexos","procedimento de revisão","COMMENTS.md","commit automático","desenvolvimento web"],"ru":["textbundler-reviewer","расширение браузера","TextBundle","Markdown","вложения","процедура проверки","COMMENTS.md","автоматический коммит","ИИ Агенты","веб-разработка"],"ar":["textbundler-reviewer","ملحقات المتصفح","TextBundle","Markdown","مرفقات","إجراء مراجعة","COMMENTS.md","التعدين التلقائي","تطوير الويب","أدوات الذكاء الاصطناعي"]}},"owner":"DivineDominion","repo":"textbundler-extension","repoPath":"DivineDominion/textbundler-extension","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.636Z","topics":[],"category":"community","skillMd":{"name":"textbundler-reviewer","description":">","bodyPreview":"Review the current feature branch against `main`.\n\nFollow the full review procedure defined in `.codex/agents/reviewer.md`.\nOutput is `COMMENTS.md` committed to the branch.","body":"Review the current feature branch against `main`.\n\nFollow the full review procedure defined in `.codex/agents/reviewer.md`.\nOutput is `COMMENTS.md` committed to the branch.\n"},"lastSynced":"2026-03-08T02:13:37.523Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Review Agents needing automated branch comparison and Markdown-based feedback generation.","zh":"非常适合需要自动化分支比较和基于Markdown的反馈生成的代码审查代理","ja":"コードレビューエージェントが自動化されたブランチの比較とMarkdownベースのフィードバック生成を必要とする場合に最適","ko":"자동화된 브랜치 비교 및 Markdown 기반 피드백 생성이 필요한 코드 리뷰 에이전트에 적합","es":"Perfecto para agentes de revisión de código que necesitan comparación automática de ramas y generación de comentarios basados en Markdown.","fr":"Parfait pour les agents de révision de code nécessitant une comparaison automatique de branches et une génération de commentaires basés sur Markdown.","de":"Perfekt für Code-Review-Agenten, die eine automatisierte Branch-Vergleich und eine Markdown-basierte Feedback-Generierung benötigen.","pt":"Perfeito para Agentes de Revisão de Código que necessitam de comparação de branch automatizada e geração de feedback baseada em Markdown.","ru":"Идеально подходит для агентов код-ревью, которым необходима автоматизированная сравнение веток и генерация отзывов на основе Markdown.","ar":"مثالي لعميل مراجعة الكود الذي يحتاج إلى مقارنة الفرع الآلي وتوليد ملاحظات بالتنسيق القائم على Markdown."},"recommendation":{"en":"Empowers agents to review feature branches against main, utilizing TextBundle format for combining Markdown with attachments, and outputs comments in COMMENTS.md, leveraging Git for version control and branch management.","zh":"赋予代理审查功能分支与主分支，利用TextBundle格式将Markdown与附件结合，输出注释到COMMENTS.md，利用Git进行版本控制和分支管理","ja":"エージェントが機能ブランチをメインブランチに対してレビューできるようにし、TextBundle形式を使用してMarkdownと添付ファイルを組み合わせ、COMMENTS.mdにコメントを出力し、Gitを使用してバージョン管理とブランチ管理を行う","ko":"에이전트가 기능 브랜치를 메인 브랜치와 비교하여審查할 수 있도록 하며, TextBundle 형식을 사용하여 Markdown와 첨부 파일을 결합하고, COMMENTS.md에 코멘트를 출력하며, Git을 사용하여 버전 관리와 브랜치 관리를 수행","es":"Habilita a los agentes a revisar ramas de características contra la rama principal, utilizando el formato TextBundle para combinar Markdown con archivos adjuntos y salida de comentarios en COMMENTS.md, aprovechando Git para el control de versiones y la gestión de ramas.","fr":"Permet aux agents de réviser les branches de fonctionnalités par rapport à la branche principale, en utilisant le format TextBundle pour combiner Markdown avec des pièces jointes et en sortie des commentaires dans COMMENTS.md, en exploitant Git pour le contrôle de version et la gestion des branches.","de":"Ermächtigt Agenten, Feature-Branches gegen die Haupt-Branch zu überprüfen, indem sie das TextBundle-Format verwenden, um Markdown mit Anlagen zu kombinieren und Kommentare in COMMENTS.md auszugeben, wobei Git für die Versionskontrolle und die Branch-Verwaltung genutzt wird.","pt":"Habilita os agentes a revisar branches de recursos contra o branch principal, utilizando o formato TextBundle para combinar Markdown com anexos e produzindo comentários em COMMENTS.md, aproveitando o Git para controle de versão e gerenciamento de branch.","ru":"Наделяет агентов возможностью просматривать функциональные ветки против основной, используя формат TextBundle для объединения Markdown с вложениями и вывода комментариев в COMMENTS.md, используя Git для контроля версий и управления ветками.","ar":"يمنح الوكيل القدرة على مراجعة فروع الميزات مقابل الفرع الرئيسي، باستخدام تنسيق TextBundle لدمج Markdown مع المرفقات، وتنفيذ التعليقات في COMMENTS.md، مستفيداً من Git لمراقبة الإصدارات وإدارة الفروع."},"useCases":{"en":["Automating code reviews for feature branches","Generating feedback in Markdown format with attachments","Comparing feature branches against main for consistency"],"zh":["自动化功能分支的代码审查","生成带有附件的Markdown格式反馈","比较功能分支与主分支以确保一致性"],"ja":["機能ブランチのコードレビューを自動化する","添付ファイルを含むMarkdown形式のフィードバックを生成する","機能ブランチとメインブランチを比較して一貫性を確保する"],"ko":["기능 브랜치의 코드 리뷰를 자동화","첨부 파일을 포함하는 Markdown 형식의 피드백을 생성","기능 브랜치를 메인 브랜치와 비교하여 일관성을 보장"],"es":["Automatizar las revisiones de código para ramas de características","Generar comentarios en formato Markdown con archivos adjuntos","Comparar ramas de características con la rama principal para garantizar la coherencia"],"fr":["Automatiser les révisions de code pour les branches de fonctionnalités","Générer des commentaires au format Markdown avec des pièces jointes","Comparer les branches de fonctionnalités avec la branche principale pour assurer la cohérence"],"de":["Automatisierung von Code-Reviews für Feature-Branches","Generieren von Feedback im Markdown-Format mit Anlagen","Vergleichen von Feature-Branches mit der Haupt-Branch für Konsistenz"],"pt":["Automatizar revisões de código para branches de recursos","Gerar feedback no formato Markdown com anexos","Comparar branches de recursos contra o branch principal para garantir a consistência"],"ru":["Автоматизировать код-ревью для функциональных веток","Генерировать отзывы в формате Markdown с вложениями","Сравнивать функциональные ветки с основной для обеспечения согласованности"],"ar":["تأتمتة مراجعة الكود لفروع الميزات","توليد ملاحظات بتنسيق Markdown مع المرفقات","مقارنة فروع الميزات مع الفرع الرئيسي لضمان الاتساق"]},"limitations":{"en":["Requires Git repository access","Limited to reviewing feature branches against main","Outputs comments in COMMENTS.md file only"],"zh":["需要Git仓库访问权限","仅限于比较功能分支与主分支","仅输出COMMENTS.md文件中的注释"],"ja":["Gitリポジトリへのアクセス権が必要","機能ブランチとメインブランチの比較のみ","COMMENTS.mdファイルのみにコメントを出力する"],"ko":["Git 저장소 접근 권한이 필요","기능 브랜치와 메인 브랜치의 비교만","COMMENTS.md 파일에만 코멘트를 출력"],"es":["Requiere acceso al repositorio Git","Limitado a la revisión de ramas de características contra la rama principal","Salida de comentarios solo en el archivo COMMENTS.md"],"fr":["Nécessite un accès au référentiel Git","Limité à la révision des branches de fonctionnalités par rapport à la branche principale","Sortie de commentaires uniquement dans le fichier COMMENTS.md"],"de":["Benötigt Zugriff auf das Git-Repository","Begrenzt auf die Überprüfung von Feature-Branches gegen die Haupt-Branch","Kommentare werden nur in der Datei COMMENTS.md ausgegeben"],"pt":["Requer acesso ao repositório Git","Limitado à revisão de branches de recursos contra o branch principal","Produz comentários apenas no arquivo COMMENTS.md"],"ru":["Требует доступа к репозиторию Git","Ограничен просмотром функциональных веток против основной","Выводит комментарии только в файл COMMENTS.md"],"ar":["يتطلب الوصول إلى مستودع Git","محدود بمراجعة فروع الميزات مقابل الفرع الرئيسي","ينفذ التعليقات فقط في ملف COMMENTS.md"]},"version":4},"contentHash":"4f2d6088bb5c4d0e9dc1b9dfd069ec8c18c2a85d99671d5684f61251cd77e728","qualityScore":23}');
