INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('DivineDominion/textbundler-extension/textbundler-reviewer', 'textbundler-reviewer', 'DivineDominion', 'textbundler-extension', 'community', 'textbundler-reviewer DivineDominion textbundler-extension community The textbundler-reviewer skill is a browser extension that exports current articles as TextBundle, a format combining Markdown with attachments, benefiting developers and content creators. It reviews the current feature branch against main and outputs comments in COMMENTS.md. TextBundler Reviewer 是一个浏览器扩展，用于导出当前文章为 TextBundle（Markdown 附件）格式，并对比主分支进行代码审查 TextBundler Reviewer は、AIエージェントを使用して、現在の記事を TextBundle（Markdown 添付ファイル）形式でエクスポートし、コードレビューを実施するブラウザ拡張機能です TextBundler Reviewer는 현재 기사를 TextBundle(Markdown 첨부 파일) 형식으로 내보내고 코드를 검토하는 브라우저 확장 프로그램입니다 textbundler-reviewer es una extensión de navegador que permite exportar artículos como TextBundle, utilizando markdown y adjuntos. Sigue el procedimiento de revisión completo para garantizar la calidad de tus artículos textbundler-reviewer est une extension de navigateur qui permet d''exporter des articles au format TextBundle, en utilisant markdown et pièces jointes. Suivez la procédure de révision complète pour assurer la qualité de vos articles textbundler-reviewer ist eine Browser-Erweiterung, die es ermöglicht, Artikel als TextBundle zu exportieren, mit Markdown und Anhängen. Befolgen Sie das vollständige Überprüfungsverfahren, um die Qualität Ihrer Artikel zu gewährleisten O textbundler-reviewer é uma extensão de navegador que exporta artigos como TextBundle, com suporte a anexos em Markdown. Siga o procedimento de revisão completo definido em `.codex/agents/reviewer.md` textbundler-reviewer — это расширение браузера, которое экспортирует статьи как TextBundle с вложениями в формате Markdown. Следуйте полной процедуре проверки, определенной в `.codex/agents/reviewer.md`, используя ИИ Агенты textbundler-reviewer ملحقات المتصفح التي توفر خاصية تصدير المقال الحالي كملف TextBundle مع مرفقات في صيغة Markdown. اتبع الإجراء الكامل لمراجعة الملفات كما هو محدد في `.codex/agents/reviewer.md` how to use textbundler-reviewer textbundler-reviewer alternative textbundler-reviewer setup guide what is textbundler-reviewer textbundler-reviewer vs markdown exporters textbundler-reviewer install textbundler-reviewer browser extension export article as TextBundle TextBundle format TextBundler Reviewer Markdown 附件 代码审查 浏览器扩展 AI 工具 代码管理 版本控制 Exports articles as TextBundle, combining Markdown with attachments Reviews the current feature branch against main Follows the full review procedure defined in .codex/agents/reviewer.md Outputs comments in COMMENTS.md committed to the branch Utilizes the Markdown file format for text content Supports attachment inclusion in the exported TextBundle textbundler-reviewer is a browser extension that enables the export of articles as TextBundle, a file format that combines Markdown text with attachments.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('JochenYang/Jochen-ai-rules/performance-optimizer', 'community', 'JochenYang', 'Jochen-ai-rules', 'JochenYang/Jochen-ai-rules', 'performance-optimizer', 0, 0, 23, '2026-03-08T01:57:15.659Z', '2026-03-08T02:14:02.470Z', 'b3def67a6c9be299cd1d62e3219e19fcd8377c5e8ad9660f48b5713b4a3621fc', '{"id":"JochenYang/Jochen-ai-rules/performance-optimizer","name":"performance-optimizer","description":{"en":"The performance-optimizer skill helps developers identify performance bottlenecks and design optimization solutions to improve application response speed and throughput. It benefits developers looking to optimize their code for better performance.","zh":"性能优化器能够帮助您识别性能瓶颈，设计优化解决方案，提高应用程序的响应速度和吞吐量","ja":"パフォーマンス最適化ツールは、パフォーマンスのボトルネックを特定し、最適化ソリューションを設計し、アプリケーションのレスポンス速度とスループットを向上させることができます","ko":"성능 최적화기는 성능 병목 현상을 식별하고 최적화 솔루션을 설계하여 응용 프로그램의 응답 속도와 처리량을 향상시킬 수 있습니다","es":"El Performance Optimizer es una herramienta de inteligencia artificial que ayuda a los desarrolladores a identificar cuellos de botella y optimizar el rendimiento de sus aplicaciones","fr":"Le Performance Optimizer est un outil d''intelligence artificielle qui aide les développeurs à identifier les goulets d''étranglement et à optimiser les performances de leurs applications","de":"Der Performance Optimizer ist ein KI-Tool, das Entwicklern hilft, Engpässe zu identifizieren und die Leistung ihrer Anwendungen zu optimieren","pt":"O Performance Optimizer é uma ferramenta que ajuda a identificar gargalos de desempenho e melhorar a velocidade de resposta da aplicação","ru":"ИИ Агент Performance Optimizer помогает выявить проблемы с производительностью и увеличить скорость приложения","ar":"أداة تحسين الأداء تساعد في تحديد مشاكل الأداء وتحسين سرعة الاستجابة للتطبيق"},"seo":{"title":{"en":"performance-optimizer: Performance Bottleneck Identificat...","zh":"性能