INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('JochenYang/Jochen-ai-rules/performance-optimizer', 'performance-optimizer', 'JochenYang', 'Jochen-ai-rules', 'community', 'performance-optimizer JochenYang Jochen-ai-rules community The performance-optimizer skill helps developers identify performance bottlenecks and design optimization solutions to improve application response speed and throughput. It benefits developers looking to optimize their code for better performance. 性能优化器能够帮助您识别性能瓶颈，设计优化解决方案，提高应用程序的响应速度和吞吐量 パフォーマンス最適化ツールは、パフォーマンスのボトルネックを特定し、最適化ソリューションを設計し、アプリケーションのレスポンス速度とスループットを向上させることができます 성능 최적화기는 성능 병목 현상을 식별하고 최적화 솔루션을 설계하여 응용 프로그램의 응답 속도와 처리량을 향상시킬 수 있습니다 El Performance Optimizer es una herramienta de inteligencia artificial que ayuda a los desarrolladores a identificar cuellos de botella y optimizar el rendimiento de sus aplicaciones Le Performance Optimizer est un outil d''intelligence artificielle qui aide les développeurs à identifier les goulets d''étranglement et à optimiser les performances de leurs applications Der Performance Optimizer ist ein KI-Tool, das Entwicklern hilft, Engpässe zu identifizieren und die Leistung ihrer Anwendungen zu optimieren O Performance Optimizer é uma ferramenta que ajuda a identificar gargalos de desempenho e melhorar a velocidade de resposta da aplicação ИИ Агент Performance Optimizer помогает выявить проблемы с производительностью и увеличить скорость приложения أداة تحسين الأداء تساعد في تحديد مشاكل الأداء وتحسين سرعة الاستجابة للتطبيق how to use performance-optimizer performance-optimizer alternative performance-optimizer setup guide what is performance-optimizer performance-optimizer vs New Relic performance-optimizer install optimizing application performance with performance-optimizer performance bottleneck identification techniques database query optimization best practices 性能优化 性能优化器 AI工具 应用程序优化 响应速度优化 吞吐量优化 性能瓶颈识别 数据库查询优化 Performance bottleneck identification for CPU, Memory, I/O, and Network Database query optimization using indexes, N+1, and connection pools Caching strategy design with multi-level caching Frontend Core Web Vitals optimization Algorithm and data structure optimization performance-optimizer is a skill that identifies performance bottlenecks, designs optimization solutions, and improves application response speed and throughput through techniques like database query optimization and caching strategy design.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('denis1011101/getcourt/review-ai', 'community', 'denis1011101', 'getcourt', 'denis1011101/getcourt', 'review-ai', 0, 0, 23, '2026-03-07T18:02:00Z', '2026-03-08T02:14:12.748Z', 'a98010863f0c9ed6b0e83685c25525d20402cdb31e8acd94c1ac71b0d32b9646', '{"id":"denis1011101/getcourt/review-ai","name":"review-ai","description":{"en":"The review-ai skill helps developers review changes made by AI editors, ensuring code quality and security. It benefits developers working with AI-generated code.","zh":"review-ai是用于审查AI编辑器更改的工具，通过git diff和CI检查来确保代码质量和安全性","ja":"review-aiはAIエディターの変更をレビューするツールで、git diffとCIチェックを使用してコードの品質とセキュリティを確保します","ko":"review-ai는 AI 편집기의 변경을審查하는 도구로, git diff와 CI 체크를 통해 코드 품질과 보안을 확인합니다","es":"Review-ai es una herramienta que ayuda a revisar cambios realizados por un editor de inteligencia artificial. Sigue estos pasos para mejorar la calidad de tu código","fr":"Review-ai est un outil qui aide à réviser les modifications apportées par un éditeur d''intelligence artificielle. Suivez ces étapes pour améliorer la qualité de votre code","de":"Review-ai ist ein Tool, das dabei hilft, Änderungen zu überprüfen, die von einem KI-Editor vorgenommen wurden. Befolgen Sie diese Schritte, um die Qualität Ihres Codes zu verbessern","pt":"O review-ai é uma ferramenta de revisão de código que ajuda a garantir a qualidade do código alterado por editores de IA.","ru":"ИИ Агент review-ai - это инструмент проверки кода, помогающий обеспечить качество кода, измененного редакторами ИИ.","ar":"review-ai هو أداة مراجعة الكود التي تساعد على ضمان جودة الكود الذي تم تغييره بواسطة محررات الذكاء الاصطناعي."},"seo":{"title":{"en":"review-ai: Code Review Setup Guide for AI Agents","zh":"AI代码审查工具review-ai_SETUP指南","ja":"AIエージェントreview-aiの設定とベストプラクティス","ko":"AI 에이전트 review-ai 설정 가이드 및 리뷰 프로세스","es":"Guía de Configuración de review-ai: Mejora de la Edición ...","fr":"Guide de Configuration de review-ai : Amélioration de l''É...","de":"Einrichtungsleitfaden für review-ai: Verbesserung der Cod...","pt":"Guia de Configuração do review-ai: Ferramenta de Revisão ...","ru":"Настройка ИИ Агента review-ai: Руководство по проверке кода","ar":"دليل إعداد review-ai: أداة مراجعة الكود"},"description":{"en":"Learn how to review AI-edited code changes with git diff, git status, and Brakeman security checks. Get started with review-ai today!","zh":"使用review-ai AI代码审查工具，确保代码质量和安全性，遵循设置和审查步骤","ja":"review-ai AIエージェントを使用してコードの品質とセキュリティを確保するための設定とレビュー方法","ko":"review-ai AI 에이전트를 사용하여 코드 품질과 보안을 확인하는 설정 및 리뷰 프로세스","es":"Aprende a revisar cambios realizados por un editor de inteligencia artificial con review-ai. Mejora la calidad de tu código con nuestra guía paso a paso","fr":"Découvrez comment réviser les modifications apportées par un éditeur d''intelligence artificielle avec review-ai. Améliorez la qualité de votre code avec notr...","de":"Erfahren Sie, wie Sie Änderungen überprüfen, die von einem KI-Editor mit review-ai vorgenommen wurden. Verbessern Sie die Qualität Ihres Codes mit unserem Sc...","pt":"Aprenda a configurar e utilizar o review-ai para revisar alterações de código feitas por editores de IA","ru":"Узнайте, как настроить и использовать ИИ Агент review-ai для проверки изменений кода, внесенных редакторами ИИ","ar":"تعرف على كيفية إعداد و استخدام review-ai لمراجعة التغييرات في الكود التي قام بها محررات الذكاء الاصطناعي"},"definition":{"en":"review-ai is a skill that enables developers to review and analyze code changes made by AI editors, using tools like git and Brakeman.","zh":"review-ai是一种AI代码审查工具，用于检查和验证AI编辑器的更改","ja":"review-aiはAIエディターの変更をチェックして検証するAIコードレビューツールです","ko":"review-ai는 AI 편집기의 변경을 확인하고 검증하는 AI 코드 리뷰 도구입니다","es":"Review-ai es una herramienta de agente de inteligencia artificial que ayuda a los desarrolladores a revisar y mejorar la calidad de su código","fr":"Review-ai est un outil d''agent d''intelligence artificielle qui aide les développeurs à réviser et améliorer la qualité de leur code","de":"Review-ai ist ein Tool des KI-Agents, das Entwicklern hilft, den Code zu überprüfen und die Qualität zu verbessern","pt":"O review-ai é uma ferramenta de revisão de código que analisa alterações feitas por editores de IA","ru":"ИИ Агент review-ai - это инструмент проверки кода, анализирующий изменения, внесенные редакторами ИИ","ar":"review-ai هو أداة مراجعة الكود التي تحليل التغييرات التي قام بها محررات الذكاء الاصطناعي"},"features":{"en":["Runs git diff and git status -s to identify uncommitted changes","Analyzes code for bugs, logic errors, and security issues like SQL injection and XSS","Checks style consistency with the rest of the codebase","Runs CI checks on changed files using bin/brakeman --no-pager","Reviews new untracked files for completeness and accuracy"],"zh":["使用git diff查看所有未提交的更改","运行CI检查以确保代码质量和安全性","检查代码中的bug和逻辑错误","分析代码风格的一致性和安全性","使用bin/brakeman进行安全性检查"],"ja":["git diffを使用してすべての未コミットの変更を表示","CIチェックを実行してコードの品質とセキュリティを確保","コード内のバグとロジックエラーをチェック","コードのスタイルの一貫性とセキュリティを分析","bin/brakemanを使用してセキュリティチェックを行う"],"ko":["git diff를 사용하여 모든 커밋되지 않은 변경을 표시","CI 체크를 실행하여 코드 품질과 보안을 확인","코드 내의 버그와 논리 오류를 확인","코드 스타일의 일관성과 보안을 분석","bin/brakeman을 사용하여 보안 체크를 수행"],"es":["Revisión de cambios con git diff y git status -s","Análisis de seguridad con Brakeman","Verificación de estilo de código y consistencia","Detección de errores y casos de borde","Ejecución de pruebas de integración continua"],"fr":["Révision des modifications avec git diff et git status -s","Analyse de sécurité avec Brakeman","Vérification du style de code et de la cohérence","Détection des erreurs et des cas de limite","Exécution des tests d''intégration continue"],"de":["Überprüfung von Änderungen mit git diff und git status -s","Sicherheitsanalyse mit Brakeman","Überprüfung des Code-Stils und der Konsistenz","Fehler- und Randfall-Erkennung","Ausführung von kontinuierlichen Integrations-Tests"],"pt":["Análise de alterações de código com git diff e git status -s","Verificação de bugs e erros lógicos","Análise de segurança contra injeção de SQL e XSS","Verificação de consistência de estilo com o restante do código","Execução de verificações de CI com bin/brakeman --no-pager"],"ru":["Анализ изменений кода с помощью git diff и git status -s","Проверка на наличие ошибок и логических ошибок","Анализ безопасности от инъекции SQL и XSS","Проверка согласованности стиля с остальным кодом","Выполнение проверок CI с помощью bin/brakeman --no-pager"],"ar":["تحليل التغييرات في الكود باستخدام git diff و git status -s","فحص الأخطاء والأخطاء المنطقية","تحليل الأمان ضد حقن SQL و XSS","فحص الاتساق في الأساليب مع بقية الكود","تشغيل فحوصات CI باستخدام bin/brakeman --no-pager"]},"keywords":{"en":["how to use review-ai","review-ai setup guide","review-ai vs code review tools","review-ai install","git diff for code review","Brakeman security checks","AI-generated code review","code quality analysis","review-ai alternative"],"zh":["AI代码审查","review-ai","git diff","CI检查","代码质量","代码安全性","AI工具","代码审查工具","开发工具"],"ja":["AIコードレビュー","review-ai","git diff","CIチェック","コード品質","コードセキュリティ","AIエージェント","コードレビューツール","開発ツール"],"ko":["AI 코드 리뷰","review-ai","git diff","CI 체크","코드 품질","코드 보안","AI 에이전트","코드 리뷰 도구","개발 도구"],"es":["review-ai","herramientas de agente de inteligencia artificial","mejora de la edición de código","revisión de cambios","análisis de seguridad","git diff","Brakeman","pruebas de integración continua"],"fr":["review-ai","outils d''agent d''intelligence artificielle","amélioration de l''édition de code","révision des modifications","analyse de sécurité","git diff","Brakeman","tests d''intégration continue"],"de":["review-ai","KI-Tool-Agents","Verbesserung der Codebearbeitung","Überprüfung von Änderungen","Sicherheitsanalyse","git diff","Brakeman","kontinuierliche Integrations-Tests"],"pt":["review-ai","ferramenta de revisão de código","edicao de ia","git diff","git status -s","segurança de código","injeção de sql","xss","verificação de ci"],"ru":["ИИ Агент review-ai","инструмент проверки кода","редакторы ИИ","git diff","git status -s","безопасность кода","инъекция SQL","XSS","проверка CI"],"ar":["review-ai","أداة مراجعة الكود","محررات الذكاء الاصطناعي","git diff","git status -s","أمان الكود","حقن SQL","XSS","فحص CI"]}},"owner":"denis1011101","repo":"getcourt","repoPath":"denis1011101/getcourt","stars":0,"forks":0,"updatedAt":"2026-03-07T18:02:00Z","topics":[],"category":"community","skillMd":{"name":"review-ai","description":"Review changes made by AI editors (Codex, Claude, etc.). Run git diff, lint, security scan, tests, and provide a code review.","bodyPreview":"Review changes made by an AI editor. Follow these steps:\n\n1. Run `git diff` and `git status -s` to see all uncommitted changes (staged, unstaged, and untracked files)\n2. For any new untracked files, read them fully\n3. Analyze every change for:\n   - Bugs or logic errors\n   - Security issues (SQL injection, XSS, etc.)\n   - Style consistency with the rest of the codebase\n   - Missing edge cases\n   - Unnecessary or over-engineered code\n4. Run CI checks on changed files:\n   - `bin/brakeman --no-pager","body":"Review changes made by an AI editor. Follow these steps:\n\n1. Run `git diff` and `git status -s` to see all uncommitted changes (staged, unstaged, and untracked files)\n2. For any new untracked files, read them fully\n3. Analyze every change for:\n   - Bugs or logic errors\n   - Security issues (SQL injection, XSS, etc.)\n   - Style consistency with the rest of the codebase\n   - Missing edge cases\n   - Unnecessary or over-engineered code\n4. Run CI checks on changed files:\n   - `bin/brakeman --no-pager` (scan_ruby: security vulnerabilities)\n   - `bin/importmap audit` (scan_js: JS dependency vulnerabilities)\n   - `bin/rubocop` (lint: code style)\n   - `PARALLEL_WORKERS=0 bin/rails db:test:prepare test test:system` (test: unit/integration/system tests)\n   - For reviews, always run the exact command above to include system tests.\n5. Provide a structured review:\n   - Summary of what changed\n   - CI results (pass/fail for each check)\n   - File-by-file comments (only where there are issues)\n   - Overall verdict: approve / needs fixes\n"},"lastSynced":"2026-03-08T02:14:12.748Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Review Agents needing advanced AI-generated code analysis and security auditing capabilities.","zh":"非常适合需要高级AI生成代码分析和安全审计功能的代码审查代理。","ja":"コードレビュー代理が高度なAI生成コード分析およびセキュリティ監査機能を必要とする場合に最適です。","ko":"고급 AI 생성 코드 분석 및 보안 감사 기능이 필요한 코드 리뷰 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Revisión de Código que necesitan análisis de código generado por IA avanzado y capacidades de auditoría de seguridad.","fr":"Parfait pour les Agents de Revue de Code nécessitant une analyse de code générée par IA avancée et des capacités d''audit de sécurité.","de":"Perfekt für Code-Review-Agenten, die erweiterte KI-generierte Codeanalyse- und Sicherheitsprüfungsfunktionen benötigen.","pt":"Perfeito para Agentes de Revisão de Código que necessitam de análise de código gerada por IA avançada e capacidades de auditoria de segurança.","ru":"Идеально для агентов проверки кода, которым необходимы продвинутые возможности анализа кода, сгенерированного ИИ, и аудита безопасности.","ar":"مثالي لعميل مراجعة الأكواد الذي يحتاج إلى تحليل متقدم للأكواد التي تم إنشاؤها بواسطة الذكاء الاصطناعي وقدرات فحص الأمان."},"recommendation":{"en":"Empowers agents to scrutinize AI-edited code for bugs, security issues like SQL injection and XSS, and style inconsistencies, leveraging tools like git diff and Brakeman for comprehensive review.","zh":"赋予代理审查AI编辑代码的错误、安全问题（如SQL注入和XSS）以及样式不一致，利用git diff和Brakeman等工具进行全面审查。","ja":"エージェントがAI編集コードのバグ、セキュリティの問題（SQLインジェクションやXSSなど）およびスタイルの不一致を調査することを可能にし、git diffやBrakemanなどのツールを利用して包括的なレビューを行う。","ko":"에이전트가 AI 편집 코드의 버그, 보안 문제(예: SQL 인젝션 및 XSS) 및 스타일 불일치를 조사할 수 있도록 하며, git diff 및 Brakeman과 같은 도구를 사용하여 종합적인 검토를 수행합니다.","es":"Habilita a los agentes a examinar el código editado por IA para errores, problemas de seguridad como inyección de SQL y XSS, y inconsistencias de estilo, aprovechando herramientas como git diff y Brakeman para una revisión integral.","fr":"Permet aux agents d''examiner le code édité par IA pour les bogues, les problèmes de sécurité tels que l''injection de SQL et le XSS, et les incohérences de style, en exploitant des outils comme git diff et Brakeman pour une revue complète.","de":"Ermächtigt die Agenten, den von KI bearbeiteten Code auf Fehler, Sicherheitsprobleme wie SQL-Injection und XSS sowie Stilinkonsistenzen zu überprüfen, unter Nutzung von Tools wie git diff und Brakeman für eine umfassende Überprüfung.","pt":"Habilita os agentes a examinar o código editado por IA para bugs, problemas de segurança como injeção SQL e XSS, e inconsistências de estilo, aproveitando ferramentas como git diff e Brakeman para uma revisão abrangente.","ru":"Наделяет агентов возможностью проверять код, отредактированный ИИ, на наличие ошибок, проблем безопасности, таких как внедрение SQL и XSS, и несоответствий стиля, используя инструменты, такие как git diff и Brakeman, для всестороннего обзора.","ar":"يمكن للعميل فحص أكواد تعديل الذكاء الاصطناعي على الأخطاء، ومشاكل الأمان مثل الحقن SQL و XSS، وعدم التماثل في الأسلوب، مستفيداً من أدوات مثل git diff و Brakeman لمراجعة شاملة."},"useCases":{"en":["Debugging AI-generated code for logic errors","Identifying security vulnerabilities in AI-edited files","Enforcing style consistency across the codebase"],"zh":["调试AI生成代码的逻辑错误","识别AI编辑文件中的安全漏洞","强制代码库中的一致性"],"ja":["AI生成コードの論理エラーのデバッグ","AI編集ファイルのセキュリティ脆弱性の特定","コードベース全体のスタイルの一貫性の確保"],"ko":["AI 생성 코드의 논리 오류 디버깅","AI 편집 파일의 보안 취약성 식별","코드베이스 전체의 일관성 적용"],"es":["Depuración de código generado por IA para errores de lógica","Identificación de vulnerabilidades de seguridad en archivos editados por IA","Aplicación de la consistencia de estilo en todo el código"],"fr":["Débogage de code généré par IA pour les erreurs de logique","Identification des vulnérabilités de sécurité dans les fichiers édités par IA","Application de la cohérence de style sur l''ensemble du code"],"de":["Fehlerbehebung von KI-generiertem Code für Logikfehler","Identifizierung von Sicherheitslücken in von KI bearbeiteten Dateien","Durchsetzung von Stilkonsistenz im gesamten Code"],"pt":["Depuração de código gerado por IA para erros lógicos","Identificação de vulnerabilidades de segurança em arquivos editados por IA","Aplicação de consistência de estilo em todo o código"],"ru":["Отладка кода, сгенерированного ИИ, для логических ошибок","Определение уязвимостей безопасности в файлах, отредактированных ИИ","Обеспечение согласованности стиля на всём кодовом базисе"],"ar":["تصحيح أخطاء أكواد تم إنشاؤها بواسطة الذكاء الاصطناعي","تحديد نقاط الضعف في الأمان في الملفات التي تم تعديلها بواسطة الذكاء الاصطناعي","تطبيق الاتساق في الأسلوب عبر كافة أكواد البرنامج"]},"limitations":{"en":["Requires git installation","Limited to codebases with CI checks implemented","Needs Brakeman for security audits"],"zh":["需要git安装","仅限于实现CI检查的代码库","需要Brakeman进行安全审计"],"ja":["gitのインストールが必要","CIチェックを実装したコードベースのみ","セキュリティ監査にはBrakemanが必要"],"ko":["git 설치가 필요합니다.","CI 체크가 구현된 코드베이스만 해당","보안 감사에는 Brakeman이 필요합니다."],"es":["Requiere la instalación de git","Limitado a codebases con controles de CI implementados","Necesita Brakeman para auditorías de seguridad"],"fr":["Nécessite l''installation de git","Limité aux bases de code avec des vérifications de CI mises en œuvre","Nécessite Brakeman pour les audits de sécurité"],"de":["Erfordert die Installation von git","Begrenzt auf Codebases mit implementierten CI-Prüfungen","Benötigt Brakeman für Sicherheitsaudits"],"pt":["Requer instalação do git","Limitado a codebases com verificações de CI implementadas","Necessita de Brakeman para auditorias de segurança"],"ru":["Требует установки git","Ограничен для кодовых баз с реализованными проверками CI","Требует Brakeman для аудита безопасности"],"ar":["يتطلب تثبيت git","محدود بالكود الذي تم تطبيق فحص CI عليه","يحتاج إلى Brakeman لأداء فحص الأمان"]},"version":4},"contentHash":"a98010863f0c9ed6b0e83685c25525d20402cdb31e8acd94c1ac71b0d32b9646","qualityScore":23}');
