INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('denis1011101/getcourt/review-ai', 'review-ai', 'denis1011101', 'getcourt', 'community', 'review-ai denis1011101 getcourt community The review-ai skill helps developers review changes made by AI editors, ensuring code quality and security. It benefits developers working with AI-generated code. review-ai是用于审查AI编辑器更改的工具，通过git diff和CI检查来确保代码质量和安全性 review-aiはAIエディターの変更をレビューするツールで、git diffとCIチェックを使用してコードの品質とセキュリティを確保します review-ai는 AI 편집기의 변경을審查하는 도구로, git diff와 CI 체크를 통해 코드 품질과 보안을 확인합니다 Review-ai es una herramienta que ayuda a revisar cambios realizados por un editor de inteligencia artificial. Sigue estos pasos para mejorar la calidad de tu código Review-ai est un outil qui aide à réviser les modifications apportées par un éditeur d''intelligence artificielle. Suivez ces étapes pour améliorer la qualité de votre code Review-ai ist ein Tool, das dabei hilft, Änderungen zu überprüfen, die von einem KI-Editor vorgenommen wurden. Befolgen Sie diese Schritte, um die Qualität Ihres Codes zu verbessern O review-ai é uma ferramenta de revisão de código que ajuda a garantir a qualidade do código alterado por editores de IA. ИИ Агент review-ai - это инструмент проверки кода, помогающий обеспечить качество кода, измененного редакторами ИИ. review-ai هو أداة مراجعة الكود التي تساعد على ضمان جودة الكود الذي تم تغييره بواسطة محررات الذكاء الاصطناعي. how to use review-ai review-ai setup guide review-ai vs code review tools review-ai install git diff for code review Brakeman security checks AI-generated code review code quality analysis review-ai alternative AI代码审查 review-ai git diff CI检查 代码质量 代码安全性 AI工具 代码审查工具 开发工具 Runs git diff and git status -s to identify uncommitted changes Analyzes code for bugs, logic errors, and security issues like SQL injection and XSS Checks style consistency with the rest of the codebase Runs CI checks on changed files using bin/brakeman --no-pager Reviews new untracked files for completeness and accuracy review-ai is a skill that enables developers to review and analyze code changes made by AI editors, using tools like git and Brakeman.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('go-go-golems/docmgr/cursor-remarkable-upload', 'community', 'go-go-golems', 'docmgr', 'go-go-golems/docmgr', 'cursor-remarkable-upload', 9, 3, 23, '2026-02-13T16:44:12Z', '2026-03-06T06:48:01.034Z', '0c03c8e310a19a3e17fe91c1893eaa02fb4d46c227c65ba88492beb026ca13df', '{"id":"go-go-golems/docmgr/cursor-remarkable-upload","name":"cursor-remarkable-upload","description":{"en":"cursor-remarkable-upload is a skill that enables safe conversion of .md files to .pdf and uploads them to reMarkable devices, defaulting to dry-runs and avoiding overwrites, benefiting developers and users alike.","zh":"cursor-remarkable-upload 是一个将 Markdown 文件转换为 PDF 并上传到 reMarkable 设备的工具，支持安全转换和默认 dry-run 模式","ja":"cursor-remarkable-upload は、Markdown ファイルを PDF に変換し、reMarkable デバイスにアップロードするツールです。安全な変換と dry-run モードをサポートしています","ko":"cursor-remarkable-upload는 Markdown 파일을 PDF로 변환하고 reMarkable 디바이스에 업로드하는 도구입니다. 안전한 변환과 기본 dry-run 모드를 지원합니다","es":"Cursor-remarkable-upload es una herramienta que convierte archivos markdown en pdf y los sube a un dispositivo reMarkable, con funciones de seguridad como dry-run y evitación de sobrescrituras","fr":"Cursor-remarkable-upload est un outil qui convertit des fichiers markdown en pdf et les télécharge sur un appareil reMarkable, avec des fonctions de sécurité comme dry-run et évitement d''écrasement","de":"Cursor-remarkable-upload ist ein Tool, das Markdown-Dateien in pdf umwandelt und auf ein reMarkable-Gerät hochlädt, mit Sicherheitsfunktionen wie dry-run und Vermeidung von Überschreibungen","pt":"O cursor-remarkable-upload é uma ferramenta que converte arquivos .md em .pdf e faz upload para dispositivos reMarkable de forma segura, utilizando tecnologias como rmapi, pandoc e xelatex","ru":"ИИ Агент cursor-remarkable-upload - это инструмент, который преобразует файлы .md в .pdf и загружает их на устройства reMarkable, используя технологии rmapi, pandoc и xelatex","ar":"أداة cursor-remarkable-upload هي أداة تحويل الملفات من .md إلى .pdf ورفعها إلى أجهزة reMarkable بشكل آمن، باستخدام تقنيات مثل rmapi وpandoc وxelatex"},"seo":{"title":{"en":"cursor-remarkable-upload: Safely Convert MD to PDF for re...","zh":"cursor-remarkable-upload Setup Guide - AI工具","ja":"cursor-remarkable-upload の設定方法 - AIエージェント","ko":"cursor-remarkable-upload 설정 가이드 - AI 에이전트","es":"Guía de configuración de cursor-remarkable-upload para su...","fr":"Configurer cursor-remarkable-upload pour uploader des fic...","de":"Einrichtungsanleitung für cursor-remarkable-upload zum Ho...","pt":"Guia de Configuração do cursor-remarkable-upload para Des...","ru":"Настройка ИИ Агента cursor-remarkable-upload: Руководство","ar":"إعداد أداة cursor-remarkable-upload للتحويل الآمن إلى PDF"},"description":{"en":"Discover how to use cursor-remarkable-upload to convert Markdown files to PDF and upload to reMarkable devices securely. Learn more and get started today!","zh":"使用 cursor-remarkable-upload 将 Markdown 文件安全转换为 PDF 并上传到 reMarkable 设备，了解更多设置和使用方法","ja":"cursor-remarkable-upload を使用して Markdown ファイルを安全に PDF に変換し、reMarkable デバイスにアップロードする方法","ko":"cursor-remarkable-upload를 사용하여 Markdown 파일을 안전하게 PDF로 변환하고 reMarkable 디바이스에 업로드하는 방법","es":"Aprende a utilizar cursor-remarkable-upload para subir archivos markdown a tu dispositivo reMarkable de manera segura y eficiente","fr":"Découvrez comment utiliser cursor-remarkable-upload pour uploader des fichiers markdown sur votre appareil reMarkable de manière sûre et efficace","de":"Erfahren Sie, wie Sie cursor-remarkable-upload verwenden, um Markdown-Dateien auf Ihr reMarkable-Gerät sicher und effizient hochzuladen","pt":"Aprenda a configurar o cursor-remarkable-upload para converter arquivos .md em .pdf e fazer upload para dispositivos reMarkable de forma segura","ru":"Узнайте, как настроить ИИ Агент cursor-remarkable-upload для безопасного преобразования файлов .md в .pdf и загрузки на устройства reMarkable","ar":"اكتشف كيفية إعداد أداة cursor-remarkable-upload لتحويل الملفات من .md إلى .pdf ورفعها إلى أجهزة reMarkable بشكل آمن"},"definition":{"en":"cursor-remarkable-upload is a technical skill that facilitates the conversion of Markdown files to PDF and uploads them to reMarkable devices using tools like rmapi, pandoc, and xelatex.","zh":"cursor-remarkable-upload 是一个 AI 工具，用于将 Markdown 文件转换为 PDF 并上传到 reMarkable 设备","ja":"cursor-remarkable-upload は、Markdown ファイルを PDF に変換し、reMarkable デバイスにアップロードする AI エージェントです","ko":"cursor-remarkable-upload는 Markdown 파일을 PDF로 변환하고 reMarkable 디바이스에 업로드하는 AI 에이전트입니다","es":"Cursor-remarkable-upload es una herramienta de línea de comandos que permite subir archivos markdown a un dispositivo reMarkable","fr":"Cursor-remarkable-upload est un outil en ligne de commande qui permet de télécharger des fichiers markdown sur un appareil reMarkable","de":"Cursor-remarkable-upload ist ein Kommandozeilen-Tool, das das Hochladen von Markdown-Dateien auf ein reMarkable-Gerät ermöglicht","pt":"O cursor-remarkable-upload é uma ferramenta de linha de comando que converte arquivos .md em .pdf e faz upload para dispositivos reMarkable","ru":"ИИ Агент cursor-remarkable-upload - это командная утилита, которая преобразует файлы .md в .pdf и загружает их на устройства reMarkable","ar":"أداة cursor-remarkable-upload هي أداة سطر الأوامر التي تحول الملفات من .md إلى .pdf وترفعها إلى أجهزة reMarkable"},"features":{"en":["Converts .md files to .pdf using pandoc and xelatex","Uploads converted PDF files to reMarkable devices via rmapi","Defaults to dry-runs to avoid accidental overwrites","Supports absolute paths for choosing markdown files","Utilizes python3 for execution, specifically remarkable_upload.py"],"zh":["支持 Markdown 到 PDF 的安全转换","默认 dry-run 模式，避免覆盖现有文件","使用 Python 脚本进行上传","支持 rmapi、pandoc 和 xelatex 依赖","可选择多个 Markdown 文件进行上传","使用绝对路径选择 Markdown 文件"],"ja":["Markdown から PDF への安全な変換をサポート","デフォルトの dry-run モードで、既存のファイルを上書きしない","Python スクリプトを使用してアップロード","rmapi、pandoc、xelatex 依存関係をサポート","複数の Markdown ファイルをアップロードできる","絶対パスを使用して Markdown ファイルを選択"],"ko":["Markdown를 PDF로 안전하게 변환하는 기능을 지원","기본 dry-run 모드로 기존 파일을 덮어쓰지 않음","Python 스크립트를 사용하여 업로드","rmapi, pandoc, xelatex 종속성을 지원","여러 개의 Markdown 파일을 업로드할 수 있음","절대 경로를 사용하여 Markdown 파일을 선택"],"es":["Conversión de archivos markdown en pdf","Subida segura a dispositivos reMarkable","Función de dry-run para pruebas","Evitación de sobrescrituras de archivos","Compatibilidad con herramientas como rmapi, pandoc y xelatex","Uso de Python 3 para la ejecución"],"fr":["Conversion de fichiers markdown en pdf","Téléchargement sécurisé sur les appareils reMarkable","Fonction de dry-run pour les tests","Évitement d''écrasement de fichiers","Compatibilité avec des outils tels que rmapi, pandoc et xelatex","Utilisation de Python 3 pour l''exécution"],"de":["Umwandlung von Markdown-Dateien in pdf","Sicheres Hochladen auf reMarkable-Geräte","Dry-run-Funktion für Tests","Vermeidung von Überschreibungen von Dateien","Kompatibilität mit Tools wie rmapi, pandoc und xelatex","Verwendung von Python 3 für die Ausführung"],"pt":["Conversão segura de arquivos .md em .pdf","Upload para dispositivos reMarkable","Utilização de tecnologias como rmapi, pandoc e xelatex","Modo de teste (dry-run) para evitar sobrescrita de arquivos","Suporte a arquivos com caminhos absolutos"],"ru":["Безопасное преобразование файлов .md в .pdf","Загрузка на устройства reMarkable","Использование технологий rmapi, pandoc и xelatex","Тестовый режим (dry-run) для предотвращения перезаписи файлов","Поддержка файлов с абсолютными путями"],"ar":["تحويل ملفات .md إلى .pdf بشكل آمن","رفع الملفات إلى أجهزة reMarkable","استخدام تقنيات مثل rmapi وpandoc وxelatex","وضع الاختبار (dry-run) لتجنب كتابة ملفات متعددة","دعم الملفات ذات المسارات المbsolute"]},"keywords":{"en":["how to use cursor-remarkable-upload","cursor-remarkable-upload alternative","convert md to pdf for reMarkable","cursor-remarkable-upload setup guide","what is cursor-remarkable-upload","rmapi and pandoc integration"],"zh":["cursor-remarkable-upload","AI 工具","Markdown 到 PDF","reMarkable 设备","Python 脚本","rmapi","pandoc","xelatex","安全转换","dry-run 模式"],"ja":["cursor-remarkable-upload","AI エージェント","Markdown から PDF","reMarkable デバイス","Python スクリプト","rmapi","pandoc","xelatex","安全な変換","dry-run モード"],"ko":["cursor-remarkable-upload","AI 에이전트","Markdown를 PDF로","reMarkable 디바이스","Python 스크립트","rmapi","pandoc","xelatex","안전한 변환","dry-run 모드"],"es":["cursor-remarkable-upload","subir markdown a reMarkable","herramientas de línea de comandos","conversión de markdown a pdf","rmapi","pandoc","xelatex","Python 3"],"fr":["cursor-remarkable-upload","télécharger des fichiers markdown sur reMarkable","outils en ligne de commande","conversion de markdown en pdf","rmapi","pandoc","xelatex","Python 3"],"de":["cursor-remarkable-upload","Markdown-Dateien auf reMarkable hochladen","Kommandozeilen-Tools","Umwandlung von Markdown in pdf","rmapi","pandoc","xelatex","Python 3"],"pt":["cursor-remarkable-upload","conversão de arquivos","upload para reMarkable","rmapi","pandoc","xelatex","desenvolvedores","ferramentas de linha de comando"],"ru":["ИИ Агент cursor-remarkable-upload","преобразование файлов","загрузка на reMarkable","rmapi","pandoc","xelatex","разработчики","командные утилиты"],"ar":["أداة cursor-remarkable-upload","تحويل الملفات","رفع الملفات إلى reMarkable","rmapi","pandoc","xelatex","مطورون","أدوات سطر الأوامر"]}},"owner":"go-go-golems","repo":"docmgr","repoPath":"go-go-golems/docmgr","stars":9,"forks":3,"updatedAt":"2026-02-13T16:44:12Z","topics":[],"category":"community","skillMd":{"name":"cursor-remarkable-upload","description":"Upload markdown (including docmgr ticket docs) to a reMarkable device as PDF via a local uploader script, with a safe dry-run and optional mirroring of ticket structure. Use when the user asks to send docs to reMarkable, export markdown to PDF for reMarkable, or troubleshoot rmapi/pandoc/xelatex.","bodyPreview":"# Cursor Remarkable Upload\n\n## Overview\n\nSafely convert `.md` to `.pdf` and upload to a reMarkable device, defaulting to dry-runs and avoiding overwrites.\n\n## Preconditions\n\n1. Confirm uploader exists: `python3 /home/manuel/.local/bin/remarkable_upload.py --help`\n2. Confirm dependencies if needed: `rmapi`, `pandoc`, `xelatex`\n\n## Workflow (safe default)\n\n1. Choose markdown file(s) (use absolute paths).\n2. Dry-run:\n   - `python3 /home/manuel/.local/bin/remarkable_upload.py --dry-run /abs/path/to/","body":"# Cursor Remarkable Upload\n\n## Overview\n\nSafely convert `.md` to `.pdf` and upload to a reMarkable device, defaulting to dry-runs and avoiding overwrites.\n\n## Preconditions\n\n1. Confirm uploader exists: `python3 /home/manuel/.local/bin/remarkable_upload.py --help`\n2. Confirm dependencies if needed: `rmapi`, `pandoc`, `xelatex`\n\n## Workflow (safe default)\n\n1. Choose markdown file(s) (use absolute paths).\n2. Dry-run:\n   - `python3 /home/manuel/.local/bin/remarkable_upload.py --dry-run /abs/path/to/doc.md`\n3. Upload (no overwrite):\n   - `python3 /home/manuel/.local/bin/remarkable_upload.py /abs/path/to/doc.md`\n4. Only if explicitly requested: overwrite with `--force`.\n\n## Ticket-aware uploads\n- Prefer mirroring ticket structure to avoid name collisions; see `references/remarkable.md`.\n\n## Reference\n- Full usage + troubleshooting: `references/remarkable.md`.\n"},"lastSynced":"2026-03-06T06:48:01.034Z","agentAnalysis":{"suitability":{"en":"Perfect for Document Processing Agents needing safe conversion and upload of markdown files to reMarkable devices.","zh":"适用于需要安全转换和上传markdown文件到reMarkable设备的文档处理代理。","ja":"reMarkableデバイスへのマークダウンファイルの安全な変換およびアップロードを必要とするドキュメント処理エージェントに適しています。","ko":"reMarkable 기기에 마크다운 파일을 안전하게 변환 및 업로드해야 하는 문서 처리 에이전트에 적합합니다.","es":"Perfecto para Agentes de Procesamiento de Documentos que necesitan una conversión y carga seguras de archivos markdown en dispositivos reMarkable.","fr":"Parfait pour les Agents de Traitement de Documents ayant besoin d''une conversion et d''un téléchargement sécurisés de fichiers markdown sur les appareils reMarkable.","de":"Perfekt für Dokumentenverarbeitungsagenten, die eine sichere Konvertierung und Hochladung von Markdown-Dateien auf reMarkable-Geräte benötigen.","pt":"Perfeito para Agentes de Processamento de Documentos que necessitam de conversão segura e upload de arquivos markdown para dispositivos reMarkable.","ru":"Идеально подходит для агентов обработки документов, которым требуется безопасное преобразование и загрузка файлов markdown на устройства reMarkable.","ar":"مثالي لوكلاء معالجة الوثائق الذين يحتاجون إلى تحويل آمن ورفع ملفات markdown إلى أجهزة reMarkable."},"recommendation":{"en":"Empowers agents to convert .md files to .pdf using pandoc and xelatex, and upload them to reMarkable devices via rmapi, while avoiding overwrites and defaulting to dry-runs for safe testing.","zh":"赋予代理使用pandoc和xelatex将.md文件转换为.pdf，并通过rmapi上传到reMarkable设备，同时避免覆盖并默认为安全测试的dry-runs模式。","ja":"pandocとxelatexを使用して.mdファイルを.pdfに変換し、rmapi経由でreMarkableデバイスにアップロードすることをエージェントに可能にし、上書きを避け、安全なテストのためにdry-runsモードをデフォルトにします。","ko":"에이전트가 pandoc와 xelatex를 사용하여 .md 파일을 .pdf로 변환하고 rmapi를 통해 reMarkable 기기에 업로드할 수 있도록 하며, 덮어쓰기를 피하고 안전한 테스트를 위한 dry-runs 모드를 기본값으로 설정합니다.","es":"Habilita a los agentes a convertir archivos .md a .pdf utilizando pandoc y xelatex, y a subirlos a dispositivos reMarkable a través de rmapi, evitando sobrescrituras y configurando de forma predeterminada pruebas de secado para una prueba segura.","fr":"Permet aux agents de convertir des fichiers .md en .pdf en utilisant pandoc et xelatex, et de les télécharger sur les appareils reMarkable via rmapi, tout en évitant les écrasements et en configurant par défaut des tests de simulation pour un test sécurisé.","de":"Ermächtigt Agenten, .md-Dateien mit pandoc und xelatex in .pdf umzuwandeln und sie über rmapi auf reMarkable-Geräte hochzuladen, während sie Überschreibungen vermeiden und standardmäßig Trockentests für sichere Tests durchführen.","pt":"Habilita os agentes a converter arquivos .md para .pdf usando pandoc e xelatex, e carregá-los em dispositivos reMarkable via rmapi, evitando sobrescritas e usando o modo de teste seco para testes seguros.","ru":"Позволяет агентам преобразовывать файлы .md в .pdf с помощью pandoc и xelatex, а также загружать их на устройства reMarkable через rmapi, избегая перезаписи и используя режим сухого запуска для безопасного тестирования.","ar":"يسمح للوكلاء بتحويل الملفات .md إلى .pdf باستخدام pandoc و xelatex، ورفعها إلى أجهزة reMarkable من خلال rmapi، مع تجنب الكتابة فوقها وافتراض تشغيل اختباري جاف لاختبارات آمنة."},"useCases":{"en":["Converting markdown documents to PDF for e-reading","Uploading notes and documents to reMarkable devices for offline access","Automating document conversion and upload workflows"],"zh":["将markdown文档转换为PDF用于电子阅读","将笔记和文档上传到reMarkable设备以实现离线访问","自动化文档转换和上传工作流"],"ja":["マークダウン文書を電子書籍としてPDFに変換する","reMarkableデバイスにノートや文書をアップロードしてオフラインでアクセスする","文書の変換およびアップロードのワークフローを自動化する"],"ko":["마크다운 문서를 전자책으로 PDF로 변환하기","reMarkable 기기에 노트와 문서를 업로드하여 오프라인에서 액세스하기","문서 변환 및 업로드 워크플로 자동화"],"es":["Conversión de documentos markdown a PDF para lectura electrónica","Carga de notas y documentos en dispositivos reMarkable para acceso sin conexión","Automatización de flujos de trabajo de conversión y carga de documentos"],"fr":["Conversion de documents markdown en PDF pour lecture électronique","Téléchargement de notes et de documents sur les appareils reMarkable pour un accès hors ligne","Automatisation des flux de travail de conversion et de téléchargement de documents"],"de":["Konvertierung von Markdown-Dokumenten in PDF für elektronisches Lesen","Hochladen von Notizen und Dokumenten auf reMarkable-Geräte für den Offline-Zugriff","Automatisierung von Dokumentenkonvertierungs- und Upload-Workflows"],"pt":["Converter documentos markdown para PDF para leitura eletrônica","Carregar notas e documentos em dispositivos reMarkable para acesso offline","Automatizar fluxos de trabalho de conversão e upload de documentos"],"ru":["Преобразование документов markdown в PDF для чтения электронных книг","Загрузка заметок и документов на устройства reMarkable для доступа в автономном режиме","Автоматизация рабочих процессов преобразования и загрузки документов"],"ar":["تحويل وثائق markdown إلى PDF للقراءة الإلكترونية","تحميل الملاحظات والوثائق إلى أجهزة reMarkable للوصول دون اتصال","تأطير سير عمل تحويل وثائق ورفعها تلقائيًا"]},"limitations":{"en":["Requires rmapi, pandoc, and xelatex dependencies","Limited to uploading to reMarkable devices","Default dry-run mode may require manual confirmation for actual uploads"],"zh":["需要rmapi、pandoc和xelatex依赖","仅限上传到reMarkable设备","默认的dry-run模式可能需要手动确认实际上传"],"ja":["rmapi、pandoc、xelatexの依存関係が必要","reMarkableデバイスへのアップロードのみ","デフォルトのdry-runsモードでは実際のアップロードのために手動での確認が必要になる場合がある"],"ko":["rmapi, pandoc, xelatex 종속성이 필요함","reMarkable 기기에 업로드하는 것만 가능","기본 dry-runs 모드에서는 실제 업로드를 위해 수동 확인이 필요할 수 있음"],"es":["Requiere dependencias de rmapi, pandoc y xelatex","Limitado a la carga en dispositivos reMarkable","El modo de prueba de secado predeterminado puede requerir confirmación manual para cargas reales"],"fr":["Nécessite des dépendances rmapi, pandoc et xelatex","Limité au téléchargement sur les appareils reMarkable","Le mode d''essai de simulation par défaut peut nécessiter une confirmation manuelle pour des téléchargements réels"],"de":["Benötigt rmapi-, pandoc- und xelatex-Abhängigkeiten","Begrenzt auf das Hochladen auf reMarkable-Geräte","Der standardmäßige Trockentestmodus kann eine manuelle Bestätigung für tatsächliche Uploads erfordern"],"pt":["Requer dependências rmapi, pandoc e xelatex","Limitado ao upload para dispositivos reMarkable","O modo de teste seco padrão pode exigir confirmação manual para uploads reais"],"ru":["Требует зависимостей rmapi, pandoc и xelatex","Ограничен загрузкой на устройства reMarkable","Режим сухого запуска по умолчанию может требовать ручного подтверждения для фактических загрузок"],"ar":["يتطلب تبعيات rmapi و pandoc و xelatex","محدود بالتحميل إلى أجهزة reMarkable","يمكن أن يتطلب وضع الاختبار الجاف الافتراضي تأكيدًا يدويًا للتحميلات الفعلية"]},"version":4},"contentHash":"0c03c8e310a19a3e17fe91c1893eaa02fb4d46c227c65ba88492beb026ca13df","qualityScore":23}');
