INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('go-go-golems/docmgr/cursor-remarkable-upload', 'cursor-remarkable-upload', 'go-go-golems', 'docmgr', 'community', 'cursor-remarkable-upload go-go-golems docmgr community cursor-remarkable-upload is a skill that enables safe conversion of .md files to .pdf and uploads them to reMarkable devices, defaulting to dry-runs and avoiding overwrites, benefiting developers and users alike. cursor-remarkable-upload 是一个将 Markdown 文件转换为 PDF 并上传到 reMarkable 设备的工具，支持安全转换和默认 dry-run 模式 cursor-remarkable-upload は、Markdown ファイルを PDF に変換し、reMarkable デバイスにアップロードするツールです。安全な変換と dry-run モードをサポートしています cursor-remarkable-upload는 Markdown 파일을 PDF로 변환하고 reMarkable 디바이스에 업로드하는 도구입니다. 안전한 변환과 기본 dry-run 모드를 지원합니다 Cursor-remarkable-upload es una herramienta que convierte archivos markdown en pdf y los sube a un dispositivo reMarkable, con funciones de seguridad como dry-run y evitación de sobrescrituras Cursor-remarkable-upload est un outil qui convertit des fichiers markdown en pdf et les télécharge sur un appareil reMarkable, avec des fonctions de sécurité comme dry-run et évitement d''écrasement Cursor-remarkable-upload ist ein Tool, das Markdown-Dateien in pdf umwandelt und auf ein reMarkable-Gerät hochlädt, mit Sicherheitsfunktionen wie dry-run und Vermeidung von Überschreibungen O cursor-remarkable-upload é uma ferramenta que converte arquivos .md em .pdf e faz upload para dispositivos reMarkable de forma segura, utilizando tecnologias como rmapi, pandoc e xelatex ИИ Агент cursor-remarkable-upload - это инструмент, который преобразует файлы .md в .pdf и загружает их на устройства reMarkable, используя технологии rmapi, pandoc и xelatex أداة cursor-remarkable-upload هي أداة تحويل الملفات من .md إلى .pdf ورفعها إلى أجهزة reMarkable بشكل آمن، باستخدام تقنيات مثل rmapi وpandoc وxelatex how to use cursor-remarkable-upload cursor-remarkable-upload alternative convert md to pdf for reMarkable cursor-remarkable-upload setup guide what is cursor-remarkable-upload rmapi and pandoc integration cursor-remarkable-upload AI 工具 Markdown 到 PDF reMarkable 设备 Python 脚本 rmapi pandoc xelatex 安全转换 dry-run 模式 Converts .md files to .pdf using pandoc and xelatex Uploads converted PDF files to reMarkable devices via rmapi Defaults to dry-runs to avoid accidental overwrites Supports absolute paths for choosing markdown files Utilizes python3 for execution, specifically remarkable_upload.py cursor-remarkable-upload is a technical skill that facilitates the conversion of Markdown files to PDF and uploads them to reMarkable devices using tools like rmapi, pandoc, and xelatex.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('pockfojoh/alumnos/pest-testing', 'community', 'pockfojoh', 'alumnos', 'pockfojoh/alumnos', 'pest-testing', 0, 0, 23, '2026-03-07T12:46:33.690Z', '2026-03-07T13:00:41.874Z', '05bb6cfd7acdeeaa3c2b2317ed71bb6fe329eafd204a072cfced0157e6ebd473', '{"id":"pockfojoh/alumnos/pest-testing","name":"pest-testing","description":{"en":"Pest-Testing is a skill that helps developers create and manage tests for their applications. It benefits developers by providing a streamlined testing workflow.","zh":"Pest Testing是用于创建和管理测试的工具，支持Pest 3模式和php artisan make:test","ja":"Pest Testingはテストの作成と管理に使用されるツールで、Pest 3パターンとphp artisan make:testをサポート","ko":"Pest Testing은 테스트 생성 및 관리에 사용되는 도구로 Pest 3 패턴 및 php artisan make:test를 지원","es":"Pest Testing es una herramienta para crear y depurar pruebas de unidad y características en proyectos de desarrollo","fr":"Pest Testing est un outil pour créer et déboguer des tests d''unités et de fonctionnalités dans les projets de développement","de":"Pest Testing ist ein Tool zur Erstellung und Fehlerbehebung von Einheits- und Funktionsprüfungen in Entwicklungsprojekten","pt":"O Pest-Testing é uma ferramenta para criar e gerenciar testes de unidade e recursos de forma eficiente","ru":"Pest-Testing - это инструмент для создания и управления юнит-тестами и функциональными тестами","ar":"اختبار الحشرات هو أداة لإنشاء وإدارة اختبارات الوحدات والموارد بفعالية"},"seo":{"title":{"en":"Pest-Testing: Automated Test Setup Guide | AI Agent Skill","zh":"Pest Testing Setup Guide - AIエージェント工具","ja":"Pest Testing Best Practices - AIエージェント","ko":"Pest Testing 구축 가이드 - AI 에이전트","es":"Guía de configuración de Pest Testing para desarrolladores","fr":"Guide de mise en place de Pest Testing pour les développeurs","de":"Einrichtungsleitfaden für Pest Testing für Entwickler","pt":"Guia de Configuração do Pest-Testing para Desenvolvedores","ru":"Настройка ИИ Агентов для Pest-Testing: Руководство","ar":"دليل إعداد اختبار الحشرات باستخدام أدوات الذكاء الاصطناعي"},"description":{"en":"Discover how to streamline your testing workflow with Pest-Testing. Learn how to create, modify, and debug tests with ease. Get started now!","zh":"了解Pest Testing的基本用法和文档，使用Pest 3模式和php artisan make:test创建测试","ja":"Pest Testingの基本的な使い方とドキュメントを学び、Pest 3パターンとphp artisan make:testを使用してテストを作成する","ko":"Pest Testing의 기본 사용법과 문서를 학습하고 Pest 3 패턴 및 php artisan make:test를 사용하여 테스트를 생성","es":"Aprende a utilizar Pest Testing para crear y depurar pruebas de unidad y características en tu proyecto de desarrollo","fr":"Découvrez comment utiliser Pest Testing pour créer et déboguer des tests d''unités et de fonctionnalités dans votre projet de développement","de":"Erfahren Sie, wie Sie Pest Testing verwenden können, um Einheit- und Funktionsprüfungen in Ihrem Entwicklungsprojekt zu erstellen und zu debuggen","pt":"Aprenda a configurar e utilizar o Pest-Testing para melhorar a eficiência dos seus testes de unidade e recursos","ru":"Узнайте, как настроить и использовать Pest-Testing для повышения эффективности ваших юнит-тестов и функциональных тестов с помощью ИИ Агентов","ar":"تعرف على كيفية إعداد وتشغيل اختبار الحشرات لتحسين كفاءة اختبارات الوحدات والموارد باستخدام أدوات الذكاء الاصطناعي"},"definition":{"en":"Pest-testing is a testing framework that allows developers to write and organize tests using the Pest syntax.","zh":"Pest Testing是一种测试工具，用于创建和管理测试，支持Pest 3模式","ja":"Pest Testingはテストツールの一種で、テストの作成と管理に使用され、Pest 3パターンをサポート","ko":"Pest Testing은 테스트 도구의 일종으로 테스트 생성 및 관리에 사용되며 Pest 3 패턴을 지원","es":"Pest Testing es una herramienta de pruebas que utiliza PHP y Pest para crear y depurar pruebas de unidad y características","fr":"Pest Testing est un outil de test qui utilise PHP et Pest pour créer et déboguer des tests d''unités et de fonctionnalités","de":"Pest Testing ist ein Testtool, das PHP und Pest verwendet, um Einheits- und Funktionsprüfungen zu erstellen und zu debuggen","pt":"Pest-Testing é uma técnica de teste que utiliza a ferramenta Pest para criar e executar testes de unidade e recursos","ru":"Pest-Testing - это техника тестирования, использующая инструмент Pest для создания и выполнения юнит-тестов и функциональных тестов","ar":"اختبار الحشرات هي تقنية اختبار تستخدم أداة الحشرات لإنشاء وتشغيل اختبارات الوحدات والموارد"},"features":{"en":["Creates tests using the `php artisan make:test --pest {name}` command","Organizes tests in the `tests/Feature` directory","Supports debugging test failures and modifying existing tests","Enables writing architecture tests using Pest 3 patterns","Integrates with `search-docs` for detailed documentation and patterns"],"zh":["支持Pest 3模式","使用php artisan make:test创建测试","测试组织和管理","支持数据集、模拟和测试组织","支持架构测试"],"ja":["Pest 3パターンをサポート","php artisan make:testを使用してテストを作成","テストの組織と管理","データセット、モック、テスト組織をサポート","アーキテクチャテストをサポート"],"ko":["Pest 3 패턴 지원","php artisan make:test를 사용하여 테스트 생성","테스트 조직 및 관리","데이터셋, 모의, 테스트 조직 지원","아키텍처 테스트 지원"],"es":["Creación de pruebas de unidad y características con Pest","Depuración de pruebas con PHP y Pest","Organización de pruebas en el directorio ''tests/Feature''","Uso de ''php artisan make:test --pest'' para crear pruebas","Compatibilidad con datasets y mocking para pruebas"],"fr":["Création de tests d''unités et de fonctionnalités avec Pest","Débogage de tests avec PHP et Pest","Organisation de tests dans le répertoire ''tests/Feature''","Utilisation de ''php artisan make:test --pest'' pour créer des tests","Compatibilité avec les datasets et le mocking pour les tests"],"de":["Erstellung von Einheits- und Funktionsprüfungen mit Pest","Fehlerbehebung von Prüfungen mit PHP und Pest","Organisation von Prüfungen im Verzeichnis ''tests/Feature''","Verwendung von ''php artisan make:test --pest'' zur Erstellung von Prüfungen","Kompatibilität mit Daten und Mocking für Prüfungen"],"pt":["Criação de testes de unidade e recursos com Pest","Organização de testes em pastas de recursos","Utilização de datasets e mocking para testes","Escrita de testes de arquitetura com Pest"],"ru":["Создание юнит-тестов и функциональных тестов с помощью Pest","Организация тестов в папках функций","Использование наборов данных и макирования для тестов","Написание тестов архитектуры с помощью Pest"],"ar":["إنشاء اختبارات الوحدات والموارد باستخدام أداة الحشرات","تنظيم الاختبارات في مجلدات الموارد","استخدام مجموعات البيانات والتقليد للاختبارات","كتابة اختبارات الهياكل باستخدام أداة الحشرات"]},"keywords":{"en":["how to use pest-testing","pest-testing setup guide","pest-testing vs phpunit","pest-testing install","what is pest-testing","pest-testing alternative","pest-testing tutorial","pest-testing best practices","pest-testing for laravel"],"zh":["Pest Testing","AIエージェント工具","php artisan make:test","Pest 3模式","测试工具","测试管理","数据集","模拟","测试组织"],"ja":["Pest Testing","AIエージェント","php artisan make:test","Pest 3パターン","テストツール","テスト管理","データセット","モック","テスト組織"],"ko":["Pest Testing","AI 에이전트","php artisan make:test","Pest 3 패턴","테스트 도구","테스트 관리","데이터셋","모의","테스트 조직"],"es":["Pest Testing","pruebas de unidad","pruebas de características","PHP","Pest","depuración de pruebas","creación de pruebas","herramientas de pruebas","desarrollo de software"],"fr":["Pest Testing","tests d''unités","tests de fonctionnalités","PHP","Pest","débogage de tests","création de tests","outils de test","développement de logiciels"],"de":["Pest Testing","Einheitsprüfungen","Funktionsprüfungen","PHP","Pest","Fehlerbehebung von Prüfungen","Erstellung von Prüfungen","Testtools","Software-Entwicklung"],"pt":["Pest-Testing","testes de unidade","testes de recursos","ferramenta Pest","desenvolvimento de software","testes automatizados"],"ru":["Pest-Testing","юнит-тесты","функциональные тесты","инструмент Pest","разработка программного обеспечения","автоматизированное тестирование","ИИ Агенты"],"ar":["اختبار الحشرات","اختبارات الوحدات","اختبارات الموارد","أداة الحشرات","تطوير البرمجيات","اختبارات آلية","أدوات الذكاء الاصطناعي"]}},"owner":"pockfojoh","repo":"alumnos","repoPath":"pockfojoh/alumnos","stars":0,"forks":0,"updatedAt":"2026-03-07T12:46:33.690Z","topics":[],"category":"community","skillMd":{"name":"pest-testing","description":">-","bodyPreview":"# Pest Testing 3\n\n## When to Apply\n\nActivate this skill when:\n- Creating new tests (unit or feature)\n- Modifying existing tests\n- Debugging test failures\n- Working with datasets, mocking, or test organization\n- Writing architecture tests\n\n## Documentation\n\nUse `search-docs` for detailed Pest 3 patterns and documentation.\n\n## Basic Usage\n\n### Creating Tests\n\nAll tests must be written using Pest. Use `php artisan make:test --pest {name}`.\n\n### Test Organization\n\n- Tests live in the `tests/Feature`","body":"# Pest Testing 3\n\n## When to Apply\n\nActivate this skill when:\n- Creating new tests (unit or feature)\n- Modifying existing tests\n- Debugging test failures\n- Working with datasets, mocking, or test organization\n- Writing architecture tests\n\n## Documentation\n\nUse `search-docs` for detailed Pest 3 patterns and documentation.\n\n## Basic Usage\n\n### Creating Tests\n\nAll tests must be written using Pest. Use `php artisan make:test --pest {name}`.\n\n### Test Organization\n\n- Tests live in the `tests/Feature` and `tests/Unit` directories.\n- Do NOT remove tests without approval - these are core application code.\n- Test happy paths, failure paths, and edge cases.\n\n### Basic Test Structure\n\n<code-snippet name=\"Basic Pest Test Example\" lang=\"php\">\n\nit(''is true'', function () {\n    expect(true)->toBeTrue();\n});\n\n</code-snippet>\n\n### Running Tests\n\n- Run minimal tests with filter before finalizing: `php artisan test --compact --filter=testName`.\n- Run all tests: `php artisan test --compact`.\n- Run file: `php artisan test --compact tests/Feature/ExampleTest.php`.\n\n## Assertions\n\nUse specific assertions (`assertSuccessful()`, `assertNotFound()`) instead of `assertStatus()`:\n\n<code-snippet name=\"Pest Response Assertion\" lang=\"php\">\n\nit(''returns all'', function () {\n    $this->postJson(''/api/docs'', [])->assertSuccessful();\n});\n\n</code-snippet>\n\n| Use | Instead of |\n|-----|------------|\n| `assertSuccessful()` | `assertStatus(200)` |\n| `assertNotFound()` | `assertStatus(404)` |\n| `assertForbidden()` | `assertStatus(403)` |\n\n## Mocking\n\nImport mock function before use: `use function Pest\\Laravel\\mock;`\n\n## Datasets\n\nUse datasets for repetitive tests (validation rules, etc.):\n\n<code-snippet name=\"Pest Dataset Example\" lang=\"php\">\n\nit(''has emails'', function (string $email) {\n    expect($email)->not->toBeEmpty();\n})->with([\n    ''james'' => ''james@laravel.com'',\n    ''taylor'' => ''taylor@laravel.com'',\n]);\n\n</code-snippet>\n\n## Pest 3 Features\n\n### Architecture Testing\n\nPest 3 includes architecture testing to enforce code conventions:\n\n<code-snippet name=\"Architecture Test Example\" lang=\"php\">\n\narch(''controllers'')\n    ->expect(''App\\Http\\Controllers'')\n    ->toExtendNothing()\n    ->toHaveSuffix(''Controller'');\n\narch(''models'')\n    ->expect(''App\\Models'')\n    ->toExtend(''Illuminate\\Database\\Eloquent\\Model'');\n\narch(''no debugging'')\n    ->expect([''dd'', ''dump'', ''ray''])\n    ->not->toBeUsed();\n\n</code-snippet>\n\n### Type Coverage\n\nPest 3 provides improved type coverage analysis. Run with `--type-coverage` flag.\n\n## Common Pitfalls\n\n- Not importing `use function Pest\\Laravel\\mock;` before using mock\n- Using `assertStatus(200)` instead of `assertSuccessful()`\n- Forgetting datasets for repetitive validation tests\n- Deleting tests without approval"},"lastSynced":"2026-03-07T13:00:41.874Z","agentAnalysis":{"suitability":{"en":"Perfect for PHP-based AI Agents needing streamlined testing workflows with Pest 3","zh":"非常适合需要使用Pest 3简化测试工作流的PHP基于的AI代理","ja":"Pest 3を使用してテストワークフローを簡素化する必要があるPHPベースのAIエージェントに最適","ko":"Pest 3를 사용하여 테스트 워크플ロー를 간소화해야 하는 PHP 기반의 AI 에이전트에 적합","es":"Perfecto para agentes de inteligencia artificial basados en PHP que necesitan flujos de trabajo de prueba optimizados con Pest 3","fr":"Parfait pour les agents d''intelligence artificielle basés sur PHP qui nécessitent des flux de travail de test rationalisés avec Pest 3","de":"Perfekt für PHP-basierte KI-Agents, die optimierte Test-Workflows mit Pest 3 benötigen","pt":"Perfeito para Agentes de IA baseados em PHP que necessitam de fluxos de trabalho de teste otimizados com Pest 3","ru":"Идеально подходит для агентов ИИ на основе PHP, которым требуются оптимизированные рабочие процессы тестирования с помощью Pest 3","ar":"مثالي لعميل الذكاء الاصطناعي الذي يعتمد على PHP والذي يحتاج إلى تدفقات عمل اختبار مبسطة مع Pest 3"},"recommendation":{"en":"Empowers agents to create and manage tests using Pest, providing a comprehensive testing framework with features like test organization, mocking, and dataset management, all accessible via the `php artisan make:test --pest` command","zh":"赋予代理创建和管理测试的能力，提供了一个全面的测试框架，包括测试组织、模拟和数据集管理等功能，所有这些都可以通过`php artisan make:test --pest`命令访问","ja":"エージェントがテストを作成、管理できるようにし、テストの組織化、モッキング、データセット管理などの機能を備えた包括的なテストフレームワークを提供し、すべてこれらは`php artisan make:test --pest`コマンド経由でアクセス可能","ko":"에이전트가 테스트를 생성하고 관리할 수 있게 하며, 테스트 조직, 모의, 데이터셋 관리 등의 기능을 갖춘 포괄적인 테스트 프레임워크를 제공하며, 모두 `php artisan make:test --pest` 명령을 통해 접근할 수 있음","es":"Permite a los agentes crear y gestionar pruebas utilizando Pest, proporcionando un marco de prueba integral con características como la organización de pruebas, la simulación y la gestión de conjuntos de datos, todo accesible a través del comando `php artisan make:test --pest`","fr":"Permet aux agents de créer et de gérer des tests en utilisant Pest, fournissant un cadre de test complet avec des fonctionnalités telles que l''organisation des tests, la simulation et la gestion des jeux de données, le tout accessible via la commande `php artisan make:test --pest`","de":"Ermöglicht es den Agents, Tests mit Pest zu erstellen und zu verwalten, und bietet ein umfassendes Test-Framework mit Funktionen wie Testorganisation, Mocking und Datenverwaltung, alles zugänglich über den Befehl `php artisan make:test --pest`","pt":"Habilita os agentes a criar e gerenciar testes usando Pest, fornecendo um framework de testes abrangente com recursos como organização de testes, simulação e gerenciamento de conjuntos de dados, todos acessíveis via comando `php artisan make:test --pest`","ru":"Позволяет агентам создавать и управлять тестами с помощью Pest, предоставляя комплексный фреймворк для тестирования с функциями, такими как организация тестов,模окирование и управление наборами данных, все доступно через команду `php artisan make:test --pest`","ar":"تمكين الوكلاء من إنشاء وادارة الاختبارات باستخدام Pest ، وتوفر إطار اختبار شامل مع ميزات مثل تنظيم الاختبارات وتقليد وإدارة مجموعات البيانات ، وكلها يمكن الوصول إليها عبر الأمر `php artisan make:test --pest`"},"useCases":{"en":["Creating new unit or feature tests with Pest 3","Debugging test failures and modifying existing tests","Organizing tests in the `tests/Feature` directory","Writing architecture tests with Pest"],"zh":["使用Pest 3创建新的单元或功能测试","调试测试失败并修改现有测试","在`tests/Feature`目录中组织测试","使用Pest编写架构测试"],"ja":["Pest 3を使用して新しいユニットまたは機能テストを作成する","テストの失敗をデバッグして既存のテストを変更する","`tests/Feature`ディレクトリでテストを組織する","Pestを使用してアーキテクチャテストを書く"],"ko":["Pest 3를 사용하여 새로운 유닛 또는 기능 테스트를 생성하는 것","테스트 실패를 디버깅하고 기존 테스트를 수정하는 것","`tests/Feature` 디렉토리에서 테스트를 조직하는 것","Pest를 사용하여 아키텍처 테스트를 작성하는 것"],"es":["Crear nuevas pruebas unitarias o de características con Pest 3","Depurar fallos de pruebas y modificar pruebas existentes","Organizar pruebas en el directorio `tests/Feature`","Escribir pruebas de arquitectura con Pest"],"fr":["Créer de nouvelles tests unitaires ou de fonctionnalités avec Pest 3","Déboguer les échecs de test et modifier les tests existants","Organiser les tests dans le répertoire `tests/Feature`","Écrire des tests d''architecture avec Pest"],"de":["Erstellen neuer Unit- oder Feature-Tests mit Pest 3","Fehler bei Tests debuggen und vorhandene Tests ändern","Tests im `tests/Feature`-Verzeichnis organisieren","Architektur-Tests mit Pest schreiben"],"pt":["Criar novos testes unitários ou de recursos com Pest 3","Depurar falhas de teste e modificar testes existentes","Organizar testes no diretório `tests/Feature`","Escrever testes de arquitetura com Pest"],"ru":["Создание новых юнит-тестов или функциональных тестов с помощью Pest 3","Отладка неудач тестов и изменение существующих тестов","Организация тестов в каталоге `tests/Feature`","Написание архитектурных тестов с помощью Pest"],"ar":["إنشاء اختبارات وحدة جديدة أو ميزات مع Pest 3","تصحيح اختبار الفشل وتعديل الاختبارات الحالية","تنظيم الاختبارات في الدليل `tests/Feature`","كتابة اختبارات الهندسة المعمارية مع Pest"]},"limitations":{"en":["Requires PHP environment","Pest 3 specific","Limited to PHP-based applications"],"zh":["需要PHP环境","特定于Pest 3","仅限于PHP基于应用"],"ja":["PHP環境が必要","Pest 3に特有","PHPベースのアプリケーションに限定"],"ko":["PHP 환경이 필요함","Pest 3에 특정됨","PHP 기반 응용 프로그램에만 제한됨"],"es":["Requiere entorno PHP","Específico de Pest 3","Limitado a aplicaciones basadas en PHP"],"fr":["Nécessite un environnement PHP","Spécifique à Pest 3","Limité aux applications basées sur PHP"],"de":["Benötigt PHP-Umgebung","Pest 3-spezifisch","Begrenzt auf PHP-basierte Anwendungen"],"pt":["Requer ambiente PHP","Específico do Pest 3","Limitado a aplicações baseadas em PHP"],"ru":["Требуется среда PHP","Специфичен для Pest 3","Ограничен для приложений на основе PHP"],"ar":["يتطلب بيئة PHP","محدد لبرنامج Pest 3","محدود لتطبيقات قائمة على PHP"]},"version":4},"contentHash":"05bb6cfd7acdeeaa3c2b2317ed71bb6fe329eafd204a072cfced0157e6ebd473","qualityScore":23}');
