INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('pockfojoh/alumnos/pest-testing', 'pest-testing', 'pockfojoh', 'alumnos', 'community', 'pest-testing pockfojoh alumnos community Pest-Testing is a skill that helps developers create and manage tests for their applications. It benefits developers by providing a streamlined testing workflow. Pest Testing是用于创建和管理测试的工具，支持Pest 3模式和php artisan make:test Pest Testingはテストの作成と管理に使用されるツールで、Pest 3パターンとphp artisan make:testをサポート Pest Testing은 테스트 생성 및 관리에 사용되는 도구로 Pest 3 패턴 및 php artisan make:test를 지원 Pest Testing es una herramienta para crear y depurar pruebas de unidad y características en proyectos de desarrollo Pest Testing est un outil pour créer et déboguer des tests d''unités et de fonctionnalités dans les projets de développement Pest Testing ist ein Tool zur Erstellung und Fehlerbehebung von Einheits- und Funktionsprüfungen in Entwicklungsprojekten O Pest-Testing é uma ferramenta para criar e gerenciar testes de unidade e recursos de forma eficiente Pest-Testing - это инструмент для создания и управления юнит-тестами и функциональными тестами اختبار الحشرات هو أداة لإنشاء وإدارة اختبارات الوحدات والموارد بفعالية how to use pest-testing pest-testing setup guide pest-testing vs phpunit pest-testing install what is pest-testing pest-testing alternative pest-testing tutorial pest-testing best practices pest-testing for laravel Pest Testing AIエージェント工具 php artisan make:test Pest 3模式 测试工具 测试管理 数据集 模拟 测试组织 Creates tests using the `php artisan make:test --pest {name}` command Organizes tests in the `tests/Feature` directory Supports debugging test failures and modifying existing tests Enables writing architecture tests using Pest 3 patterns Integrates with `search-docs` for detailed documentation and patterns Pest-testing is a testing framework that allows developers to write and organize tests using the Pest syntax.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('t-kuni/relavue-er/tasks-make-task-list', 'community', 't-kuni', 'relavue-er', 't-kuni/relavue-er', 'tasks-make-task-list', 0, 0, 23, '2026-02-27T01:51:08.697Z', '2026-02-27T03:52:48.259Z', 'b122a02f6899b6587b1f7d1591e8eab85bc9bc4d9b05c65a5e76b5d6cef3d248', '{"id":"t-kuni/relavue-er/tasks-make-task-list","name":"tasks-make-task-list","description":{"zh":"RelavueER 是一个工具，用于逆向 ER 图表从数据库，并允许您在浏览器中交互式地查看它们。它可以帮助您更好地理解数据库结构。","ja":"RelavueER は、データベースから ER 図を逆にし、ブラウザで交互的に表示するためのツールです。データベースの構造を理解するのに役立ちます。","ko":"RelavueER 는 데이터베이스에서 ER 图를逆으로하고 브라우저에서 상호작용적으로 표시하는 도구입니다. 데이터베이스의 구조를 이해하는 데 도움이 됩니다.","es":"RelavueER es una herramienta que invierte diagramas ER desde bases de datos y los muestra interactivamente en tu navegador con facilidad","fr":"RelavueER est un outil qui inverse les diagrammes ER à partir de bases de données et les affiche de manière interactive dans votre navigateur avec facilité","de":"RelavueER ist ein Tool, das ER-Diagramme aus Datenbanken umkehrt und sie interaktiv in Ihrem Browser mit Leichtigkeit anzeigt","pt":"RelavueER é uma ferramenta que reverte diagramas ER de bancos de dados e os exibe interativamente no navegador com facilidade","ru":"RelavueER - это инструмент, который обращает ER-диаграммы баз данных и отображает их интерактивно в браузере с легкостью","ar":"RelavueER هي أداة تعكس الرسوم البيانية ER للقواعد وتعرضها بشكل تفاعلي في المتصفح بسهولة","en":"RelavueER is a tool that reverses ER diagrams from databases and allows you to view them interactively in your browser with ease."},"seo":{"title":{"zh":"RelavueER AI Agent - 任务列表工具","ja":"RelavueER AIエージェント - タスクリストを作成","ko":"RelavueER AI Agent - タスク 리스트 생성 도구","es":"Herramientas de AI: tasks-make-task-list con RelavueER","fr":"Outils d''IA: tasks-make-task-list avec RelavueER","de":"KI-Tools: tasks-make-task-list mit RelavueER","