INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('t-kuni/relavue-er/tasks-make-task-list', 'tasks-make-task-list', 't-kuni', 'relavue-er', 'community', 'tasks-make-task-list t-kuni relavue-er community RelavueER 是一个工具，用于逆向 ER 图表从数据库，并允许您在浏览器中交互式地查看它们。它可以帮助您更好地理解数据库结构。 RelavueER は、データベースから ER 図を逆にし、ブラウザで交互的に表示するためのツールです。データベースの構造を理解するのに役立ちます。 RelavueER 는 데이터베이스에서 ER 图를逆으로하고 브라우저에서 상호작용적으로 표시하는 도구입니다. 데이터베이스의 구조를 이해하는 데 도움이 됩니다. RelavueER es una herramienta que invierte diagramas ER desde bases de datos y los muestra interactivamente en tu navegador con facilidad RelavueER est un outil qui inverse les diagrammes ER à partir de bases de données et les affiche de manière interactive dans votre navigateur avec facilité RelavueER ist ein Tool, das ER-Diagramme aus Datenbanken umkehrt und sie interaktiv in Ihrem Browser mit Leichtigkeit anzeigt RelavueER é uma ferramenta que reverte diagramas ER de bancos de dados e os exibe interativamente no navegador com facilidade RelavueER - это инструмент, который обращает ER-диаграммы баз данных и отображает их интерактивно в браузере с легкостью RelavueER هي أداة تعكس الرسوم البيانية ER للقواعد وتعرضها بشكل تفاعلي في المتصفح بسهولة RelavueER is a tool that reverses ER diagrams from databases and allows you to view them interactively in your browser with ease. RelavueER AI 工具 ER 图表逆向 数据库结构理解 how to use RelavueER what is RelavueER RelavueER is a tool that reverses ER diagrams from databases and allows you to view them interactively in your browser with ease.');
